_boat_norm_slug_map_cache: dict = {}
_boat_norm_slug_map_cache_at: float = 0.0
_BOAT_NORM_SLUG_CACHE_TTL_SEC = 300.0


def _boat_profile_slug_for_name(boat_name: str, norm_slug_map: Optional[dict] = None) -> Optional[str]:
    """Slug for /boat-name/{slug} — map lookup first, then deterministic slug from ladder text."""
    bn = str(boat_name or "").strip()
    if not bn or _boat_names_directory is None:
        return None
    m = norm_slug_map if norm_slug_map is not None else _load_boat_norm_slug_map()
    slug = (m or {}).get(bn.lower())
    if slug:
        return slug
    slug = _boat_names_directory.boat_name_slug(bn)
    return slug or None


def _load_boat_norm_slug_map() -> dict:
    """Cached boat norm -> slug map for profile links (5 min TTL)."""
    global _boat_norm_slug_map_cache, _boat_norm_slug_map_cache_at
    now = time.time()
    if _boat_norm_slug_map_cache and (now - _boat_norm_slug_map_cache_at) < _BOAT_NORM_SLUG_CACHE_TTL_SEC:
        return _boat_norm_slug_map_cache
    if _boat_names_directory is None or not table_exists("results"):
        return _boat_norm_slug_map_cache or {}
    try:
        loaded = _boat_names_directory.load_boat_norm_slug_map(
            table_exists=table_exists,
            get_db_connection=get_db_connection,
            return_db_connection=return_db_connection,
        )
        if loaded:
            _boat_norm_slug_map_cache = loaded
            _boat_norm_slug_map_cache_at = now
        return loaded or _boat_norm_slug_map_cache or {}
    except Exception:
        return _boat_norm_slug_map_cache or {}


def _boat_name_display_html(boat_name: str, norm_slug_map: Optional[dict] = None) -> str:
    bn = str(boat_name or "").strip()
    if not bn:
        return ""
    if _boat_names_directory is not None:
        slug = _boat_profile_slug_for_name(bn, norm_slug_map)
        if slug:
            return _boat_names_directory.boat_name_link_html(bn, {bn.lower(): slug})
    return html_module.escape(bn)


