@app.get("/boat-name/{slug}", response_class=HTMLResponse)
def serve_boat_name_page(slug: str):
    """Boat name profile: regattas sailed + sailors."""
    if _boat_names_directory is None:
        raise HTTPException(status_code=503, detail="boat names module not available")
    index = _boat_names_directory.load_boat_name_index(
        table_exists=table_exists,
        get_db_connection=get_db_connection,
        return_db_connection=return_db_connection,
    )
    resolved = _boat_names_directory.resolve_boat_name(slug, index)
    if not resolved:
        resolved = _boat_names_directory.resolve_boat_name_from_db(
            slug,
            table_exists=table_exists,
            get_db_connection=get_db_connection,
            return_db_connection=return_db_connection,
        )
    if not resolved:
        return HTMLResponse(
            content=_boat_names_directory.BOAT_404_HTML,
            status_code=404,
            media_type="text/html",
        )
    display, norm = resolved
    canonical_slug = _boat_names_directory.boat_name_slug(display)
    if canonical_slug and slug.strip().lower() != canonical_slug:
        return RedirectResponse(url=f"/boat-name/{canonical_slug}", status_code=301)
    regattas, sailors, class_name, class_id, class_logo = _boat_names_directory.load_boat_name_detail(
        norm,
        table_exists=table_exists,
        get_db_connection=get_db_connection,
        return_db_connection=return_db_connection,
        format_date_range=_format_event_date_range,
    )
    result_rows = _boat_names_directory.load_boat_result_rows(
        norm,
        table_exists=table_exists,
        get_db_connection=get_db_connection,
        return_db_connection=return_db_connection,
    )
    html = _boat_names_directory.detail_page_html(
        display,
        norm,
        result_rows,
        _seo_discovery_block_html(),
        _sailor_canonical_slug,
        class_name=class_name,
        class_id=class_id,
        class_logo=class_logo,
    )
    return HTMLResponse(html)


