@app.get("/traffic-v2/", response_class=HTMLResponse)
def traffic_dashboard_page(request: Request):
    import os
    from urllib.parse import quote

    if not _session_role_is_super_admin(request):
        return_to = quote(str(request.url.path or "/traffic"), safe="")
        session_token = request.cookies.get("session") or ""
        if not session_token:
            return RedirectResponse(url=f"/login.html?returnTo={return_to}", status_code=307)
        return HTMLResponse(
            """<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Traffic Access Required</title>
  <style>
    body { margin: 0; font-family: Arial, sans-serif; background: #f4f7fb; color: #08184a; }
    .wrap { min-height: 100vh; display: flex; align-items: center; justify-content: center; padding: 24px; }
    .card { width: 100%; max-width: 540px; background: #fff; border: 2px solid #08184a; border-radius: 14px; padding: 24px; box-shadow: 0 18px 40px rgba(8,24,74,0.12); }
    h1 { margin: 0 0 10px; font-size: 28px; line-height: 1.1; }
    p { margin: 0 0 14px; line-height: 1.5; color: #334155; }
    .actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
    .btn { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 16px; border-radius: 10px; text-decoration: none; font-weight: 800; }
    .btn-primary { background: #08184a; color: #fff; }
    .btn-secondary { background: #fff; color: #08184a; border: 1px solid #08184a; }
  </style>
</head>
<body>
  <div class="wrap">
    <div class="card">
      <h1>Traffic Access Required</h1>
      <p>This page is restricted to super admin access.</p>
      <p>Your current session does not have permission to open the traffic dashboard.</p>
      <div class="actions">
        <a class="btn btn-primary" href="/admin/dashboard">Admin Dashboard</a>
        <a class="btn btn-secondary" href="/">Home</a>
      </div>
    </div>
  </div>
</body>
</html>""",
            status_code=403,
            headers={"Cache-Control": "no-store"},
        )
    blank_path = os.path.join(STATIC_DIR, "blank.html")
    frag_main = os.path.join(STATIC_DIR, "traffic_visual_main.html")
    frag_script = os.path.join(STATIC_DIR, "traffic_visual_script.js")
    if not os.path.isfile(blank_path):
        raise HTTPException(status_code=404, detail="blank.html not found")
    if not os.path.isfile(frag_main) or not os.path.isfile(frag_script):
        raise HTTPException(status_code=404, detail="traffic visual fragments missing")
    with open(blank_path, "r", encoding="utf-8", errors="replace") as f:
        html = f.read()
    html = html.replace(
        '  <script src="/js/blank-landing-header.js"></script>\n',
        "",
        1,
    )
    with open(frag_main, "r", encoding="utf-8", errors="replace") as f:
        traffic_main = f.read()
    with open(frag_script, "r", encoding="utf-8", errors="replace") as f:
        script_body = f.read()
    html = html.replace("<title>Search — SailingSA</title>", "<title>Traffic Visual — SailingSA</title>", 1)
    if 'href="/css/main.css"' not in html:
        html = html.replace(
            "</head>",
            '  <link rel="stylesheet" href="/css/main.css">\n'
            '  <script src="/js/api.js"></script>\n'
            '  <script src="/js/session.js"></script>\n'
            "</head>",
            1,
        )
    html = html.replace(
        '''  <nav class="blank-drawer" id="navDrawer" aria-label="Site menu" hidden aria-hidden="true">
    <a href="/">Home</a>
    <a href="/sailors">Sailors</a>
    <a href="/regattas">Regattas</a>
    <a href="/classes">Classes</a>
    <a href="/clubs">Clubs</a>
    <a href="/about">About</a>
  </nav>''',
        '''  <nav class="blank-drawer" id="navDrawer" aria-label="Site menu" hidden aria-hidden="true">
    <a href="/traffic">Traffic analytics</a>
    <a href="/admin/dashboard">Admin dashboard</a>
    <a href="/admin/dashboard-v10">Dashboard v10</a>
    <a href="/admin/review">Data review</a>
    <a href="/">Home</a>
    <a href="/sailors">Sailors</a>
    <a href="/regattas">Regattas</a>
    <a href="/classes">Classes</a>
    <a href="/clubs">Clubs</a>
    <a href="/about">About</a>
  </nav>''',
        1,
    )
    i0 = html.find("    <section class=\"card blank-stats-wrap\"")
    i1 = html.find("  <div class=\"blank-overlay\"")
    if i0 < 0 or i1 < 0:
        raise HTTPException(status_code=500, detail="blank.html layout changed; cannot splice traffic visual")
    html = html[:i0] + traffic_main + html[i1:]
    s0 = html.find("  <script>\n(function () {")
    if s0 < 0:
        s0 = html.find("  <script>\r\n(function () {")
    s_end = html.find("</script>", s0)
    if s0 < 0 or s_end < 0:
        raise HTTPException(status_code=500, detail="blank.html script block not found")
    html = html[:s0] + "  <script>\n" + script_body + "\n  </script>" + html[s_end + len("</script>") :]
    return HTMLResponse(content=html, headers={"Cache-Control": "no-store"})


@app.get("/traffic-visual", response_class=HTMLResponse)
@app.get("/traffic-visual/", response_class=HTMLResponse)
def traffic_visual_page(request: Request):
    import os

    _traffic_require_super_admin(request)
    blank_path = os.path.join(STATIC_DIR, "blank.html")
    frag_main = os.path.join(STATIC_DIR, "traffic_visual_main.html")
    frag_script = os.path.join(STATIC_DIR, "traffic_visual_script.js")
    if not os.path.isfile(blank_path):
        raise HTTPException(status_code=404, detail="blank.html not found")
    if not os.path.isfile(frag_main) or not os.path.isfile(frag_script):
        raise HTTPException(status_code=404, detail="traffic visual fragments missing")
    with open(blank_path, "r", encoding="utf-8", errors="replace") as f:
        html = f.read()
    html = html.replace(
        '  <script src="/js/blank-landing-header.js"></script>\n',
        "",
        1,
    )
    with open(frag_main, "r", encoding="utf-8", errors="replace") as f:
        main_body = f.read()
