def _traffic_runtime():
    d = _traffic_analytics_deps()
    ta = d.pop("ta")
    return ta, ta.get_runtime(**d)


if not getattr(app.state, "_traffic_analytics_middleware_installed", False):
    app.state._traffic_analytics_middleware_installed = True

    @app.middleware("http")
    async def traffic_analytics_middleware(request: Request, call_next):
        ta, runtime = _traffic_runtime()
        visitor_id = runtime.ensure_visitor_id(request.cookies.get(ta.VISITOR_COOKIE_NAME) or "")
        role = _get_session_role(request) or ""
        user_agent = request.headers.get("user-agent", "")
        path = request.url.path or "/"
        if runtime.should_skip(path=path, method=request.method, user_agent=user_agent, role=role):
            return await call_next(request)

        response = await call_next(request)
        try:
            headers = ta.request_headers_to_dict(request.headers)
            event = runtime.build_event(
                request_url=str(request.url),
                method=request.method,
                status_code=getattr(response, "status_code", 0),
                session_id=request.cookies.get("session") or "",
                visitor_id=visitor_id,
                sas_id=_get_session_sas_id(request) or "",
                referrer=request.headers.get("referer", ""),
                user_agent=user_agent,
                headers=headers,
            )
            runtime.enqueue(event)
            if not request.cookies.get(ta.VISITOR_COOKIE_NAME):
                response.set_cookie(value=visitor_id, **ta.cookie_params())
        except Exception:
            pass
        return response


