def _traffic_runtime():
    d = _traffic_analytics_deps()
    ta = d.pop("ta")
    return ta, ta.get_runtime(**d)


if not getattr(app.state, "_traffic_analytics_middleware_installed", False):
    app.state._traffic_analytics_middleware_installed = True

    @app.middleware("http")
    async def traffic_analytics_middleware(request: Request, call_next):
        ta, runtime = _traffic_runtime()
        visitor_id = runtime.ensure_visitor_id(request.cookies.get(ta.VISITOR_COOKIE_NAME) or "")
        role = _get_session_role(request) or ""
        user_agent = request.headers.get("user-agent", "")
        path = request.url.path or "/"
        if runtime.should_skip(path=path, method=request.method, user_agent=user_agent, role=role):
            return await call_next(request)

        response = await call_next(request)
        try:
            headers = ta.request_headers_to_dict(request.headers)
            event = runtime.build_event(
                request_url=str(request.url),
                method=request.method,
                status_code=getattr(response, "status_code", 0),
                session_id=request.cookies.get("session") or "",
                visitor_id=visitor_id,
                sas_id=_get_session_sas_id(request) or "",
                referrer=request.headers.get("referer", ""),
                user_agent=user_agent,
                headers=headers,
            )
            runtime.enqueue(event)
            if not request.cookies.get(ta.VISITOR_COOKIE_NAME):
                response.set_cookie(value=visitor_id, **ta.cookie_params())
        except Exception:
            pass
        return response


def _traffic_require_super_admin(request: Request) -> None:
    if not _session_role_is_super_admin(request):
        raise HTTPException(status_code=403, detail="Super admin access required.")


@app.get("/traffic", response_class=HTMLResponse)
@app.get("/traffic/", response_class=HTMLResponse)
def traffic_dashboard_page(request: Request):
    import os

    _traffic_require_super_admin(request)
    blank_path = os.path.join(STATIC_DIR, "blank.html")
    frag_main = os.path.join(STATIC_DIR, "traffic_dashboard_main.html")
    frag_script = os.path.join(STATIC_DIR, "traffic_dashboard_script.js")
    if not os.path.isfile(blank_path):
        raise HTTPException(status_code=404, detail="blank.html not found")
    if not os.path.isfile(frag_main) or not os.path.isfile(frag_script):
        raise HTTPException(status_code=404, detail="traffic dashboard fragments missing")
    with open(blank_path, "r", encoding="utf-8", errors="replace") as f:
        html = f.read()
    html = html.replace(
        '  <script src="/js/blank-landing-header.js"></script>\n',
        "",
        1,
    )
    with open(frag_main, "r", encoding="utf-8", errors="replace") as f:
        traffic_main = f.read()
    with open(frag_script, "r", encoding="utf-8", errors="replace") as f:
        script_body = f.read()
    html = html.replace("<title>Search — SailingSA</title>", "<title>Traffic Analytics — SailingSA</title>", 1)
    if 'href="/css/main.css"' not in html:
        html = html.replace(
            "</head>",
            '  <link rel="stylesheet" href="/css/main.css">\n'
            '  <script src="/js/api.js"></script>\n'
            '  <script src="/js/session.js"></script>\n'
            "</head>",
            1,
        )
    html = html.replace(
        '''  <nav class="blank-drawer" id="navDrawer" aria-label="Site menu" hidden aria-hidden="true">
    <a href="/">Home</a>
    <a href="/sailors">Sailors</a>
    <a href="/regattas">Regattas</a>
    <a href="/classes">Classes</a>
    <a href="/clubs">Clubs</a>
    <a href="/about">About</a>
  </nav>''',
        '''  <nav class="blank-drawer" id="navDrawer" aria-label="Site menu" hidden aria-hidden="true">
    <a href="/traffic">Traffic analytics</a>
    <a href="/admin/dashboard">Admin dashboard</a>
    <a href="/admin/dashboard-v10">Dashboard v10</a>
    <a href="/admin/review">Data review</a>
    <a href="/">Home</a>
    <a href="/sailors">Sailors</a>
    <a href="/regattas">Regattas</a>
    <a href="/classes">Classes</a>
    <a href="/clubs">Clubs</a>
    <a href="/about">About</a>
  </nav>''',
        1,
    )
    i0 = html.find("    <section class=\"card blank-stats-wrap\"")
    i1 = html.find("  <div class=\"blank-overlay\"")
    if i0 < 0 or i1 < 0:
        raise HTTPException(status_code=500, detail="blank.html layout changed; cannot splice traffic dashboard")
    html = html[:i0] + traffic_main + html[i1:]
    s0 = html.find("  <script>\n(function () {")
    if s0 < 0:
        s0 = html.find("  <script>\r\n(function () {")
    s_end = html.find("</script>", s0)
    if s0 < 0 or s_end < 0:
        raise HTTPException(status_code=500, detail="blank.html script block not found")
    html = html[:s0] + "  <script>\n" + script_body + "\n  </script>" + html[s_end + len("</script>") :]
    return HTMLResponse(content=html, headers={"Cache-Control": "no-store"})


