def _traffic_require_super_admin(request: Request) -> None:
    if _session_role_is_super_admin(request):
        return
    session_token = request.cookies.get("session") or ""
    if not session_token:
        from urllib.parse import quote
        return_to = quote(str(request.url.path or "/traffic"), safe="")
        raise HTTPException(status_code=307, detail="Redirecting to login.", headers={"Location": f"/login.html?returnTo={return_to}"})
    raise HTTPException(status_code=403, detail="Super admin access required.")



