    try:
        d = _sponsor_profiles_deps()
        sp = d.pop("sp")
        status_code, body = sp.sponsors_index_html(
            canonical_base_url=d.pop("canonical_base_url")(),
            **d,
        )
        return HTMLResponse(body, status_code=status_code)
    except Exception as e:
        return HTMLResponse(
            "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>Sponsors</title></head>"
            "<body><h1>Sponsors</h1><pre>"
            + html_module.escape(f"{type(e).__name__}: {e}")
            + "</pre></body></html>",
            status_code=500,
        )


