def _regatta_admin_1_deps():
    import sys
    from pathlib import Path

    _deploy = Path(__file__).resolve().parent.parent / "deploy"
    if _deploy.is_dir() and str(_deploy) not in sys.path:
        sys.path.insert(0, str(_deploy))
    import regatta_admin_1 as ra1

    return {
        "ra1": ra1,
        "get_db_connection": get_db_connection,
        "return_db_connection": return_db_connection,
        "column_exists": column_exists,
    }


@app.get("/regatta-admin-1", response_class=HTMLResponse)
def regatta_admin_1_page():
    try:
        d = _regatta_admin_1_deps()
        ra1 = d.pop("ra1")
        rows = ra1.load_rows(**d)
        return HTMLResponse(ra1.page_html(rows))
    except Exception as e:
        return HTMLResponse(
            "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>Regatta Admin 1</title></head>"
            "<body><h1>Regatta Admin 1</h1><pre>"
            + html_module.escape(f"{type(e).__name__}: {e}")
            + "</pre></body></html>"
        )


@app.get("/api/regatta-admin-1/source-preview")
def regatta_admin_1_source_preview(url: str):
    d = _regatta_admin_1_deps()
    ra1 = d.pop("ra1")
    try:
        data, mime, name = ra1.fetch_preview_source(url)
    except Exception as e:
        return Response(
            content=(
                "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>Source Preview</title></head>"
                "<body style=\"font-family:Arial,sans-serif;padding:20px\"><h1>Source Preview Unavailable</h1><pre>"
                + html_module.escape(str(e))
                + "</pre></body></html>"
            ),
            media_type="text/html",
            status_code=400,
        )
    headers = {"Content-Disposition": f'inline; filename="{name or "source"}"'}
    return Response(content=data, media_type=mime, headers=headers)

