_EVENTS_PAGE_HTML_CACHE = {"html": None, "ts": 0.0}
_EVENTS_PAGE_HTML_TTL_SEC = 120.0


def _events_page_html_cached() -> str:
    """Short TTL cache so crawlers/health checks do not rebuild 1000+ past cards every hit."""
    now = time.time()
    ent = _EVENTS_PAGE_HTML_CACHE
    if ent.get("html") and (now - float(ent.get("ts") or 0)) < _EVENTS_PAGE_HTML_TTL_SEC:
        return ent["html"]
    html = _events_page_html()
    _EVENTS_PAGE_HTML_CACHE["html"] = html
    _EVENTS_PAGE_HTML_CACHE["ts"] = now
    return html


