@app.get("/api/classes-with-boats")
def classes_with_boats():
    """Get classes that have registered boats, ordered by boat count."""
    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        cur.execute("""
            SELECT c.class_name, COUNT(DISTINCT bi.boat_id) as boat_count
            FROM classes c
            JOIN boat_identifiers bi ON bi.class_id = c.class_id AND bi.is_current = TRUE
            GROUP BY c.class_id, c.class_name
            HAVING COUNT(DISTINCT bi.boat_id) > 0
            ORDER BY COUNT(DISTINCT bi.boat_id) DESC, c.class_name
            LIMIT 50
        """)
        return [dict(r) for r in cur.fetchall()]
    except Exception as e:
        print(f"Error in classes_with_boats: {e}")
        return []
    finally:
        cur.close()
        return_db_connection(conn)

