@app.get("/regatta/{slug}/{fleet_class_slug}")
@app.head("/regatta/{slug}/{fleet_class_slug}")
def _regatta_class_short_segment(request: Request, slug: str, fleet_class_slug: str):
    """Legacy one extra path segment after /regatta/{slug}/.

    Fleet tails (block_id after ':', e.g. fast / slow) → **fleet_shell** `/regatta/{slug}-{tail}` — never `/class-*`.
    Otherwise → `/regatta/{slug}/class-{segment}` (single-class-style shortcut, e.g. 420).
    """
    t = (fleet_class_slug or "").strip()
    if not t or ".." in fleet_class_slug or "/" in fleet_class_slug:
        raise HTTPException(status_code=404, detail="Not found")
    low = t.lower()
    if low.endswith(".html") or low.endswith(".htm") or low.endswith(".json"):
        raise HTTPException(status_code=404, detail="Not found")
    reserved = frozenset(
        {"results", "class", "api", "edit", "admin", "embed", "iframe", "static", "assets", "podium"}
    )
    if low in reserved or low.startswith("results"):
        raise HTTPException(status_code=404, detail="Not found")
    if not re.match(r"^[a-zA-Z0-9][a-zA-Z0-9._-]*$", t):
        raise HTTPException(status_code=404, detail="Not found")
    slug_s = str(slug).strip()
    fleet_shell_candidate = f"{slug_s}-{t}"
    if _resolve_fleet_shell_public_slug(fleet_shell_candidate):
        return RedirectResponse(url=f"/regatta/{quote(fleet_shell_candidate, safe='')}", status_code=301)
    canon = f"/regatta/{quote(slug_s, safe='')}/class-{quote(t, safe='')}"
    return RedirectResponse(url=canon, status_code=301)


