# REQUEST PROFILING MIDDLEWARE
# ============================================================================

@app.middleware("http")
async def profile_requests(request: Request, call_next):
    """Profile all API requests to identify slow endpoints with request IDs"""
    req_id = get_request_id()
    endpoint = f"{request.method} {request.url.path}"
    start = time.time()
    _db_tls.db_query_count = 0
    _db_tls.borrowed_conns = []

    # Store request ID in request state for use in endpoints
    request.state.request_id = req_id

    print(f"[REQ {req_id}] → {endpoint}")

    try:
        response = await call_next(request)
        duration = time.time() - start
        status_code = response.status_code if hasattr(response, 'status_code') else 200
        n_queries = getattr(_db_tls, "db_query_count", 0)
        print(f"REQ {req_id}: total_db_queries={n_queries}", flush=True)
        log_endpoint_timing(req_id, endpoint, duration, status_code)
        return response
    except Exception as e:
        duration = time.time() - start
        n_queries = getattr(_db_tls, "db_query_count", 0)
        print(f"REQ {req_id}: total_db_queries={n_queries}", flush=True)
        log_endpoint_timing(req_id, f"{endpoint} [EXCEPTION: {str(e)}]", duration, status_code=500)
        raise
    finally:
        leaked = list(getattr(_db_tls, "borrowed_conns", []) or [])
        if leaked:
            print(f"[DB] reclaiming {len(leaked)} leaked conn(s) after {endpoint}", flush=True)
            for c in leaked:
                try:
                    return_db_connection(c)
                except Exception:
                    pass
        _db_tls.borrowed_conns = None

def _dir_nav_safe_path(v: str) -> str:
    s = str(v or "").strip()
    if not s.startswith("/"):
        return ""
    return s[:2000]


def _dir_nav_overlay_html(request: Request) -> str:
    prev_url = _dir_nav_safe_path(request.query_params.get("_dir_prev") or "")
    next_url = _dir_nav_safe_path(request.query_params.get("_dir_next") or "")
    home_url = _dir_nav_safe_path(request.query_params.get("_dir_home") or "")
    if not home_url:
        return ""
    prev_href = html_module.escape(prev_url or home_url)
    next_href = html_module.escape(next_url or home_url)
    home_href = html_module.escape(home_url)
    current_path = html_module.escape((request.url.path or "/")[:200])
    return (
        "<div id=\"dir-nav-overlay\" style=\"position:fixed;left:14px;bottom:14px;z-index:9999;"
        "display:flex;gap:8px;align-items:center;padding:10px 12px;border:1px solid #cbd5e1;"
        "border-radius:999px;background:rgba(255,255,255,.96);box-shadow:0 10px 28px rgba(15,23,42,.16);"
        "font-family:Arial,sans-serif;\">"
        f"<a href=\"{prev_href}\" style=\"display:inline-flex;align-items:center;justify-content:center;min-width:40px;height:36px;padding:0 12px;border-radius:999px;text-decoration:none;background:#eff6ff;color:#0b3b75;font-weight:700;\">&lt;</a>"
        f"<a href=\"{home_href}\" style=\"display:inline-flex;align-items:center;justify-content:center;height:36px;padding:0 14px;border-radius:999px;text-decoration:none;background:#0b3b75;color:#fff;font-weight:700;\">Directory</a>"
        f"<a href=\"{next_href}\" style=\"display:inline-flex;align-items:center;justify-content:center;min-width:40px;height:36px;padding:0 12px;border-radius:999px;text-decoration:none;background:#eff6ff;color:#0b3b75;font-weight:700;\">&gt;</a>"
        f"<span style=\"margin-left:4px;color:#475569;font-size:12px;max-width:42vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\">{current_path}</span>"
        "</div>"
    )


@app.middleware("http")
async def _directory_nav_overlay(request: Request, call_next):
    response = await call_next(request)
    if request.method != "GET":
        return response
    if request.url.path == "/directory":
        return response
    overlay = _dir_nav_overlay_html(request)
    if not overlay:
        return response
    if int(getattr(response, "status_code", 200) or 200) >= 300:
        return response
    if response.headers.get("content-encoding"):
        return response
    content_type = (response.headers.get("content-type") or "").lower()
    if "text/html" not in content_type:
        return response
    body = getattr(response, "body", b"")
    if not body:
        iterator = getattr(response, "body_iterator", None)
        if iterator is None:
            return response
        parts = []
        async for chunk in iterator:
            parts.append(chunk)
        body = b"".join(parts)
    if not body:
        return response
    try:
        html = body.decode("utf-8", "ignore")
    except Exception:
        return response
    last_idx = html.lower().rfind("</body>")
    if last_idx >= 0:
        html = html[:last_idx] + overlay + html[last_idx:]
    else:
        html += overlay
    headers = dict(response.headers)
    headers.pop("content-length", None)
    headers.pop("Content-Length", None)
    return HTMLResponse(content=html, status_code=response.status_code, headers=headers)

def q(sql, *args):
    """Execute query with connection pooling and profiling"""
    start = time.time()
    conn = None
    try:
        conn = get_db_connection()
        with conn.cursor() as cur:
            cur.execute(sql, args)
            result = cur.fetchall()
            duration = (time.time() - start) * 1000
            if duration > 200:
                print(f"[DB] ⚠️  SLOW QUERY took {duration:.2f}ms: {sql[:100]}...")
            return result
    finally:
        if conn:
            return_db_connection(conn)

def one(sql, *args):
    """Execute query and return single row with connection pooling"""
    start = time.time()
    conn = None
    try:
        conn = get_db_connection()
        with conn.cursor() as cur:
            cur.execute(sql, args)
            row = cur.fetchone()
            duration = time.time() - start  # Keep in seconds for logging
            
            # Full SQL tracing
            sql_trimmed = sql[:200] + "..." if len(sql) > 200 else sql
            params_str = str(args) if args else "()"
            print(f"[SQL] ({duration:.3f}s) {sql_trimmed} | params: {params_str}")
            
            # Log slow queries to file
            if duration > 0.5:
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                with open("slow_queries.log", "a") as f:
                    f.write(f"{timestamp} | {duration:.3f}s | {sql} | params: {params_str}\n")
                print(f"[SQL] ⚠️  SLOW QUERY ({duration:.3f}s) logged to slow_queries.log")
            
            if not row:
                raise HTTPException(status_code=404, detail="Not found")
            return row
    finally:
        if conn:
            return_db_connection(conn)

def qf(sql, *args):
    """Execute query with connection pooling"""
    start = time.time()
    conn = None
    try:
        conn = get_db_connection()
        with conn.cursor() as cur:
            cur.execute(sql, args)
            result = cur.fetchall()
            duration = time.time() - start  # Keep in seconds for logging
            
            # Full SQL tracing
            sql_trimmed = sql[:200] + "..." if len(sql) > 200 else sql
            params_str = str(args) if args else "()"
            print(f"[SQL] ({duration:.3f}s) {sql_trimmed} | params: {params_str}")
            
            # Log slow queries to file
            if duration > 0.5:
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                with open("slow_queries.log", "a") as f:
                    f.write(f"{timestamp} | {duration:.3f}s | {sql} | params: {params_str}\n")
                print(f"[SQL] ⚠️  SLOW QUERY ({duration:.3f}s) logged to slow_queries.log")
            
            return result
    finally:
        if conn:
            return_db_connection(conn)

