def _get_site_stats():
    """Single source for the 4 homepage stats. Cached 5min. Returns active_sailors, classes_sailed, regattas_sailed, races_raced. Used by /api/site-stats and /admin/dashboard-data."""
    cached = get_cached("site_stats", ttl_seconds=300)
    if cached is not None:
        return cached
    conn = None
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        # Sailors: same filter as admin_active_sailors (regatta must have a date so badge count = table rows)
        cur.execute("""
            SELECT COUNT(DISTINCT sailor_id) AS active_sailors
            FROM (
                SELECT r.helm_sa_sailing_id AS sailor_id FROM results r
                JOIN regattas reg ON reg.regatta_id = r.regatta_id
                WHERE r.raced = TRUE AND r.helm_sa_sailing_id IS NOT NULL AND r.helm_sa_sailing_id::text != ''
                  AND (reg.end_date IS NOT NULL OR reg.start_date IS NOT NULL)
                UNION ALL
                SELECT r.crew_sa_sailing_id AS sailor_id FROM results r
                JOIN regattas reg ON reg.regatta_id = r.regatta_id
                WHERE r.raced = TRUE AND r.crew_sa_sailing_id IS NOT NULL AND r.crew_sa_sailing_id::text != ''
                  AND (reg.end_date IS NOT NULL OR reg.start_date IS NOT NULL)
            ) u
        """)
        row = cur.fetchone()
        val = row.get("active_sailors") if row else None
        active_sailors = int(val) if val is not None else 0
        # Classes Sailed: distinct class_name in results, excluding Unknown
        cur.execute("""
            SELECT COUNT(DISTINCT c.class_name) AS n
            FROM results r
            JOIN classes c ON c.class_id = r.class_id
            WHERE c.class_name <> 'Unknown'
        """)
        row_cl = cur.fetchone()
        classes_sailed = int(row_cl["n"]) if row_cl and row_cl.get("n") is not None else 0
        # Regattas: only those with results (matches regattas/with-counts list)
        cur.execute("""
            SELECT COUNT(DISTINCT r.regatta_id) AS regattas_sailed
            FROM regattas r
            JOIN results res ON res.regatta_id = r.regatta_id
            WHERE res.raced = TRUE
        """)
        row3 = cur.fetchone()
        val3 = row3.get("regattas_sailed") if row3 else None
        regattas_sailed = int(val3) if val3 is not None else 0
        cur.execute("SELECT COUNT(*) AS races_raced FROM results r WHERE r.raced = TRUE")
        row4 = cur.fetchone()
        val4 = row4.get("races_raced") if row4 else None
        races_raced = int(val4) if val4 is not None else 0
        cur.close()
        result = {"active_sailors": active_sailors, "classes_sailed": classes_sailed, "regattas_sailed": regattas_sailed, "races_raced": races_raced}
        set_cached("site_stats", result, ttl_seconds=300)
        return result
    except Exception as e:
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        return {"active_sailors": None, "classes_sailed": None, "regattas_sailed": None, "races_raced": None, "error": str(e)}
    finally:
        if conn:
            return_db_connection(conn)


@app.get("/api/site-stats")
def api_site_stats():
    """Site stats for dashboard. Uses same sources as search. Cached 5min. Delegates to _get_site_stats()."""
    return _get_site_stats()


@app.get("/api/events/live-summary")
def api_events_live_summary():
    """Live events count for public hub UIs; same `live` bucket as /events. Cached 60s."""
    ck = "events_live_summary_v1"
    cached = get_cached(ck, ttl_seconds=60)
    if cached is not None:
        return cached
    try:
        data = _get_upcoming_events()
        live = data.get("live") or []
        out = {"live_count": len(live), "has_live": len(live) > 0}
    except Exception as e:
        out = {"live_count": 0, "has_live": False, "error": str(e)}
    set_cached(ck, out, ttl_seconds=60)
    return out


def _supplement_breaking_news_events_with_hub_badged_regattas(
    cur,
    out: list,
    *,
    has_category: bool,
    has_rb: bool,
    has_res: bool,
) -> None:
    """Append synthetic event rows for regattas with ``blank_hub_news_badge_label`` set when they are absent from
    the ``events`` calendar feed (no row, or row without ``regatta_id``). Otherwise blank.html never sees SA-tagged
    regattas and Top/Breaking/News/Archive slots stay empty."""
    if not table_exists("regattas") or not column_exists("regattas", "blank_hub_news_badge_label"):
        return
    seen = {str(x.get("regatta_id") or "").strip() for x in out if x and x.get("regatta_id")}
    if has_rb:
        races_sql = (
            "(SELECT COALESCE(SUM(COALESCE(rb.races_sailed, 0)), 0)::int "
            "FROM regatta_blocks rb WHERE rb.regatta_id = r.regatta_id)"
        )
        podium_sql = (
            "(SELECT rb.class_id FROM regatta_blocks rb WHERE rb.regatta_id = r.regatta_id "
            "ORDER BY rb.block_id NULLS LAST LIMIT 1)"
        )
    else:
        races_sql = "0::int"
        podium_sql = "NULL::int"
    if has_res:
        entries_sql = (
            "(SELECT COUNT(*)::int FROM results res WHERE res.regatta_id = r.regatta_id AND res.raced = TRUE)"
        )
    else:
        entries_sql = "0::int"
    has_rt_r = column_exists("regattas", "result_type")
    rt_sel = "COALESCE(r.result_type::text, 'UNKNOWN')" if has_rt_r else "'UNKNOWN'::text"
    cur.execute(
        f"""
        SELECT r.regatta_id::text AS regatta_id,
               r.event_name,
               r.start_date,
               COALESCE(r.end_date, r.start_date) AS end_date,
               {races_sql} AS races_sailed,
               {entries_sql} AS entries,
               {podium_sql} AS podium_class_id,
               NULLIF(TRIM(r.blank_hub_news_badge_label), '') AS blank_hub_news_badge_label,
               {rt_sel} AS result_type
        FROM regattas r
        WHERE NULLIF(TRIM(r.blank_hub_news_badge_label), '') IS NOT NULL
        LIMIT 40
        """
    )
    extra = cur.fetchall() or []
    for r in extra:
        rid = r.get("regatta_id")
        rs = str(rid or "").strip()
        if not rs or rs in seen:
            continue
        seen.add(rs)
        sd = r.get("start_date")
        ed = r.get("end_date")
        pcid = r.get("podium_class_id")
        item = {
            "event_name": r.get("event_name"),
            "start_date": sd.isoformat() if sd and hasattr(sd, "isoformat") else (str(sd) if sd else None),
            "end_date": ed.isoformat() if ed and hasattr(ed, "isoformat") else (str(ed) if ed else None),
            "races_sailed": int(r.get("races_sailed") or 0),
            "entries": int(r.get("entries") or 0),
        }
        if has_category:
            item["category"] = None
        item["regatta_id"] = rid if rid is not None else None
        item["podium_class_id"] = int(pcid) if pcid is not None else None
        ren = r.get("event_name")
        item["regatta_event_name"] = (str(ren).strip() if ren is not None and str(ren).strip() else None)
        item["class_layout"] = "unknown"
        rt_out = r.get("result_type")
        item["result_type"] = str(rt_out).strip() if rt_out is not None else "UNKNOWN"
        hb_raw = r.get("blank_hub_news_badge_label")
        item["blank_hub_news_badge_label"] = (
            (str(hb_raw).strip() if hb_raw is not None and str(hb_raw).strip() else None) or None
        )
        out.append(item)


@app.get("/api/events")
def api_events_public_list(
    blank_hub: bool = Query(
        False,
        alias="blank_hub",
        description="If true: narrower date window + lower limit for blank/events hub (faster).",
    ),
    breaking_news: bool = Query(
        False,
        alias="breaking_news",
        description="With blank_hub: linked events only, lower limit, skip yearly-series + hub window (Breaking News card).",
    ),
):
    """Public JSON array for dashboards: event_name, start_date, end_date, races_sailed, entries (from linked regatta when present)."""
    if not table_exists("events"):
        return []
    conn = None
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        has_regatta_id = column_exists("events", "regatta_id")
        has_category = column_exists("events", "category")
        has_rb = table_exists("regatta_blocks")
        has_res = table_exists("results")
        if not has_regatta_id:
            races_sql = "0::int"
            entries_sql = "0::int"
            podium_class_sql = "NULL::int"
            regatta_col = "NULL::text AS regatta_id"
        else:
            if has_rb:
                races_sql = (
                    "CASE WHEN e.regatta_id IS NULL THEN 0::int "
                    "ELSE (SELECT COALESCE(SUM(COALESCE(rb.races_sailed, 0)), 0)::int FROM regatta_blocks rb "
                    "WHERE rb.regatta_id = e.regatta_id) END::int"
                )
                podium_class_sql = (
                    "CASE WHEN e.regatta_id IS NULL THEN NULL::int "
                    "ELSE (SELECT rb.class_id FROM regatta_blocks rb WHERE rb.regatta_id = e.regatta_id "
                    "ORDER BY rb.block_id NULLS LAST LIMIT 1) END"
                )
            else:
                races_sql = "0::int"
                podium_class_sql = "NULL::int"
            if has_res:
                entries_sql = (
                    "CASE WHEN e.regatta_id IS NULL THEN 0::int "
                    "ELSE (SELECT COUNT(*)::int FROM results r WHERE r.regatta_id = e.regatta_id AND r.raced = TRUE) END::int"
                )
            else:
                entries_sql = "0::int"
            regatta_col = "e.regatta_id"
        if blank_hub:
            # Blank landing: regatta-style calendar only (same exclusions as /events result line for Meeting/Training).
            cat_excl = ""
            if has_category:
                cat_excl = (
                    " AND lower(trim(COALESCE(e.category, ''))) NOT IN "
                    "('training', 'meeting', 'meetings') "
                )
            bn_extra = ""
            limit_n = 400
            if breaking_news:
                limit_n = 100
                if has_regatta_id:
                    bn_extra = " AND e.regatta_id IS NOT NULL "
            where_hub = f"""
            WHERE COALESCE(e.end_date, e.start_date) >= (CURRENT_DATE - INTERVAL '150 days')
              AND COALESCE(e.start_date, e.end_date) <= (CURRENT_DATE + INTERVAL '540 days')
              {cat_excl}
              {bn_extra}
            """
        else:
            where_hub = ""
            limit_n = 1500
        category_sql = "e.category AS category" if has_category else "NULL::text AS category"
        has_layout_e = column_exists("events", "class_layout")
        has_layout_r = column_exists("regattas", "class_layout")
        has_rt_e = column_exists("events", "result_type")
        has_rt_r = column_exists("regattas", "result_type")
        join_reg = ""
        if has_regatta_id and table_exists("regattas"):
            join_reg = "\n            LEFT JOIN regattas reg ON reg.regatta_id = e.regatta_id"
        if has_regatta_id and has_res:
            e_cl = "e.class_layout" if has_layout_e else "NULL::text"
            r_cl = "reg.class_layout" if has_layout_r else "NULL::text"
            layout_select = (
                f"""COALESCE(
                (SELECT CASE
                    WHEN COUNT(*) = 0 THEN NULL::text
                    WHEN COUNT(DISTINCT block_id) > 1 THEN 'multi_class'
                    WHEN COUNT(DISTINCT block_id) = 1 THEN 'single_class'
                    ELSE 'unknown'
                END
                FROM public.results x
                WHERE x.regatta_id = e.regatta_id AND x.raced = TRUE),
                NULLIF(BTRIM({r_cl}), ''),
                NULLIF(BTRIM({e_cl}), ''),
                'unknown'
            ) AS class_layout"""
            )
        elif join_reg and (has_layout_e or has_layout_r):
            e_cl = "e.class_layout" if has_layout_e else "NULL::text"
            r_cl = "reg.class_layout" if has_layout_r else "NULL::text"
            layout_select = f"COALESCE(NULLIF(BTRIM({r_cl}), ''), NULLIF(BTRIM({e_cl}), ''), 'unknown') AS class_layout"
        elif has_layout_e:
            layout_select = "COALESCE(NULLIF(BTRIM(e.class_layout), ''), 'unknown') AS class_layout"
        else:
            layout_select = "'unknown'::text AS class_layout"
        if has_regatta_id and join_reg and has_rt_e and has_rt_r:
            result_type_select = "COALESCE(e.result_type::text, reg.result_type::text, 'UNKNOWN') AS result_type"
        elif has_regatta_id and join_reg and has_rt_r:
            result_type_select = "COALESCE(reg.result_type::text, 'UNKNOWN') AS result_type"
        elif has_rt_e:
            result_type_select = "COALESCE(e.result_type::text, 'UNKNOWN') AS result_type"
        else:
            result_type_select = "'UNKNOWN'::text AS result_type"
        regatta_name_sql = "reg.event_name AS regatta_event_name" if join_reg else "NULL::text AS regatta_event_name"
        # Same hub slot as blank.html / regatta SA — from ``regattas.blank_hub_news_badge_label`` (not ``results``).
        hub_badge_sql = (
            "NULLIF(TRIM(reg.blank_hub_news_badge_label), '') AS blank_hub_news_badge_label"
            if join_reg
            else "NULL::text AS blank_hub_news_badge_label"
        )
        # Linked regatta: hub dates follow regattas (SA / results card), not stale events rows.
        if join_reg:
            hub_start_sql = (
                "CASE WHEN e.regatta_id IS NOT NULL THEN COALESCE(reg.start_date, e.start_date) "
                "ELSE e.start_date END AS start_date"
            )
            hub_end_sql = (
                "CASE WHEN e.regatta_id IS NOT NULL "
                "THEN COALESCE(reg.end_date, reg.start_date, e.end_date, e.start_date) "
                "ELSE COALESCE(e.end_date, e.start_date) END AS end_date"
            )
            hub_order_start = (
                "CASE WHEN e.regatta_id IS NOT NULL THEN COALESCE(reg.start_date, e.start_date) "
                "ELSE e.start_date END DESC NULLS LAST"
            )
        else:
            hub_start_sql = "e.start_date AS start_date"
            hub_end_sql = "e.end_date AS end_date"
            hub_order_start = "e.start_date DESC NULLS LAST"
        cur.execute(
            f"""
            SELECT e.event_name, {hub_start_sql}, {hub_end_sql},
                   {category_sql},
                   {regatta_col},
                   {races_sql} AS races_sailed,
                   {entries_sql} AS entries,
                   {podium_class_sql} AS podium_class_id,
                   {layout_select},
                   {result_type_select},
                   {regatta_name_sql},
                   {hub_badge_sql}
            FROM events e{join_reg}
            {where_hub}
            ORDER BY {hub_order_start}
            LIMIT {limit_n}
            """
        )
        rows = cur.fetchall() or []
        out = []
        for r in rows:
            sd = r.get("start_date")
            ed = r.get("end_date")
            rid = r.get("regatta_id")
            pcid = r.get("podium_class_id")
            item = {
                "event_name": r.get("event_name"),
                "start_date": sd.isoformat() if sd and hasattr(sd, "isoformat") else (str(sd) if sd else None),
                "end_date": ed.isoformat() if ed and hasattr(ed, "isoformat") else (str(ed) if ed else None),
                "races_sailed": int(r.get("races_sailed") or 0),
                "entries": int(r.get("entries") or 0),
            }
            if has_category:
                cat_raw = r.get("category")
                item["category"] = (str(cat_raw).strip() if cat_raw is not None else "") or None
            if has_regatta_id:
                item["regatta_id"] = rid if rid is not None else None
                item["podium_class_id"] = int(pcid) if pcid is not None else None
                ren = r.get("regatta_event_name")
                item["regatta_event_name"] = (str(ren).strip() if ren is not None and str(ren).strip() else None)
            cl_out = r.get("class_layout")
            if cl_out is not None:
                item["class_layout"] = str(cl_out).strip() or "unknown"
            else:
                item["class_layout"] = "unknown"
            rt_out = r.get("result_type")
            item["result_type"] = str(rt_out).strip() if rt_out is not None else "UNKNOWN"
            hb_raw = r.get("blank_hub_news_badge_label")
            item["blank_hub_news_badge_label"] = (
                (str(hb_raw).strip() if hb_raw is not None and str(hb_raw).strip() else None) or None
            )
            out.append(item)
        if blank_hub and breaking_news and has_regatta_id:
            _supplement_breaking_news_events_with_hub_badged_regattas(
                cur, out, has_category=has_category, has_rb=has_rb, has_res=has_res
            )
        if blank_hub:
            if breaking_news:
                return {
                    "events": out,
                    "hub_upcoming_window": {
                        "sort_version": UPCOMING_DISPLAY_SORT_VERSION,
                        "sort_signature": "",
                        "anchor_date": None,
                        "window_end": None,
                        "items": [],
                    },
                }
            series_map = _yearly_series_distinct_year_counts_map()
            max_by_sk, hist_by_sk = _yearly_series_max_and_history_maps()
            for item in out:
                key = _yearly_event_series_key((item.get("event_name") or "").strip())
                item["series_years_count"] = int(series_map.get(key, 0)) if key else 0
                emax = int(max_by_sk.get(key, 0)) if key else 0
                item["entries_max_series"] = emax
                ev_y = _event_year_from_public_event_item(item)
                py, pe = _prior_year_entries_from_hist(hist_by_sk.get(key) if key else None, ev_y)
                item["prior_year"] = py
                item["entries_prior_year"] = pe
                item["entries_for_sort"] = max(int(item.get("entries") or 0), emax)
            hub_window = _compute_hub_upcoming_window_payload(out, today_iso=date.today().isoformat(), window_days=5, limit=10)
            return {"events": out, "hub_upcoming_window": hub_window}
        return out
    except Exception as e:
        print(f"[api_events_public_list] {e}")
        traceback.print_exc()
        return []
    finally:
        if conn:
            return_db_connection(conn)


@app.get("/api/events/upcoming-window")
def api_events_upcoming_window():
    """Same slice + sort_signature as blank hub (`hub_upcoming_window`). Compare signatures across UIs."""
    payload = api_events_public_list(blank_hub=True)
    if isinstance(payload, dict):
        return payload.get("hub_upcoming_window") or {
            "sort_version": UPCOMING_DISPLAY_SORT_VERSION,
            "sort_signature": "",
            "anchor_date": None,
            "window_end": None,
            "items": [],
        }
    return {
        "sort_version": UPCOMING_DISPLAY_SORT_VERSION,
        "sort_signature": "",
        "anchor_date": None,
        "window_end": None,
        "items": [],
    }


