def api_results_sailor_by_slug(slug: str, request: Request):
    """Alias for /api/sailor/results/{slug} – frontend/iframe may call /api/results/sailor/{slug}/."""
    return api_sailor_results_by_slug(slug, request)


@app.get("/api/regatta/results/{slug}")
def api_regatta_results_by_slug(slug: str, request: Request):
    """Results by sailor slug (same as sailor/results) – frontend result sheet popup may call either URL."""
    sas_id = _get_sas_id_by_slug(slug)
    if not sas_id:
        raise HTTPException(status_code=404, detail="sailor not found")
    return api_member_results(sas_id, request)


@app.get("/api/sailor/{sailor_id}")
def api_sailor_details(sailor_id: str):
    """Get full sailor details by SA ID, Temp ID, or slug (e.g. tristan-gress) for tooltip/profile."""
    # If not numeric and not TMP, treat as slug so /api/sailor/tristan-gress works like /api/sailor/8612
    if sailor_id and not sailor_id.isdigit() and not sailor_id.upper().startswith("TMP"):
        resolved_id = _get_sas_id_by_slug(sailor_id)
        if resolved_id:
            sailor_id = resolved_id
    with psycopg2.connect(DB_URL) as conn:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            # Check if it's a temp ID
            if sailor_id.upper().startswith("TMP:") or sailor_id.upper().startswith("TMP"):
                tmp_num = sailor_id.split(":")[-1].strip() if ":" in sailor_id else sailor_id.replace("TMP", "").strip()
                if tmp_num.isdigit():
                    cur.execute("""
                        SELECT 
                            'TMP:' || t.temp_id::text as sa_id,
                            t.full_name as name,
                            COALESCE(c.club_code, t.club_raw) as club,
                            NULL as age,
                            NULL as year_of_birth,
                            NULL as primary_class,
                            NULL as email,
                            NULL as phone_primary,
                            t.notes as notes
                        FROM temp_people t
                        LEFT JOIN clubs c ON c.club_id = t.club_id
                        WHERE t.temp_id = %s
                    """, (int(tmp_num),))
                    row = cur.fetchone()
                    if row:
                        return dict(row)
            if sailor_id.upper().startswith("NAME:"):
                slug_key = sailor_id.split(":", 1)[-1].strip()
                nm, _res = _get_sailor_by_name_slug_from_results(slug_key)
                if nm:
                    club_disp, class_disp = _profile_fields_from_results_for_name_only(nm)
                    return {
                        "sa_id": sailor_id,
                        "name": nm,
                        "club": club_disp,
                        "age": None,
                        "year_of_birth": None,
                        "primary_class": class_disp,
                        "email": None,
                        "phone_primary": None,
                        "notes": None,
                    }
            # Otherwise, treat as SA Sailing ID
            if sailor_id.isdigit():
                cur.execute("""
                    SELECT 
                        s.sa_sailing_id::text as sa_id,
                        COALESCE(s.full_name, TRIM(s.first_name || ' ' || COALESCE(s.last_name, ''))) as name,
                        COALESCE(s.primary_club, s.club_1) as club,
                        s.age,
                        s.year_of_birth,
                        s.primary_class,
                        s.email,
                        s.phone_primary,
                        NULL as notes
                    FROM sas_id_personal s
                    WHERE s.sa_sailing_id::text = %s
                """, (sailor_id,))
                row = cur.fetchone()
                if row:
                    return dict(row)
    
    return {"error": "Sailor not found"}

