def _redirect_with_query(page: str, params: Dict[str, Any]) -> RedirectResponse:
    clean = {}
    for key, value in (params or {}).items():
        if value is None:
            continue
        text = str(value).strip()
        if text == "":
            continue
        clean[key] = text
    if clean:
        return RedirectResponse(f"{page}?{urlencode(clean)}")
    return RedirectResponse(page)


def _create_login_session_record(cur, request: Request, account_id: Any, sas_id: Any, login_method: str) -> str:
    session_token = str(uuid.uuid4())
    expires_at = datetime.now() + timedelta(days=30)
    client_ip = _get_client_ip(request)
    user_agent = (request.headers.get("user-agent") or "")[:500]
    device_type = _derive_device_type(user_agent)
    cols = ["session_id", "account_id", "sas_id", "login_method", "expires_at", "ip_address", "user_agent"]
    vals = [session_token, account_id, sas_id, login_method, expires_at, client_ip or None, user_agent or None]
    if table_exists("user_sessions") and column_exists("user_sessions", "device_type"):
        cols.append("device_type")
        vals.append(device_type)
    cur.execute(
        "INSERT INTO public.user_sessions (" + ", ".join(cols) + ") VALUES (" + ", ".join(["%s"] * len(vals)) + ")",
        vals,
    )
    return session_token


def _upsert_google_account(
    cur,
    sas_id: Any,
    google_id: str,
    google_email: Optional[str],
    email_verified: bool,
    first_name: Optional[str],
    last_name: Optional[str],
    full_name: Optional[str],
) -> Any:
    cur.execute(
        """
        SELECT account_id
        FROM public.user_accounts
        WHERE login_method = 'google' AND provider_id = %s
        LIMIT 1
        """,
        (str(google_id).strip(),),
    )
    existing = cur.fetchone()
    if existing:
        cur.execute(
            """
            UPDATE public.user_accounts
            SET sas_id = %s,
                email = COALESCE(%s, email),
                email_verified = %s,
                first_name = COALESCE(%s, first_name),
                last_name = COALESCE(%s, last_name),
                full_name = COALESCE(%s, full_name)
            WHERE account_id = %s
            RETURNING account_id
            """,
            (
                sas_id,
                (google_email or "").strip() or None,
                bool(email_verified),
                (first_name or "").strip() or None,
                (last_name or "").strip() or None,
                (full_name or "").strip() or None,
                existing["account_id"],
            ),
        )
        row = cur.fetchone()
        return row["account_id"] if row else existing["account_id"]

    cur.execute(
        """
        INSERT INTO public.user_accounts
        (sas_id, login_method, provider_id, email, email_verified, first_name, last_name, full_name)
        VALUES (%s, 'google', %s, %s, %s, %s, %s, %s)
        RETURNING account_id
        """,
        (
            sas_id,
            str(google_id).strip(),
            (google_email or "").strip() or None,
            bool(email_verified),
            (first_name or "").strip() or None,
            (last_name or "").strip() or None,
            (full_name or "").strip() or None,
        ),
    )
    row = cur.fetchone()
    return row["account_id"] if row else None


