# --- REGATTA_ENTRY_FLOW_2026_07_23 ---

def _regatta_entry_is_optimist_class(name: str) -> bool:
    n = (name or "").strip().lower()
    return n == "optimist" or n.startswith("optimist ")


def _regatta_entry_sailor_age(cur, sas_id: str):
    """Best-effort age in whole years from catalogue; None if unknown."""
    sid = str(sas_id or "").strip()
    if not sid:
        return None
    cur.execute(
        """
        SELECT year_of_birth, age, date_of_birth
        FROM sas_id_personal
        WHERE sa_sailing_id::text = %s
        LIMIT 1
        """,
        (sid,),
    )
    row = cur.fetchone() or {}
    dob = row.get("date_of_birth")
    if dob:
        try:
            today = datetime.now().date()
            years = today.year - dob.year - ((today.month, today.day) < (dob.month, dob.day))
            if years >= 0:
                return int(years)
        except Exception:
            pass
    yob = row.get("year_of_birth")
    try:
        yob_i = int(yob) if yob not in (None, "") else None
    except (TypeError, ValueError):
        yob_i = None
    if yob_i and 1900 <= yob_i <= datetime.now().year:
        return max(0, datetime.now().year - yob_i)
    try:
        age_i = int(row.get("age")) if row.get("age") not in (None, "") else None
    except (TypeError, ValueError):
        age_i = None
    if age_i is not None and 0 <= age_i < 120:
        return age_i
    return None


def _regatta_entry_optimist_policy(cur, sas_id: str) -> dict:
    """
    Optimist entry rules:
    - age > 16 → hide all Optimist classes
    - more Optimist A than B AND A more recent (or equal) → hide Optimist B
    """
    sid = str(sas_id or "").strip()
    age = _regatta_entry_sailor_age(cur, sid) if sid else None
    hide_all = bool(age is not None and age > 16)
    hide_b = False
    a_count = b_count = 0
    a_last = b_last = None
    if sid and not hide_all:
        cur.execute(
            """
            SELECT COALESCE(NULLIF(TRIM(c.class_name), ''), '') AS class_name,
                   COUNT(*)::int AS n,
                   MAX(COALESCE(rg.end_date, rg.start_date)) AS last_date
            FROM results r
            LEFT JOIN classes c ON c.class_id = r.class_id
            LEFT JOIN regattas rg ON rg.regatta_id = r.regatta_id
            WHERE r.helm_sa_sailing_id::text = %s
               OR r.crew_sa_sailing_id::text = %s
               OR COALESCE(r.crew2_sa_sailing_id::text, '') = %s
               OR COALESCE(r.crew3_sa_sailing_id::text, '') = %s
            GROUP BY COALESCE(NULLIF(TRIM(c.class_name), ''), '')
            """,
            (sid, sid, sid, sid),
        )
        for row in cur.fetchall() or []:
            name = (row.get("class_name") or "").strip().lower()
            n = int(row.get("n") or 0)
            last = row.get("last_date")
            if name == "optimist a":
                a_count, a_last = n, last
            elif name == "optimist b":
                b_count, b_last = n, last
        if a_count > b_count:
            if a_last is not None and (b_last is None or a_last >= b_last):
                hide_b = True
            elif b_count == 0:
                hide_b = True
    return {
        "age": age,
        "hide_all_optimist": hide_all,
        "hide_optimist_b": hide_b,
        "optimist_a_count": a_count,
        "optimist_b_count": b_count,
    }


def _regatta_entry_filter_classes(classes: list, policy: dict | None) -> list:
    pol = policy or {}
    hide_all = bool(pol.get("hide_all_optimist"))
    hide_b = bool(pol.get("hide_optimist_b"))
    out = []
    for c in classes or []:
        name = (c.get("class_name") or "").strip()
        low = name.lower()
        if hide_all and _regatta_entry_is_optimist_class(name):
            continue
        if hide_b and low == "optimist b":
            continue
        out.append(c)
    return out


def _regatta_entry_boats_for_sas(cur, sas_id: str) -> list:
    """Classes + sail numbers this sailor has used (helm or crew)."""
    sid = str(sas_id or "").strip()
    if not sid:
        return []
    cur.execute(
        """
        SELECT c.class_id,
               COALESCE(NULLIF(TRIM(c.class_name), ''), 'Open') AS class_name,
               NULLIF(btrim(c.logo_path), '') AS logo_path,
               COUNT(*)::int AS race_count,
               ARRAY_REMOVE(ARRAY_AGG(DISTINCT NULLIF(TRIM(r.sail_number::text), '')), NULL) AS sail_numbers
        FROM results r
        LEFT JOIN classes c ON c.class_id = r.class_id
        WHERE r.helm_sa_sailing_id::text = %s
           OR r.crew_sa_sailing_id::text = %s
           OR COALESCE(r.crew2_sa_sailing_id::text, '') = %s
           OR COALESCE(r.crew3_sa_sailing_id::text, '') = %s
        GROUP BY c.class_id, COALESCE(NULLIF(TRIM(c.class_name), ''), 'Open'), NULLIF(btrim(c.logo_path), '')
        ORDER BY COUNT(*) DESC, class_name
        """,
        (sid, sid, sid, sid),
    )
    out = []
    for row in cur.fetchall() or []:
        sails = row.get("sail_numbers") or []
        if not isinstance(sails, list):
            sails = list(sails) if sails else []
        cname = row.get("class_name") or "Open"
        logo = (row.get("logo_path") or "").strip()
        if not logo:
            try:
                logo = (_catalogue_logo_path_for_class_name(cname, cur) or "").strip()
            except Exception:
                logo = ""
        out.append(
            {
                "class_id": row.get("class_id"),
                "class_name": cname,
                "logo_path": logo,
                "race_count": int(row.get("race_count") or 0),
                "sail_numbers": [str(s) for s in sails if s],
            }
        )
    policy = _regatta_entry_optimist_policy(cur, sid)
    return _regatta_entry_filter_classes(out, policy)


def _regatta_entry_profile(cur, sas_id: str) -> dict | None:
    sid = str(sas_id or "").strip()
    if not sid:
        return None
    cur.execute(
        """
        SELECT sa_sailing_id::text AS sas_id,
               first_name, last_name,
               COALESCE(NULLIF(TRIM(full_name), ''),
                        TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,''))) AS full_name,
               COALESCE(NULLIF(TRIM(primary_club), ''), NULLIF(TRIM(club_1), '')) AS club,
               year_of_birth, age, date_of_birth
        FROM sas_id_personal
        WHERE sa_sailing_id::text = %s
        LIMIT 1
        """,
        (sid,),
    )
    row = cur.fetchone()
    if not row:
        return None
    club = row.get("club") or ""
    club_logo = ""
    if club:
        club_logo = f"/api/club-logo/{str(club).strip().upper()}"
    age = _regatta_entry_sailor_age(cur, sid)
    policy = _regatta_entry_optimist_policy(cur, sid)
    return {
        "sas_id": row.get("sas_id"),
        "first_name": row.get("first_name") or "",
        "last_name": row.get("last_name") or "",
        "full_name": row.get("full_name") or "",
        "club": club,
        "club_logo": club_logo,
        "year_of_birth": row.get("year_of_birth"),
        "age": age,
        "optimist_policy": {
            "hide_all_optimist": bool(policy.get("hide_all_optimist")),
            "hide_optimist_b": bool(policy.get("hide_optimist_b")),
        },
    }


@app.get("/api/regatta-entry/me")
async def api_regatta_entry_me(request: Request):
    """Logged-in sailor profile + boats/classes for entry form."""
    session_token = request.cookies.get("session") or request.query_params.get("session")
    if not session_token:
        raise HTTPException(status_code=401, detail="Not signed in")
    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        cur.execute(
            """
            SELECT sas_id FROM public.user_sessions
            WHERE session_id = %s AND expires_at > NOW()
            """,
            (session_token,),
        )
        sess = cur.fetchone()
        if not sess or not sess.get("sas_id"):
            raise HTTPException(status_code=401, detail="Session invalid")
        sid = str(sess["sas_id"])
        profile = _regatta_entry_profile(cur, sid)
        boats = _regatta_entry_boats_for_sas(cur, sid)
        return {"ok": True, "profile": profile, "boats": boats}
    finally:
        cur.close()
        return_db_connection(conn)


@app.get("/api/regatta-entry/profile")
async def api_regatta_entry_profile(sas_id: str = Query(...)):
    """Public profile + boats for find-yourself confirmation."""
    sid = str(sas_id or "").strip()
    if not sid.isdigit():
        raise HTTPException(status_code=400, detail="Invalid sas_id")
    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        profile = _regatta_entry_profile(cur, sid)
        if not profile:
            raise HTTPException(status_code=404, detail="Sailor not found")
        boats = _regatta_entry_boats_for_sas(cur, sid)
        return {"ok": True, "profile": profile, "boats": boats}
    finally:
        cur.close()
        return_db_connection(conn)


@app.get("/api/regatta-entry/classes")
async def api_regatta_entry_classes(
    q: str = Query(""),
    limit: int = Query(20),
    sas_id: str = Query(""),
):
    """Catalogue class search for entry form (with logo_path)."""
    term = str(q or "").strip()
    if len(term) < 2:
        return {"classes": []}
    lim = max(1, min(int(limit or 20), 40))
    sid = str(sas_id or "").strip()
    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        like = f"%{term.lower()}%"
        cur.execute(
            """
            SELECT class_id, class_name, NULLIF(btrim(logo_path), '') AS logo_path
            FROM classes
            WHERE class_name IS NOT NULL AND btrim(class_name) <> ''
              AND lower(class_name) LIKE %s
            ORDER BY
              CASE WHEN lower(class_name) = lower(%s) THEN 0
                   WHEN lower(class_name) LIKE lower(%s) || '%%' THEN 1
                   ELSE 2 END,
              class_name
            LIMIT %s
            """,
            (like, term, term, lim),
        )
        out = []
        for row in cur.fetchall() or []:
            cname = row.get("class_name") or ""
            logo = (row.get("logo_path") or "").strip()
            if not logo and cname:
                try:
                    logo = (_catalogue_logo_path_for_class_name(cname, cur) or "").strip()
                except Exception:
                    logo = ""
            out.append(
                {
                    "class_id": row.get("class_id"),
                    "class_name": cname,
                    "logo_path": logo,
                    "sail_numbers": [],
                }
            )
        policy = _regatta_entry_optimist_policy(cur, sid) if sid else None
        return {"ok": True, "classes": _regatta_entry_filter_classes(out, policy)}
    finally:
        cur.close()
        return_db_connection(conn)


def _regatta_entry_apply_to_fleet(cur, entry: dict) -> dict:
    """Fill next empty Open Fleet stub row (or update same SAS id). Returns rank/result_id."""
    rid = str(entry.get("regatta_id") or "").strip()
    try:
        cur.execute(
            """
            SELECT COALESCE(bool_or(COALESCE(entries_closed, FALSE)), FALSE) AS closed
            FROM regatta_blocks WHERE regatta_id = %s
            """,
            (rid,),
        )
        crow = cur.fetchone() or {}
        if crow.get("closed"):
            raise HTTPException(status_code=409, detail="Entries are closed for this event")
    except HTTPException:
        raise
    except Exception:
        pass
    sas = str(entry.get("sas_id") or "").strip()
    first = str(entry.get("first_name") or "").strip()
    last = str(entry.get("last_name") or "").strip()
    full = (first + " " + last).strip() or "Sailor"
    club = str(entry.get("club") or "").strip()
    class_id = entry.get("class_id")
    try:
        class_id_i = int(class_id) if class_id not in (None, "", "null") else None
    except (TypeError, ValueError):
        class_id_i = None
    class_name = str(entry.get("class_name") or "").strip() or "Open"
    sail = str(entry.get("sail_number") or "").strip()
    boat = str(entry.get("boat_name") or "").strip()
    role = str(entry.get("role") or "helm").strip().lower()
    teammate = str(entry.get("teammate") or "").strip()
    teammate_sas = str(entry.get("teammate_sas_id") or "").strip()
    teammate_sid = int(teammate_sas) if teammate_sas.isdigit() else None
    note = str(entry.get("note") or "").strip()

    helm_name = full
    crew_name = None
    helm_sid = int(sas) if sas.isdigit() else None
    crew_sid = None
    if role == "crew":
        # Self as crew; teammate as helm if provided
        crew_name = full
        crew_sid = helm_sid
        helm_name = teammate or full
        helm_sid = teammate_sid if teammate else helm_sid
        if teammate:
            crew_name = full
    elif role == "helm_with_crew":
        crew_name = teammate or None
        crew_sid = teammate_sid
    elif role == "crew_with_helm":
        helm_name = teammate or full
        crew_name = full
        crew_sid = int(sas) if sas.isdigit() else None
        helm_sid = teammate_sid

    # Resolve club_id if possible
    club_id = None
    if club:
        cur.execute(
            """
            SELECT club_id FROM clubs
            WHERE upper(btrim(club_abbrev)) = upper(%s)
               OR upper(btrim(club_code)) = upper(%s)
               OR lower(btrim(club_name)) = lower(%s)
            LIMIT 1
            """,
            (club, club, club),
        )
        crow = cur.fetchone()
        if crow:
            club_id = crow.get("club_id")

    # Prefer update existing row for this SAS on this regatta
    row = None
    if sas.isdigit():
        cur.execute(
            """
            SELECT result_id, rank, block_id
            FROM results
            WHERE regatta_id = %s
              AND (helm_sa_sailing_id::text = %s OR crew_sa_sailing_id::text = %s)
            ORDER BY rank NULLS LAST
            LIMIT 1
            """,
            (rid, sas, sas),
        )
        row = cur.fetchone()

    if not row:
        cur.execute(
            """
            SELECT result_id, rank, block_id
            FROM results
            WHERE regatta_id = %s
              AND (helm_name IS NULL OR btrim(helm_name) = '')
              AND helm_sa_sailing_id IS NULL
            ORDER BY rank NULLS LAST, result_id
            LIMIT 1
            """,
            (rid,),
        )
        row = cur.fetchone()

    if not row:
        raise HTTPException(status_code=409, detail="Fleet is full — no empty entry slots left")

    result_id = row["result_id"]
    rank = row["rank"]
    source_note = note
    cur.execute(
        """
        UPDATE results SET
            helm_name = %s,
            helm_sa_sailing_id = %s,
            crew_name = %s,
            crew_sa_sailing_id = %s,
            sail_number = %s,
            boat_name = NULLIF(%s, ''),
            class_id = %s,
            class_original = %s,
            class_canonical = %s,
            fleet_label = COALESCE(NULLIF(fleet_label, ''), 'Open'),
            club_raw = NULLIF(%s, ''),
            club_id = COALESCE(%s, club_id),
            raced = TRUE,
            match_status_helm = CASE WHEN %s IS NOT NULL THEN 'entry_form' ELSE match_status_helm END,
            source_row_text = CASE
                WHEN %s <> '' THEN left('ENTRY: ' || %s, 500)
                ELSE source_row_text
            END
        WHERE result_id = %s
        """,
        (
            helm_name,
            helm_sid,
            crew_name,
            crew_sid,
            sail,
            boat,
            class_id_i,
            class_name,
            class_name,
            club,
            club_id,
            helm_sid,
            source_note,
            source_note,
            result_id,
        ),
    )
    return {
        "result_id": result_id,
        "rank": rank,
        "block_id": row.get("block_id"),
        "helm_name": helm_name,
        "sail_number": sail,
        "class_name": class_name,
    }


@app.post("/api/regatta-entry/submit")
async def api_regatta_entry_submit(request: Request, body: dict = Body(...)):
    """Store provisional entry AND write into live fleet results table."""
    rid = str(body.get("regatta_id") or "").strip()
    if not rid:
        raise HTTPException(status_code=400, detail="regatta_id required")
    entry = {
        "ts": datetime.now(timezone.utc).isoformat(),
        "regatta_id": rid,
        "event_name": body.get("event_name") or "",
        "first_name": body.get("first_name") or "",
        "last_name": body.get("last_name") or "",
        "sas_id": body.get("sas_id") or "",
        "club": body.get("club") or "",
        "role": body.get("role") or "",
        "teammate": body.get("teammate") or "",
        "teammate_sas_id": body.get("teammate_sas_id") or "",
        "class_id": body.get("class_id"),
        "class_name": body.get("class_name") or "",
        "class_free": bool(body.get("class_free")),
        "sail_number": body.get("sail_number") or "",
        "sail_free": bool(body.get("sail_free")),
        "boat_name": body.get("boat_name") or "",
        "note": body.get("note") or "",
    }
    Path("/var/www/sailingsa/data").mkdir(parents=True, exist_ok=True)
    with open("/var/www/sailingsa/data/regatta_entries.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps(entry, ensure_ascii=False) + "\n")

    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        applied = _regatta_entry_apply_to_fleet(cur, entry)
        conn.commit()
    except HTTPException:
        conn.rollback()
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=f"Fleet write failed: {e}")
    finally:
        cur.close()
        return_db_connection(conn)

    lines = [
        f"Event: {entry['event_name'] or rid}",
        f"Name: {entry['first_name']} {entry['last_name']}".strip(),
        f"SAS ID: {entry['sas_id'] or '—'}",
        f"Club: {entry['club'] or '—'}",
        f"Role: {entry['role']}",
        f"Class: {entry['class_name']}",
        f"Sail no: {entry['sail_number']}",
        f"Fleet rank: {applied.get('rank')}",
    ]
    summary = "\n".join(lines)
    return {
        "ok": True,
        "summary": summary,
        "mailto": "",
        "entry": entry,
        "rank": applied.get("rank"),
        "result_id": applied.get("result_id"),
        "live_url": f"/regatta/{rid}",
    }


@app.patch("/api/super-admin/regatta/{regatta_id}/event-info-strip")
async def api_super_admin_regatta_event_info_strip_patch(request: Request, regatta_id: str, body: dict = Body(...)):
    """Super-admin: show/hide + edit Live/Upcoming invite strip (below main header)."""
    if not _session_role_is_super_admin(request):
        raise HTTPException(status_code=403, detail="super_admin only")
    rid = str(regatta_id).strip()
    if not rid:
        raise HTTPException(status_code=400, detail="regatta_id required")
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="JSON object expected")
    items_in = body.get("items") if isinstance(body.get("items"), list) else []
    items_out = []
    for it in items_in:
        if not isinstance(it, dict):
            continue
        typ = str(it.get("type") or "note").strip().lower()[:32]
        row = {"type": typ}
        if typ == "pin":
            row["line1"] = str(it.get("line1") or "").strip()[:120]
            row["line2"] = str(it.get("line2") or "").strip()[:120]
        elif typ == "clock":
            row["text"] = str(it.get("text") or "").strip()[:400]
            # Clock date under NOT BEFORE… (header strip line2)
            row["line2"] = str(it.get("line2") or it.get("date") or "").strip()[:120]
        else:
            row["text"] = str(it.get("text") or "").strip()[:400]
        items_out.append(row)
    enter_in = body.get("enter") if isinstance(body.get("enter"), dict) else {}
    enter_out = {
        "label": str(enter_in.get("label") or "ENTER NOW").strip()[:64] or "ENTER NOW",
        "url": str(enter_in.get("url") or "").strip()[:500],
        "loud": bool(enter_in.get("loud", True)),
    }
    prev = _wc_regatta_event_info_strip_cfg(rid) or {}
    cfg = {
        "show": bool(body.get("show")),
        "items": items_out,
        "enter": enter_out,
    }
    en = str(body.get("event_name") or prev.get("event_name") or "").strip()
    if en:
        cfg["event_name"] = en[:200]
    _wc_regatta_event_info_strip_set(rid, cfg)
    return {"ok": True, "event_info_strip": _wc_regatta_event_info_strip_cfg(rid)}


