@app.patch("/api/super-admin/regatta/{regatta_id}/column-prefs")
async def api_super_admin_regatta_column_prefs_patch(request: Request, regatta_id: str, body: dict = Body(...)):
    """WC pilot: set which result columns are shown (same table for everyone after save)."""
    if not _session_role_is_super_admin(request):
        raise HTTPException(status_code=403, detail="super_admin only")
    rid = str(regatta_id).strip()
    if not _regatta_slug_is_sa_pilot_standalone(rid):
        raise HTTPException(status_code=403, detail="not editable for this regatta yet")
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="JSON object expected")
    patch = {}
    for k in _WC_COLUMN_PREF_KEYS:
        if k in body:
            patch[k] = bool(body[k])
    if not patch:
        raise HTTPException(status_code=400, detail="no known keys")
    _write_wc_regatta_column_prefs_for_regatta(rid, patch)
    return {"ok": True, "prefs": _merge_wc_column_prefs_for_regatta(rid)}


@app.post("/auth/login")
async def login(request: Request):
    """Login with SAS ID/WhatsApp and password"""
    try:
        body = await request.json()
        username = body.get("username") or body.get("email")
        password = body.get("password")
        provider = body.get("provider", "username")
        
        if not username or not password:
            return {"success": False, "error": "Username and password required"}
        
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        
        # Hash password for comparison
        password_hash = hashlib.sha256(password.encode('utf-8')).hexdigest()
        
        # Try to find account by SAS ID or WhatsApp number
        # Username can be SAS ID (numeric) or WhatsApp (10 digits)
        whatsapp_clean = re.sub(r'\D', '', str(username))[:10] if username else ''
        
        # Check if username looks like SAS ID (numeric) or WhatsApp (10 digits starting with 0)
        is_sas_id = username.isdigit() and len(username) <= 10
        is_whatsapp = len(whatsapp_clean) == 10 and whatsapp_clean.startswith('0')
        
        cur.execute("""
            SELECT account_id, sas_id, login_method, provider_id, email
            FROM public.user_accounts
            WHERE (
                (login_method = 'email' AND (sas_id = %s OR email = %s) AND password_hash = %s)
                OR (login_method = 'whatsapp' AND provider_id = %s AND password_hash = %s)
                OR (login_method = 'sas_id' AND sas_id = %s AND password_hash = %s)
            )
            LIMIT 1
        """, (
            username, username, password_hash,  # email login
            whatsapp_clean, password_hash,       # whatsapp login (with password check)
            username, password_hash              # sas_id login
        ))
        
        account = cur.fetchone()
        
        if not account:
            # Try alternative: check sas_id_personal for email/password match
            cur.execute("""
                SELECT ua.account_id, ua.sas_id, ua.login_method, ua.provider_id, ua.email
                FROM public.user_accounts ua
                JOIN public.sas_id_personal s ON s.sa_sailing_id = ua.sas_id
                WHERE (
                    (s.email = %s OR ua.sas_id = %s)
                    AND ua.password_hash = %s
                    AND ua.login_method IN ('email', 'sas_id')
                )
                LIMIT 1
            """, (username, username, password_hash))
            
            account = cur.fetchone()
        
        if not account:
            cur.close()
            return_db_connection(conn)
            return {"success": False, "error": "Invalid username or password"}
        
        # Fetch user name information from sas_id_personal or sailing_id
        user_name = None
        first_name = None
        last_name = None
        full_name = None
        
        if account['sas_id']:
            # Try to get name from sas_id_personal first
            cur.execute("""
                SELECT first_name, last_name, 
                       COALESCE(
                           NULLIF(TRIM(COALESCE(first_name, '') || ' ' || COALESCE(last_name, '')), ''),
                           full_name,
                           ''
                       ) as full_name
                FROM public.sas_id_personal
                WHERE sa_sailing_id = %s
                LIMIT 1
            """, (account['sas_id'],))
            
            personal_row = cur.fetchone()
            if personal_row:
                first_name = personal_row.get('first_name')
                last_name = personal_row.get('last_name')
                full_name = personal_row.get('full_name')
                # Construct full_name if not available
                if not full_name or not full_name.strip():
                    if first_name or last_name:
                        full_name = f"{first_name or ''} {last_name or ''}".strip()
            
            # If not found in sas_id_personal, try sailing_id
            if not full_name or not full_name.strip():
                cur.execute("""
                    SELECT first_name, last_name,
                           COALESCE(
                               NULLIF(TRIM(COALESCE(first_name, '') || ' ' || COALESCE(last_name, '')), ''),
                               display_name,
                               ''
                           ) as full_name
                    FROM public.sailing_id
                    WHERE sa_sailing_id = %s
                    LIMIT 1
                """, (account['sas_id'],))
                
                sailing_row = cur.fetchone()
                if sailing_row:
                    first_name = sailing_row.get('first_name')
                    last_name = sailing_row.get('last_name')
                    full_name = sailing_row.get('full_name')
                    # Construct full_name if not available
                    if not full_name or not full_name.strip():
                        if first_name or last_name:
                            full_name = f"{first_name or ''} {last_name or ''}".strip()
        
        # Create session (store IP, user_agent, device_type for admin dashboard)
        session_token = str(uuid.uuid4())
        expires_at = datetime.now() + timedelta(days=30)
        client_ip = _get_client_ip(request)
        user_agent = (request.headers.get("user-agent") or "")[:500]
        device_type = _derive_device_type(user_agent)
        cols = ["session_id", "account_id", "sas_id", "login_method", "expires_at", "ip_address", "user_agent"]
        vals = [session_token, account['account_id'], account['sas_id'], account['login_method'] or 'username', expires_at, client_ip or None, user_agent or None]
        if table_exists("user_sessions") and column_exists("user_sessions", "device_type"):
            cols.append("device_type")
            vals.append(device_type)
        cur.execute("INSERT INTO public.user_sessions (" + ", ".join(cols) + ") VALUES (" + ", ".join(["%s"] * len(vals)) + ")", vals)
        
        conn.commit()
        cur.close()
        return_db_connection(conn)
        
        return {
            "success": True,
            "session": session_token,
            "session_token": session_token,
            "sas_id": account['sas_id'],
            "login_method": account['login_method'] or 'username',
            "user": {
                "first_name": first_name,
                "last_name": last_name,
                "full_name": full_name
            }
        }
        
    except Exception as e:
        print(f"Error during login: {e}")
        traceback.print_exc()
        return {"success": False, "error": str(e)}

@app.post("/auth/logout")
async def logout(request: Request):
    """Logout user by clearing session. Prefer session_token from body so logout works when cookie is not sent."""
    conn = get_db_connection()
    cur = conn.cursor()
    try:
        body = {}
        try:
            if request.method == "POST":
                body = await request.json() or {}
        except Exception:
            pass
        session_token = (body.get("session_token") or request.cookies.get("session") or "").strip()
        if not session_token:
            cur.close()
            return_db_connection(conn)
            return {"success": True, "message": "No session to log out", "marked": False}

        rows_updated = 0
        if table_exists("user_sessions") and column_exists("user_sessions", "logout_time"):
            cur.execute("""
                UPDATE public.user_sessions
                SET logout_time = NOW()
                WHERE session_id = %s AND logout_time IS NULL
            """, (session_token,))
            rows_updated = cur.rowcount
        elif table_exists("user_sessions"):
            cur.execute("""
                DELETE FROM public.user_sessions
                WHERE session_id = %s
            """, (session_token,))
            rows_updated = cur.rowcount
        conn.commit()

        cur.execute("""
            DELETE FROM public.user_sessions
            WHERE expires_at <= NOW()
        """)
        conn.commit()

        cur.close()
        return_db_connection(conn)
        return {"success": True, "message": "Logged out successfully", "marked": rows_updated > 0}
    except Exception as e:
        print(f"Error during logout: {e}")
        traceback.print_exc()
        try:
            cur.close()
        except Exception:
            pass
        return_db_connection(conn)
        return {"success": False, "error": str(e), "marked": False}

