@app.get("/auth/facebook/callback")
async def facebook_callback(request: Request, code: Optional[str] = None, state: Optional[str] = None, error: Optional[str] = None):
    """Handle Facebook OAuth callback."""
    state_data = _parse_facebook_state(state)
    if not state_data:
        return _redirect_with_query("/login.html", {"error": "facebook_invalid_state"})
    flow = state_data.get("flow", "login")
    return_to = state_data.get("returnTo", "")
    landing_page = _oauth_landing_page(flow)

    if error:
        return _redirect_with_query(landing_page, {"error": "facebook_login_failed", "returnTo": return_to})
    if not code:
        return _redirect_with_query(landing_page, {"error": "facebook_no_code", "returnTo": return_to})
    if not FACEBOOK_APP_ID or not FACEBOOK_APP_SECRET:
        return _redirect_with_query(landing_page, {"error": "facebook_not_configured", "returnTo": return_to})

    conn = None
    try:
        redirect_uri = f"{_public_https_origin(request)}/auth/facebook/callback"
        async with httpx.AsyncClient(timeout=15.0) as client:
            token_response = await client.get(
                FACEBOOK_TOKEN_URL,
                params={
                    "client_id": FACEBOOK_APP_ID,
                    "client_secret": FACEBOOK_APP_SECRET,
                    "redirect_uri": redirect_uri,
                    "code": code,
                },
                headers={"Accept": "application/json"},
            )
            token_response.raise_for_status()
            token_data = token_response.json()
            access_token = token_data.get("access_token")
            if not access_token:
                return _redirect_with_query(landing_page, {"error": "facebook_token_failed", "returnTo": return_to})

            profile_response = await client.get(
                FACEBOOK_PROFILE_URL,
                params={
                    "fields": "id,name,first_name,last_name,email,picture.width(320).height(320)",
                    "access_token": access_token,
                },
                headers={"Accept": "application/json"},
            )
            profile_response.raise_for_status()
            profile_data = profile_response.json()

        facebook_id = str(profile_data.get("id") or "").strip()
        facebook_name = (profile_data.get("name") or "").strip()
        first_name = (profile_data.get("first_name") or "").strip()
        last_name = (profile_data.get("last_name") or "").strip()
        facebook_email = (profile_data.get("email") or "").strip()
        picture_url = ((profile_data.get("picture") or {}).get("data") or {}).get("url")

        if not facebook_id:
            return _redirect_with_query(landing_page, {"error": "facebook_no_id", "returnTo": return_to})

        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

        cur.execute(
            """
            SELECT account_id, sas_id
            FROM public.user_accounts
            WHERE login_method = 'facebook' AND provider_id = %s
            LIMIT 1
            """,
            (facebook_id,),
        )
        existing_account = cur.fetchone()
        if existing_account and existing_account.get("sas_id") and not str(existing_account.get("sas_id")).startswith("FB_"):
            session_token = _create_login_session_record(
                cur, request, existing_account["account_id"], existing_account["sas_id"], "facebook"
            )
            conn.commit()
            cur.close()
            return_db_connection(conn)
            conn = None
            return _redirect_with_query(
                landing_page,
                {"session": session_token, "returnTo": return_to},
            )

        if facebook_email:
            cur.execute(
                """
                SELECT account_id, sas_id
                FROM public.user_accounts
                WHERE email IS NOT NULL AND LOWER(email) = LOWER(%s)
                ORDER BY CASE WHEN login_method = 'email' THEN 0 ELSE 1 END, account_id ASC
                LIMIT 1
                """,
                (facebook_email,),
            )
            email_account = cur.fetchone()
            if email_account and email_account.get("sas_id"):
                facebook_account_id = _upsert_facebook_account(
                    cur,
                    email_account["sas_id"],
                    facebook_id,
                    facebook_email,
                    first_name,
                    last_name,
                    facebook_name,
                )
                session_token = _create_login_session_record(
                    cur, request, facebook_account_id, email_account["sas_id"], "facebook"
                )
                conn.commit()
                cur.close()
                return_db_connection(conn)
                conn = None
                return _redirect_with_query(
                    landing_page,
                    {"session": session_token, "returnTo": return_to},
                )

        cur.close()
        return_db_connection(conn)
        conn = None

        return _redirect_with_query(
            "/signup.html",
            {
                "facebook_signup": "1",
                "facebook_id": facebook_id,
                "facebook_email": facebook_email,
                "facebook_name": facebook_name,
                "facebook_first_name": first_name,
                "facebook_last_name": last_name,
                "facebook_picture": picture_url,
                "returnTo": return_to,
            },
        )
    except Exception as e:
        print(f"Facebook callback error: {e}")
        traceback.print_exc()
        return _redirect_with_query(landing_page, {"error": "facebook_callback_error", "returnTo": return_to})
    finally:
        if conn:
            try:
                return_db_connection(conn)
            except Exception:
                pass


