# ---------- SEO: clean /sailor/<slug> URLs (name-first), 301 from ?sas_id= ----------
def _slug_from_name(full_name: str) -> str:
    """Build URL slug from a **display** full name (token order = slug order). Use only for rows
    with **no** `helm_sa_sailing_id` / `crew_sa_sailing_id`. When a SAS id is present, slugs must
    come from `sas_id_personal` via `_batch_sailor_slugs_for_sas_ids` (catalogue `full_name` = truth)."""
    if not full_name or not isinstance(full_name, str):
        return ""
    s = full_name.strip().lower().replace("&", " and ")
    s = re.sub(r"[^\w\s\-]", "", s)
    s = re.sub(r"\s+", "-", s)
    s = re.sub(r"-+", "-", s).strip("-")
    return s


def _sailor_canonical_slug(full_name: str, sas_id: str, has_duplicate: bool) -> str:
    base = _slug_from_name(full_name)
    sid = str(sas_id or "").strip()
    if has_duplicate and sid.isdigit() and base:
        return base + "-" + sid
    return base or "sailor"


def _batch_sailor_slugs_for_sas_ids(sas_ids: list):
    """Return dict sas_id -> canonical_slug for regatta rows. Enables real /sailor/<slug> links."""
    if not sas_ids:
        return {}
    ids = list({str(i).strip() for i in sas_ids if i is not None and str(i).strip().isdigit()})
    if not ids:
        return {}
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT sa_sailing_id::text AS sas_id,
                    COALESCE(TRIM(full_name), TRIM(first_name || ' ' || COALESCE(last_name, ''))) AS full_name
                FROM public.sas_id_personal
                WHERE sa_sailing_id::text = ANY(%s)
            """, (ids,))
            rows = cur.fetchall()
            if not rows:
                return {}
            names_lower = list({(r.get("full_name") or "").strip().lower() for r in rows if (r.get("full_name") or "").strip()})
            name_count = {}
            if names_lower:
                cur.execute("""
                    SELECT LOWER(TRIM(COALESCE(full_name, first_name || ' ' || COALESCE(last_name, '')))) AS n, COUNT(*) AS c
                    FROM public.sas_id_personal
                    WHERE LOWER(TRIM(COALESCE(full_name, first_name || ' ' || COALESCE(last_name, '')))) = ANY(%s)
                    GROUP BY 1
                """, (names_lower,))
                name_count = {r["n"]: r["c"] for r in cur.fetchall()}
            out = {}
            for r in rows:
                sid = str(r.get("sas_id") or "")
                full_name = (r.get("full_name") or "").strip()
                if not full_name:
                    # Still emit a stable slug — never leave SAS-linked rows without a slug
                    # (callers must not fall back to PDF name order for URLs).
                    out[sid] = _sailor_canonical_slug("", sid, False)
                    continue
                has_dup = (name_count.get(full_name.lower()) or 0) > 1
                out[sid] = _sailor_canonical_slug(full_name, sid, has_dup)
            return out
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[api] _batch_sailor_slugs_for_sas_ids: {e}")
        return {}


def _get_sailor_by_sas_id_for_redirect(sas_id: str):
    """Return (full_name, canonical_slug) for sailor or (None, None) if not found. Used for 301 redirect."""
    if not sas_id or not str(sas_id).strip().isdigit():
        return None, None
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT sa_sailing_id::text AS sas_id,
                    COALESCE(TRIM(full_name), TRIM(first_name || ' ' || COALESCE(last_name, ''))) AS full_name
                FROM public.sas_id_personal
                WHERE sa_sailing_id::text = %s
                LIMIT 1
            """, (str(sas_id).strip(),))
            row = cur.fetchone()
            if not row:
                # Fallback: sailor in results but not sas_id_personal
                name_from_res, canon_from_res = _get_sailor_name_from_results(str(sas_id).strip())
                return (name_from_res, canon_from_res) if (name_from_res and canon_from_res) else (None, None)
            full_name = (row.get("full_name") or "").strip()
            if not full_name:
                return None, None
            slugs = _batch_sailor_slugs_for_sas_ids([str(sas_id).strip()])
            canonical = slugs.get(str(sas_id).strip()) or _slug_from_name(full_name)
            return full_name, canonical
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[SEO] _get_sailor_by_sas_id_for_redirect: {e}")
        return None, None


def _get_sailor_name_by_slug(slug: str):
    """Return (full_name, canonical_slug) for sailor or (None, None). Used for server-side SEO HTML."""
    if not slug or not slug.strip():
        return None, None
    slug = slug.strip()
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            m = re.match(r"^(.+)-(\d+)$", slug)
            if m:
                slug = m.group(1).strip()

            if slug.isdigit():
                sid = slug
                cur.execute("""
                    SELECT COALESCE(TRIM(full_name), TRIM(first_name || ' ' || COALESCE(last_name, ''))) AS full_name
                    FROM public.sas_id_personal WHERE sa_sailing_id::text = %s LIMIT 1
                """, (sid,))
                row = cur.fetchone()
                if row:
                    name = (row.get("full_name") or "").strip()
                    if name:
                        slugs = _batch_sailor_slugs_for_sas_ids([sid])
                        return name, slugs.get(sid) or _slug_from_name(name)
                name_from_results, _ = _get_sailor_name_from_results(sid)
                if name_from_results:
                    slugs = _batch_sailor_slugs_for_sas_ids([sid])
                    return name_from_results, slugs.get(sid) or _slug_from_name(name_from_results)
                return None, None
            # By name: normalize slug (hyphens and spaces -> single space) so "mia-strydom-wallis" matches "Mia Strydom-Wallis"
            name_from_slug = re.sub(r"\s+", " ", slug.replace("-", " ").strip()).lower()
            if not name_from_slug:
                return None, None
            cur.execute("""
                SELECT sa_sailing_id::text AS sas_id,
                    COALESCE(TRIM(full_name), TRIM(first_name || ' ' || COALESCE(last_name, ''))) AS full_name
                FROM public.sas_id_personal
                WHERE REGEXP_REPLACE(LOWER(TRIM(REPLACE(COALESCE(full_name, first_name || ' ' || COALESCE(last_name, '')), '-', ' '))), '\\s+', ' ', 'g') = %s
                LIMIT 2
            """, (name_from_slug,))
            rows = cur.fetchall()
            if not rows:
                # Fallback: name-only slug from results (regatta page links)
                name_from_res, sid_from_res = _get_sailor_by_name_slug_from_results(slug)
                if name_from_res and sid_from_res:
                    return name_from_res, _slug_from_name(name_from_res)
                return None, None
            r = rows[0]
            name = (r.get("full_name") or "").strip()
            sid = str(r.get("sas_id") or "")
            slugs = _batch_sailor_slugs_for_sas_ids([sid]) if sid and sid.isdigit() else {}
            return name, slugs.get(sid) or _slug_from_name(name)
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[SEO] _get_sailor_name_by_slug: {e}")
        return None, None


