# --- regatta auto host club logo (patch_regatta_auto_host_club_logo.py) ---
def _parse_host_club_abbrev_from_legacy(legacy: str) -> str:
    """Extract club abbrev from host display e.g. MAC - Milnerton Aquatic Club."""
    leg = re.sub(r"^host:\s*", "", (legacy or "").strip(), flags=re.I)
    if not leg:
        return ""
    m = re.match(r"^([A-Za-z0-9]{2,12})\s*-\s*.+", leg)
    if m:
        return m.group(1).strip().upper()
    if re.fullmatch(r"[A-Za-z0-9]{2,12}", leg):
        return leg.upper()
    return ""


def _regatta_host_club_code_resolved(
    host_club_abbrev: str,
    host_club_legacy: str = "",
    regatta_id: Optional[str] = None,
) -> str:
    """Host club code for header logo: join abbrev, legacy parse, DB host_club_code lookup."""
    a = (host_club_abbrev or "").strip().upper()
    if a:
        return a
    parsed = _parse_host_club_abbrev_from_legacy(host_club_legacy)
    if parsed:
        return parsed
    if regatta_id:
        ab = _wc_regatta_host_club_abbrev_for_regatta(str(regatta_id))
        if ab:
            return str(ab).strip().upper()
    return ""


# --- regatta header right: no SA fallback (patch_regatta_header_right_no_sa_fallback.py) ---
def _regatta_host_club_logo_src_for_code(code: str) -> Optional[str]:
    """Public URL for host club logo file when on disk (right header + SA editor preview)."""
    safe = re.sub(r"[^\w\-]", "", (code or "").strip())
    if not safe:
        return None
    disk = _club_logo_disk_path(safe)
    if disk:
        return "/artwork/Club Logo/" + os.path.basename(disk)
    return f"/api/club-logo/{safe.upper()}"


def _club_logo_disk_path(code: str) -> Optional[str]:
    """Return path to artwork/Club Logo/{code}.ext if present (case-insensitive)."""
    safe = re.sub(r"[^\w\-]", "", (code or "").strip())
    if not safe:
        return None
    for ext in ("png", "jpg", "jpeg"):
        p = os.path.join(CLUB_LOGO_DIR, safe + "." + ext)
        if os.path.isfile(p):
            return p
    try:
        want = safe.lower()
        for fn in os.listdir(CLUB_LOGO_DIR):
            base, ext = os.path.splitext(fn)
            if ext.lower().lstrip(".") in ("png", "jpg", "jpeg") and base.lower() == want:
                return os.path.join(CLUB_LOGO_DIR, fn)
    except OSError:
        pass
    return None


def _ensure_club_logo_cached(code: str, club_slug: Optional[str] = None) -> bool:
    """Ensure club logo PNG exists on disk; fetch from SAS club page when missing."""
    if _club_logo_disk_path(code):
        return True
    safe = re.sub(r"[^\w\-]", "", (code or "").strip())
    if not safe:
        return False
    slug = (club_slug or safe).strip().lower()
    if not slug:
        return False
    try:
        import urllib.request

        url = f"https://www.sailing.org.za/clubs/{slug}"
        req = urllib.request.Request(url, headers={"User-Agent": "SailingSA-regatta-header/1.0"})
        with urllib.request.urlopen(req, timeout=12) as resp:
            html = resp.read().decode("utf-8", errors="replace")
        m = re.search(
            r'https://cdn\.revolutionise\.com\.au/logos/[a-z0-9]+\.(?:png|jpg|jpeg)',
            html,
            re.I,
        )
        if not m:
            return False
        logo_url = m.group(0)
        with urllib.request.urlopen(
            urllib.request.Request(logo_url, headers={"User-Agent": "SailingSA-regatta-header/1.0"}),
            timeout=12,
        ) as lr:
            body = lr.read()
        if len(body) < 200:
            return False
        os.makedirs(CLUB_LOGO_DIR, exist_ok=True)
        dest = os.path.join(CLUB_LOGO_DIR, safe.upper() + ".png")
        with open(dest, "wb") as out:
            out.write(body)
        return True
    except Exception:
        return False


def _club_logo_file_exists_on_disk(code: str) -> bool:
    """True if artwork/Club Logo/{CODE}.(jpg|png|jpeg) exists (same as api_club_logo)."""
    return _club_logo_disk_path(code) is not None


def _regatta_header_right_club_logo_html(host_club_abbrev: str, host_club_slug: Optional[str]) -> str:
    """Right header slot: host club logo from disk only — never SA Sailing fallback."""
    code = re.sub(r"[^\w\-]", "", (host_club_abbrev or "").strip())
    img_cls = "regatta-header-logo-img regatta-header-club-logo-img"
    if code:
        _ensure_club_logo_cached(code, host_club_slug)
    if code and _club_logo_file_exists_on_disk(code):
        href = f"/club/{html_module.escape(host_club_slug)}" if host_club_slug else "/"
        disk = _club_logo_disk_path(code)
        src = (
            "/artwork/Club Logo/" + html_module.escape(os.path.basename(disk))
            if disk
            else f"/api/club-logo/{html_module.escape(code.upper())}"
        )
        return (
            f'<div class="regatta-header-club-logo-col">'
            f'<a href="{href}" class="regatta-header-logo-link" title="Host club">'
            f'<img src="{src}" alt="" class="{img_cls}" loading="lazy" decoding="async" />'
            f"</a></div>"
        )
    return '<div class="regatta-header-club-logo-col"></div>'


def _club_page_header_logo_html(club_abbrev: str, club_slug: str) -> str:
    """Club profile /club/{slug}: logo below ABBREV - Full Name when artwork exists on disk."""
    code = re.sub(r"[^\w\-]", "", (club_abbrev or "").strip())
    if not code:
        return ""
    _ensure_club_logo_cached(code, club_slug or None)
    if not _club_logo_file_exists_on_disk(code):
        return ""
    src = _regatta_host_club_logo_src_for_code(code)
    if not src:
        return ""
    alt = html_module.escape(f"{code} club logo")
    return (
        f'<div class="club-page-logo-wrap">'
        f'<img src="{html_module.escape(src)}" alt="{alt}" class="club-page-logo-img" '
        f'loading="lazy" decoding="async" />'
        f"</div>"
    )


def _regatta_standalone_left_logo_column_html(override_url: Optional[str]) -> str:
    """Left header column: default Sailing SA logo or super-admin WC custom image URL."""
    if not (override_url and str(override_url).strip()):
        return _REGATTA_STANDALONE_HEADER_LOGO_HTML
    src = html_module.escape(str(override_url).strip())
    return (
        '<div class="regatta-header-logo-col">'
        '<a href="/" class="regatta-header-logo-link" title="SailingSA home">'
        f'<img src="{src}" alt="" class="regatta-header-logo-img regatta-header-left-logo-img" '
        'loading="lazy" decoding="async" />'
        "</a></div>"
    )


def _regatta_standalone_right_logo_column_html(
    host_club_abbrev: str,
    host_club_slug: Optional[str],
    override_url: Optional[str] = None,
) -> str:
    """Right header: always host club logo from regattas.host_club_id (ignore JSON right)."""
    _ = override_url
    return _regatta_header_right_club_logo_html(host_club_abbrev, host_club_slug)


