def _resolve_fleet_shell_public_slug(slug: str) -> Optional[Tuple[str, str]]:
    """If public slug is master_regatta_id + '-' + fleet_tail matching block_id 'master:fleet_tail', return (regatta_id, block_id)."""
    if not slug or not str(slug).strip():
        return None
    if not table_exists("regatta_blocks"):
        return None
    s = str(slug).strip()
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute(
                """
                SELECT block_id, regatta_id
                FROM regatta_blocks
                WHERE strpos(block_id::text, ':') > 0
                  AND array_length(string_to_array(block_id::text, ':'), 1) = 2
                  AND %s = split_part(block_id::text, ':', 1) || '-' || split_part(block_id::text, ':', 2)
                LIMIT 2
                """,
                (s,),
            )
            rows = cur.fetchall() or []
            if len(rows) != 1:
                # Fleet tail in DB may be ilca-4.7 but bookmarks/nginx used ilca-47 (dotless).
                if s.endswith("-ilca-47"):
                    alt = s[: -len("-ilca-47")] + "-ilca-4.7"
                    cur.execute(
                        """
                        SELECT block_id, regatta_id
                        FROM regatta_blocks
                        WHERE strpos(block_id::text, ':') > 0
                  AND array_length(string_to_array(block_id::text, ':'), 1) = 2
                          AND %s = split_part(block_id::text, ':', 1) || '-' || split_part(block_id::text, ':', 2)
                        LIMIT 2
                        """,
                        (alt,),
                    )
                    rows = cur.fetchall() or []
            # block_id prefix can differ from canonical regatta_id (e.g. 385-…:420 vs URL 380-…-420).
            if len(rows) != 1:
                cur.execute(
                    """
                    SELECT block_id, regatta_id
                    FROM regatta_blocks
                    WHERE strpos(block_id::text, ':') > 0
                  AND array_length(string_to_array(block_id::text, ':'), 1) = 2
                      AND %s = regatta_id || '-' || split_part(block_id::text, ':', 2)
                    LIMIT 2
                    """,
                    (s,),
                )
                rows = cur.fetchall() or []
            if len(rows) != 1:
                return None
            block_id = str(rows[0].get("block_id") or "").strip()
            rid = str(rows[0].get("regatta_id") or "").strip()
            if not block_id or not rid:
                return None
            return (rid, block_id)
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[fleet_shell] _resolve_fleet_shell_public_slug: {e}")
    return None


# Invented / age-band public tails (PARENT_RESULT_URL_POLICY + AGE_CATEGORY_SUBFLEET).
# Profiles must link to the parent master URL when these child shells were never created.
_FLEET_URL_TAILS_FOR_PARENT_FALLBACK = (
    "overall-results",
    "u19-results",
    "u17-results",
    "420-fleet-under-19",
    "420-fleet-under-17",
)


def _parent_slug_from_fleet_public_url(slug: str) -> Optional[str]:
    """Strip known fleet-shell tails → parent master slug, or None."""
    s = str(slug or "").strip()
    if not s:
        return None
    for tail in _FLEET_URL_TAILS_FOR_PARENT_FALLBACK:
        suf = "-" + tail
        if s.endswith(suf) and len(s) > len(suf):
            return s[: -len(suf)]
    # Legacy single-class block tail ":420" → public "...-420"
    if s.endswith("-420") and len(s) > 4:
        return s[:-4]
    return None


def _redirect_missing_fleet_shell_to_parent(slug: str):
    """301 invented *-overall-results (etc.) URLs to the real parent /regatta/{master} when child shell missing."""
    parent = _parent_slug_from_fleet_public_url(slug)
    if not parent:
        return None
    reg = _get_regatta_by_regatta_id(parent) or _get_regatta_by_slug(parent)
    if not reg:
        return None
    canonical = str(reg[0] or parent).strip() or parent
    if canonical == str(slug).strip():
        return None
    return RedirectResponse(url=f"/regatta/{canonical}", status_code=301)


def _count_regatta_blocks(regatta_id: str) -> int:
    """Number of regatta_blocks rows for regatta (for fleet_shell vs class- URL policy)."""
    if not regatta_id or not table_exists("regatta_blocks"):
        return 0
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        try:
            cur.execute(
                "SELECT COUNT(*)::int AS n FROM regatta_blocks WHERE regatta_id = %s",
                (str(regatta_id).strip(),),
            )
            row = cur.fetchone()
            if not row:
                return 0
            try:
                v = row["n"]
            except (KeyError, TypeError, IndexError):
                v = row[0]
            return int(v) if v is not None else 0
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[regatta] _count_regatta_blocks: {e}")
    return 0


def _regatta_block_count(regatta_id: str) -> int:
    """Count fleet blocks on a regatta shell (1 = single-fleet, master-only public URL)."""
    rid = str(regatta_id or "").strip()
    if not rid or not table_exists("regatta_blocks"):
        return 0
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        try:
            cur.execute(
                "SELECT COUNT(*)::int FROM regatta_blocks WHERE regatta_id = %s",
                (rid,),
            )
            row = cur.fetchone()
            if not row:
                return 0
            try:
                return int(row[0])
            except (TypeError, IndexError, KeyError):
                return int(row["count"])
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[regatta] _regatta_block_count: {e}")
    return 0

_MIXED_SINGLE_FLEET_LABELS = frozenset({"overall", "open", "all", "mixed"})


def _fleet_label_matches_single_class(fleet_label: str, class_name: str) -> bool:
    """True when fleet title denotes the sole class (e.g. L26 Fleet / L26)."""
    if not fleet_label or not class_name:
        return False
    fl = fleet_label.strip()
    cn = class_name.strip()
    fl_core = re.sub(r"\s+fleet$", "", fl, flags=re.I).strip()
    if fl_core.lower() == cn.lower():
        return True
    if cn.lower() in fl.lower():
        return True
    cn_slug = _class_canonical_slug(cn)
    fl_slug = _class_canonical_slug(fl_core)
    return bool(cn_slug and fl_slug and cn_slug.lower() == fl_slug.lower())


def _single_fleet_is_mixed_or_overall(regatta_id: str) -> bool:
    """True when a single-fleet regatta ladder is Overall/mixed (no fleet=class sub-URL)."""
    rid = str(regatta_id or "").strip()
    if not rid:
        return False
    if table_exists("regatta_blocks"):
        try:
            conn = get_db_connection()
            cur = conn.cursor()
            try:
                cur.execute(
                    "SELECT COALESCE(NULLIF(TRIM(fleet_label), ''), NULLIF(TRIM(class_canonical), ''), '') "
                    "FROM regatta_blocks WHERE regatta_id = %s LIMIT 1",
                    (rid,),
                )
                row = cur.fetchone()
                if row:
                    try:
                        fl = str(row[0]).strip().lower()
                    except (TypeError, IndexError, KeyError):
                        fl = str(list(row.values())[0]).strip().lower()
                    fl_core = re.sub(r"\s+fleet$", "", fl, flags=re.I).strip()
                    if fl in _MIXED_SINGLE_FLEET_LABELS or fl_core in _MIXED_SINGLE_FLEET_LABELS:
                        return True
            finally:
                cur.close()
                return_db_connection(conn)
        except Exception as e:
            print(f"[regatta] _single_fleet_is_mixed_or_overall block: {e}", flush=True)
    if table_exists("results"):
        try:
            conn = get_db_connection()
            cur = conn.cursor()
            try:
                cur.execute(
                    "SELECT COUNT(DISTINCT COALESCE(NULLIF(TRIM(class_canonical), ''), NULLIF(TRIM(class_original), ''))) "
                    "FROM results WHERE regatta_id = %s",
                    (rid,),
                )
                row = cur.fetchone()
                n = int(row[0]) if row else 0
                return n > 1
            finally:
                cur.close()
                return_db_connection(conn)
        except Exception as e:
            print(f"[regatta] _single_fleet_is_mixed_or_overall classes: {e}", flush=True)
    return False

def _regatta_has_sibling_block(regatta_id: str, block_id: str) -> bool:
    """True if another fleet block exists for this regatta (multi-fleet umbrella — class URLs must not masquerade as fleet)."""
    if not regatta_id or not block_id:
        return False
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT EXISTS (
                    SELECT 1 FROM regatta_blocks rb
                    WHERE rb.regatta_id = %s AND rb.block_id IS DISTINCT FROM %s
                ) AS sibling
                """,
                (str(regatta_id).strip(), str(block_id).strip()),
            )
            row = cur.fetchone()
            if not row:
                return False
            try:
                v = row["sibling"]
            except (KeyError, TypeError, IndexError):
                v = row[0]
            return bool(v)
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[regatta] _regatta_has_sibling_block: {e}")
    return False


def _get_regatta_by_event_name_slug(slug: str):
    """Return (regatta_id, event_name, ...) when slugified event_name matches slug; else None. Used for 301 fallback only."""
    if not slug or not slug.strip():
        return None
    slug_norm = slug.strip().lower()
    try:
        if not table_exists("regattas"):
            return None
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT r.regatta_id, r.event_name, r.start_date, r.end_date,
                       r.host_club_id,
                       COALESCE(c.club_abbrev, c.club_fullname, '') AS host_club_name
                FROM regattas r
                LEFT JOIN clubs c ON c.club_id = r.host_club_id
                WHERE r.event_name IS NOT NULL AND TRIM(r.event_name) != ''
            """)
            for r in cur.fetchall() or []:
                name = (r.get("event_name") or "").strip()
                rid = str(r.get("regatta_id") or "").strip()
                if rid and _slugify_event_name(rid) == slug_norm:
                    return (
                        rid,
                        name or rid,
                        r.get("start_date"),
                        r.get("end_date"),
                        (r.get("host_club_name") or "").strip(),
                        r.get("host_club_id"),
                    )
                if not name:
                    continue
                cand = _slugify_event_name(name)
                if cand == slug_norm:
                    return (
                        str(r.get("regatta_id") or ""),
                        name,
                        r.get("start_date"),
                        r.get("end_date"),
                        (r.get("host_club_name") or "").strip(),
                        r.get("host_club_id"),
                    )
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[SEO] _get_regatta_by_event_name_slug: {e}")
    return None


def _get_regatta_by_slug(slug: str):
    """Return (regatta_id, event_name, start_date, end_date, host_club_name, host_club_id) for regatta slug or None."""
    if not slug or not slug.strip():
        return None
    s = slug.strip()
    # Prefer direct regatta_id match (existing routing)
    reg = _get_regatta_by_regatta_id(s)
    if reg:
        return reg
    # Backward-compatible alias: numeric-prefix slugs can drift (e.g. 385-... -> 380-...).
    # If id-prefixed slug does not exist, match by suffix after the first dash.
    m = re.match(r"^\d+-(.+)$", s)
    if m:
        tail = (m.group(1) or "").strip()
        if tail:
            try:
                conn = get_db_connection()
                cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
                try:
                    cur.execute("""
                        SELECT r.regatta_id, r.event_name, r.start_date, r.end_date,
                               COALESCE(c.club_abbrev, c.club_fullname, '') AS host_club_name,
                               c.club_id AS host_club_id
                        FROM regattas r
                        LEFT JOIN clubs c ON c.club_id = r.host_club_id
                        WHERE r.regatta_id ILIKE %s
                        ORDER BY COALESCE(r.end_date, r.start_date) DESC NULLS LAST, r.regatta_id
                        LIMIT 1
                    """, ('%-' + tail,))
                    row = cur.fetchone()
                    if row:
                        return (
                            row.get("regatta_id"),
                            row.get("event_name"),
                            row.get("start_date"),
                            row.get("end_date"),
                            row.get("host_club_name"),
                            row.get("host_club_id"),
                        )
                finally:
                    cur.close()
                    return_db_connection(conn)
            except Exception:
                pass
    # Else match by slugified event_name (used by sitemap / callers that want any match)
    return _get_regatta_by_event_name_slug(s)


def _format_rank(rank):
    """Fleet sheet rank label; same ordinals as _ordinal (1st, 7th, 11th, …)."""
    if rank is None:
        return ""
    try:
        num = int(rank)
    except (TypeError, ValueError):
        try:
            num = int(float(str(rank).strip()))
        except (TypeError, ValueError):
            return str(rank)
    out = _ordinal(num)
    return out if out else str(rank)




def _mac_endurance_fleet_sort_key(bl: dict) -> tuple:
    """Preserve PDF block order for MAC endurance regattas."""
    label = (bl.get("block_label_raw") or "").strip()
    bid = (bl.get("block_id") or "").lower()
    if label.startswith("1 —"):
        return (0, "")
    if label.startswith("2 —"):
        return (1, "")
    if label.startswith("3 —"):
        return (2, "")
    _class_sub_order = {
        "sonnet-handicap": 0,
        "saldanha-line-honours": 1,
    }
    if ":class-results:" in bid:
        tail = bid.rsplit(":", 1)[-1]
        return (3, _class_sub_order.get(tail, 99), label.lower())
    return (3, 99, label.lower())


def _strip_numbered_block_label_prefix(label: Optional[str]) -> str:
    """Display titles: drop sort-only '1 — ' / '2 - ' prefix from block_label_raw."""
    s = str(label or "").strip()
    if not s:
        return ""
    return re.sub(r"^\d+\s*[—–\-]\s*", "", s).strip()

def _regatta_fleets_sort_key(by_block: dict, bid: str) -> tuple:
    """Fleet order: numbered block_label_raw prefix (MAC sections), else display name, then block_id."""
    bl = by_block.get(bid) or {}
    raw = (bl.get("block_label_raw") or "").strip()
    m = re.match(r"^(\d+)\s*[—\-]", raw)
    if m:
        return (0, int(m.group(1)), bid)
    disp = (bl.get("name") or "").strip().lower()
    _medal = re.match(r"^(gold|silver|bronze)\b", disp)
    if _medal:
        return (0, {"gold": 0, "silver": 1, "bronze": 2}[_medal.group(1)], bid)
    return (1, disp, bid)



def _is_rsa_nationality(nat: Optional[str]) -> bool:
    n = (nat or "").strip().upper()
    return not n or n in ("RSA", "ZAF", "SA", "SOUTH AFRICA")


def _nationality_flag_asset_code(nat: Optional[str]) -> str:
    n = (nat or "").strip().upper()
    if not n:
        return ""
    if n in ("ZAF", "SA"):
        return "RSA"
    return n


def _nationality_flag_cell_html(nat: Optional[str]) -> str:
    code = _nationality_flag_asset_code(nat)
    if not code:
        return ""
    url = f"/artwork/International Flags/{code}.png"
    label = (nat or "").strip().upper()
    return (
        f'<img src="{html_module.escape(url)}" alt="{html_module.escape(label)}" '
        f'title="{html_module.escape(label)}" class="nat-flag" width="24" height="16" loading="lazy">'
    )

def _get_regatta_full_page_data(regatta_id: str, only_block_id: Optional[str] = None):
    """Return (event_name, host_club_name, start_date, end_date, fleets, result_status, as_at_time, host_club_province, host_club_abbrev, host_club_fullname) for standalone regatta page.
    host_club_abbrev / host_club_fullname: from clubs join for 'CODE - Full name' header.
    fleets = [{name, races_sailed, discard_count, to_count, scoring_system, entries, rows}].
    Each row = {rank, sail_number, helm_name, club, total, nett, race_scores, raced, class_name}.
    result_status: from regattas.result_status.
    as_at_time: for status line; from results table (one row) per Result rule, fallback to regattas.as_at_time."""
    t0 = time.time()
    print(f"REGATTA_DATA: step=start time={time.time() - t0:.3f}", flush=True)
    if not regatta_id or not table_exists("regattas") or not table_exists("regatta_blocks") or not table_exists("results"):
        return None
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            try:
                cur.execute("""
                    SELECT r.event_name, r.start_date, r.end_date,
                           COALESCE(c.club_abbrev, c.club_fullname, '') AS host_club_name,
                           TRIM(COALESCE(c.club_abbrev, '')) AS host_club_abbrev,
                           TRIM(COALESCE(c.club_fullname, '')) AS host_club_fullname,
                           c.province AS host_club_province,
                           r.result_status, r.as_at_time, r.scoring_system
                    FROM regattas r
                    LEFT JOIN clubs c ON c.club_id = r.host_club_id
                    WHERE r.regatta_id = %s
                """, (regatta_id,))
            except Exception:
                cur.execute("""
                    SELECT r.event_name, r.start_date, r.end_date,
                           COALESCE(c.club_abbrev, c.club_fullname, '') AS host_club_name,
                           TRIM(COALESCE(c.club_abbrev, '')) AS host_club_abbrev,
                           TRIM(COALESCE(c.club_fullname, '')) AS host_club_fullname,
                           c.province AS host_club_province
                    FROM regattas r
                    LEFT JOIN clubs c ON c.club_id = r.host_club_id
                    WHERE r.regatta_id = %s
                """, (regatta_id,))
            row = cur.fetchone()
            if not row:
                return None
            event_name = (row.get("event_name") or "").strip()
            host_club_name = (row.get("host_club_name") or "").strip()
            host_club_abbrev = (row.get("host_club_abbrev") or "").strip()
            host_club_fullname = (row.get("host_club_fullname") or "").strip()
            host_club_province = (row.get("host_club_province") or "").strip() or None
            start_date = row.get("start_date")
            end_date = row.get("end_date")
            result_status = (row.get("result_status") or "").strip() or "Final"
            as_at_time = row.get("as_at_time")
            print(f"REGATTA_DATA: step=after_regatta_meta time={time.time() - t0:.3f}", flush=True)
            # Status-line timestamp: prefer results table (per Result rule), fallback to regattas.as_at_time
            cur.execute("""
                SELECT as_at_time FROM results
                WHERE regatta_id = %s AND as_at_time IS NOT NULL
                ORDER BY result_id LIMIT 1
            """, (regatta_id,))
            res_row = cur.fetchone()
            if res_row and res_row.get("as_at_time"):
                as_at_time = res_row["as_at_time"]
            as_at_time = _resolve_regatta_status_as_at_time(
                regatta_id, end_date, start_date, as_at_time, cur=cur
            )
            print(f"REGATTA_DATA: step=after_as_at_time time={time.time() - t0:.3f}", flush=True)

            regatta_scoring = (row.get("scoring_system") or "").strip().lower()
            is_mac_endurance = regatta_scoring.startswith("mac endurance")
            results_join = "LEFT JOIN results res" if is_mac_endurance else "JOIN results res"
            cur.execute(f"""
                SELECT rb.block_id,
                       COALESCE(TRIM(rb.fleet_label), TRIM(rb.class_canonical), TRIM(rb.class_original), 'Fleet') AS fleet_name,
                       rb.fleet_label, rb.class_canonical,
                       rb.races_sailed, rb.discard_count, rb.to_count, rb.scoring_system, rb.rating_system,
                       rb.block_label_raw, rb.race_column_labels, rb.entries_raced, COALESCE(rb.entries_closed, FALSE) AS entries_closed,
                       res.result_id,
                       res.rank, res.sail_number, res.helm_name, res.crew_name,
                       res.boat_name, res.jib_no, res.bow_no, res.hull_no,
                res.hull_colour,
                       res.age_category,
                       res.nationality,
                       COALESCE(TRIM(c.club_abbrev), TRIM(res.club_raw), '') AS club,
                       res.club_id, COALESCE(c.club_abbrev, c.club_fullname) AS club_fullname,
                       res.helm_sa_sailing_id, s_helm.year_of_birth AS helm_year_of_birth, s_helm.age AS helm_current_age, res.crew_sa_sailing_id,
                       res.crew2_name, res.crew2_sa_sailing_id,
                       res.crew3_name, res.crew3_sa_sailing_id,
                       res.identity_status, res.match_status_helm, res.match_status_crew,
                       res.total_points_raw, res.nett_points_raw, res.race_scores, res.raced,
                       res.start_time, res.finish_time, res.duration_time, res.corrected_time, res.delta_time,
                       res.handicap, res.laps, res.aph, res.race_distance_nm, res.course_data,
                       COALESCE(NULLIF(TRIM(c_res.class_name), ''), NULLIF(TRIM(res.class_canonical), ''), NULLIF(TRIM(res.class_original), ''), '') AS class_name,
                       res.class_id AS result_class_id,
                       rb.class_id AS block_class_id,
                       cl_blk.logo_path AS class_logo_path,
                       cl_blk.icon_path AS class_icon_path
                FROM regatta_blocks rb
                LEFT JOIN classes cl_blk ON cl_blk.class_id = rb.class_id
                {results_join} ON res.block_id = rb.block_id AND res.regatta_id = rb.regatta_id
                LEFT JOIN clubs c ON c.club_id = res.club_id
                LEFT JOIN sas_id_personal s_helm ON s_helm.sa_sailing_id::text = res.helm_sa_sailing_id::text
                LEFT JOIN classes c_res ON c_res.class_id = res.class_id
                WHERE rb.regatta_id = %s
                  AND (%s IS NULL OR rb.block_id = %s)
                ORDER BY rb.block_id, COALESCE(res.rank, 99999), res.result_id
            """, (regatta_id, only_block_id, only_block_id))
            raw = cur.fetchall() or []
            print(f"REGATTA_DATA: step=after_main_join time={time.time() - t0:.3f}", flush=True)
            if str(regatta_id).strip() == WC_DINGHY_CHAMPS_REGATTA_SLUG:
                _wc_dinghy_apply_manual_helm_sas(raw)
                v_abb, _v_slug = _wc_lookup_velddrif_club_abbrev_slug(cur)
                if v_abb:
                    for _r in raw:
                        c = (_r.get("club") or "").strip()
                        if c and ("velddrif" in c.lower() or "port owen" in c.lower()):
                            _r["club"] = v_abb
            dup_names = set()
            cur.execute("""
                SELECT LOWER(TRIM(COALESCE(full_name, first_name || ' ' || COALESCE(last_name, '')))) AS n
                FROM sas_id_personal WHERE full_name IS NOT NULL OR first_name IS NOT NULL OR last_name IS NOT NULL
                GROUP BY LOWER(TRIM(COALESCE(full_name, first_name || ' ' || COALESCE(last_name, ''))))
                HAVING COUNT(*) > 1
            """)
            for row in cur.fetchall() or []:
                if row.get("n"):
                    dup_names.add(row["n"])
            # Batch name and slug lookups: one query for all sailor names, then slug in Python (no per-row DB)
            sas_ids = set()
            for r in raw:
                for _sid in (
                    r.get("helm_sa_sailing_id"),
                    r.get("crew_sa_sailing_id"),
                    r.get("crew2_sa_sailing_id"),
                    r.get("crew3_sa_sailing_id"),
                ):
                    if _sid is not None and str(_sid).strip().isdigit():
                        sas_ids.add(str(_sid).strip())
            name_map = {}
            slug_map = {}
            if sas_ids:
                cur.execute("""
                    SELECT sa_sailing_id::text AS sas_id,
                           COALESCE(TRIM(full_name), TRIM(first_name || ' ' || COALESCE(last_name, ''))) AS full_name
                    FROM sas_id_personal
                    WHERE sa_sailing_id::text = ANY(%s)
                """, (list(sas_ids),))
                for row in cur.fetchall() or []:
                    sid = str(row.get("sas_id") or "")
                    nm = (row.get("full_name") or "").strip()
                    name_map[sid] = nm
                    has_dup = nm.lower() in dup_names if nm else False
                    slug_map[sid] = _sailor_canonical_slug(nm, sid, has_dup) if nm else _sailor_canonical_slug("", sid, False)
                # SAS id on result row but no catalogue row: stable slug only — never PDF order
                for sid in sas_ids:
                    if sid not in slug_map:
                        slug_map[sid] = _sailor_canonical_slug("", sid, False)
                        name_map.setdefault(sid, "")
            print(f"REGATTA_DATA: step=after_dup_names time={time.time() - t0:.3f}", flush=True)
            boat_norm_slug_map = _load_boat_norm_slug_map()
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[regatta standalone] _get_regatta_full_page_data: {e}")
        return None
    print(f"REGATTA_DATA: step=after_db_calls time={time.time() - t0:.3f}", flush=True)
    fleets = []
    by_block = {}
    for r in raw:
        bid = r.get("block_id")
        rs = r.get("race_scores")
        if isinstance(rs, str) and rs:
            try:
                rs = json.loads(rs)
            except Exception:
                rs = {}
        if not isinstance(rs, dict):
            rs = {}
        if bid not in by_block:
            class_name_for_slug = (r.get("class_name") or "").strip()
            if _regatta_slug_is_sa_pilot_standalone(str(regatta_id).strip()):
                class_name_for_slug = _wc_dinghy_table_label_open_a_to_open(class_name_for_slug)
            class_slug = _class_canonical_slug(class_name_for_slug) if class_name_for_slug else ""
            _fleet_nm = (r.get("fleet_name") or "Fleet").strip()
            _fl_combine = (r.get("fleet_label") or r.get("class_canonical") or "").strip()
            _fleet_lb = _fl_combine
            if _regatta_slug_is_sa_pilot_standalone(str(regatta_id).strip()):
                _fleet_nm = _wc_dinghy_fleet_title_display(_fleet_nm)
                _fleet_lb = _wc_dinghy_fleet_title_display(_fleet_lb)
                _fleet_lb_cell = _wc_dinghy_fleet_column_cell_display(_wc_dinghy_fleet_title_display(_fl_combine))
            else:
                _fleet_lb_cell = _fleet_lb
            by_block[bid] = {
                "block_id": bid,
                "name": _fleet_nm,
                "fleet_label": _fleet_lb,
                "fleet_label_cell": _fleet_lb_cell,
                "races_sailed": r.get("races_sailed"),
                "discard_count": r.get("discard_count"),
                "to_count": r.get("to_count"),
                "scoring_system": r.get("scoring_system") or "Appendix A",
                "rating_system": r.get("rating_system"),
                "block_label_raw": r.get("block_label_raw"),
                "race_column_labels": r.get("race_column_labels"),
                "entries_raced": r.get("entries_raced"),
                "entries_closed": bool(r.get("entries_closed")),
                "rows": [],
                "regatta_id": regatta_id,
                "class_slug": class_slug,
                "class_id": r.get("block_class_id"),
                "class_canonical": (r.get("class_canonical") or "").strip(),
                "class_logo_path": (r.get("class_logo_path") or "").strip() or None,
                "class_icon_path": (r.get("class_icon_path") or "").strip() or None,
            }
        if r.get("result_id") is None:
            continue
        club_fn = (r.get("club_abbrev") or r.get("club_fullname") or "").strip()
        club_slug = _club_slug_from_name(club_fn or r.get("club") or "") if (r.get("club_id") and (club_fn or r.get("club"))) else None
        helm_name = r.get("helm_name")
        helm_sas_id = str(r.get("helm_sa_sailing_id") or "") if r.get("helm_sa_sailing_id") is not None else ""
        helm_slug = slug_map.get(helm_sas_id) if (helm_sas_id and helm_sas_id.isdigit()) else None
        crew_name = r.get("crew_name")
        crew_sas_id = str(r.get("crew_sa_sailing_id") or "") if r.get("crew_sa_sailing_id") is not None else ""
        crew_slug = slug_map.get(crew_sas_id) if (crew_sas_id and crew_sas_id.isdigit()) else None
        if not helm_slug and _result_row_identity_pending_helm(r):
            helm_slug = _identity_pending_name_slug(helm_name)
        if not crew_slug and _result_row_identity_pending_crew(r):
            crew_slug = _identity_pending_name_slug(crew_name)
        by_block[bid]["rows"].append({
            "result_id": r.get("result_id"),
            "rank": r.get("rank"),
            "sail_number": r.get("sail_number"),
            "helm_name": helm_name,
            "helm_slug": helm_slug,
            "helm_sa_sailing_id": r.get("helm_sa_sailing_id"),
            "helm_profile_from_name_only": bool(helm_slug and r.get("helm_sa_sailing_id") is None),
            "crew_name": crew_name,
            "crew_slug": crew_slug,
            "crew_sa_sailing_id": r.get("crew_sa_sailing_id"),
            "crew_profile_from_name_only": bool(crew_slug and r.get("crew_sa_sailing_id") is None),
            "crew2_name": r.get("crew2_name"),
            "crew2_slug": slug_map.get(str(r.get("crew2_sa_sailing_id")).strip())
            if r.get("crew2_sa_sailing_id") is not None and str(r.get("crew2_sa_sailing_id")).strip().isdigit()
            else None,
            "crew2_sa_sailing_id": r.get("crew2_sa_sailing_id"),
            "crew3_name": r.get("crew3_name"),
            "crew3_slug": slug_map.get(str(r.get("crew3_sa_sailing_id")).strip())
            if r.get("crew3_sa_sailing_id") is not None and str(r.get("crew3_sa_sailing_id")).strip().isdigit()
            else None,
            "crew3_sa_sailing_id": r.get("crew3_sa_sailing_id"),
            "boat_name": r.get("boat_name"),
            "boat_profile_slug": _boat_profile_slug_for_name(
                (r.get("boat_name") or "").strip(), boat_norm_slug_map
            ),
            "jib_no": r.get("jib_no"),
            "bow_no": r.get("bow_no"),
            "hull_no": r.get("hull_no"),
            "hull_colour": r.get("hull_colour"),
            "age_category": r.get("age_category"),
            "helm_year_of_birth": r.get("helm_year_of_birth"),
            "helm_current_age": r.get("helm_current_age"),
            "nationality": r.get("nationality"),
            "club": r.get("club") or r.get("club_abbrev") or r.get("club_raw"),
            "club_id": r.get("club_id"),
            "club_slug": club_slug,
            "total": r.get("total_points_raw"),
            "nett": r.get("nett_points_raw"),
            "race_scores": rs,
            "raced": r.get("raced"),
            "class_name": (
                "ILCA 4"
                if (
                    str(regatta_id).strip() == "2026-02-16-hyc-cape-classic"
                    and (r.get("fleet_label") or "").strip() == "ILCA 4"
                    and (r.get("class_name") or "").strip().casefold() in {"ilca 4.7", "ilca 4"}
                )
                else _wc_dinghy_table_label_open_a_to_open((r.get("class_name") or "").strip())
                if _regatta_slug_is_sa_pilot_standalone(str(regatta_id).strip())
                else (r.get("class_name") or "").strip()
            ),
            "start_time": r.get("start_time"),
            "finish_time": r.get("finish_time"),
            "duration_time": r.get("duration_time"),
            "corrected_time": r.get("corrected_time"),
            "delta_time": r.get("delta_time"),
            "handicap": r.get("handicap"),
            "laps": r.get("laps"),
            "aph": r.get("aph"),
            "race_distance_nm": r.get("race_distance_nm"),
            "course_data": r.get("course_data"),
            "result_class_id": r.get("result_class_id"),
            "match_status_class": r.get("match_status_class"),
            "class_catalogue_matched": r.get("result_class_id") is not None,
        })
    _mac_fleet_order = any(
        (by_block[b].get("scoring_system") or "").strip().lower().startswith("mac endurance")
        for b in by_block
    )
    _fleet_sort = (
        (lambda b: _mac_endurance_fleet_sort_key(by_block[b]))
        if _mac_fleet_order
        else (lambda b: _regatta_fleets_sort_key(by_block, b))
    )
    for bid in sorted(by_block.keys(), key=_fleet_sort):
        bl = by_block[bid]
        er = bl.get("entries_raced")
        bl["entries"] = int(er) if er is not None else len(bl["rows"])
        bl["host_club_abbrev"] = host_club_abbrev
        bl["host_club_slug"] = _club_slug_from_name(host_club_fullname or host_club_abbrev or "") if host_club_abbrev else None
        fleets.append(bl)
    # Multi-fleet regatta (PY Appendix A umbrella): public sub-URLs are fleet_shell …-{fast|slow}, never /class-*.
    # /regatta/{id}/class-* is a class slice (e.g. Topper-only) — wrong for fleet ladders that mix classes (Slow = Topper + Topaz + …).
    rid_s = str(regatta_id).strip()
    n_blocks = len(fleets)
    for bl in fleets:
        bid = str(bl.get("block_id") or "")
        if n_blocks > 1 and ":" in bid:
            tail = bid.split(":", 1)[1]
            bl["fleet_shell_href"] = f"/regatta/{quote(rid_s, safe='')}-{quote(tail, safe='')}"
        if n_blocks > 1:
            bl["class_slug"] = ""
        elif n_blocks == 1:
            fl = (bl.get("fleet_label") or bl.get("name") or "").strip()
            fl_lower = fl.lower()
            fl_core = re.sub(r"\s+fleet$", "", fl_lower, flags=re.I).strip()
            rows = bl.get("rows") or []
            row_classes = {(r.get("class_name") or "").strip() for r in rows if (r.get("class_name") or "").strip()}
            is_mixed = (
                fl_lower in _MIXED_SINGLE_FLEET_LABELS
                or fl_core in _MIXED_SINGLE_FLEET_LABELS
                or len(row_classes) > 1
            )
            if is_mixed:
                bl["class_slug"] = ""
            elif len(row_classes) == 1:
                only_class = next(iter(row_classes))
                if _fleet_label_matches_single_class(fl, only_class):
                    cn_slug = _class_canonical_slug(only_class)
                    bl["class_slug"] = cn_slug or (bl.get("class_slug") or "").strip()
                else:
                    bl["class_slug"] = ""
            else:
                bl["class_slug"] = (bl.get("class_slug") or "").strip()
    print(f"REGATTA_DATA: step=before_return time={time.time() - t0:.3f}", flush=True)
    return (
        event_name,
        host_club_name,
        start_date,
        end_date,
        fleets,
        result_status,
        as_at_time,
        host_club_province,
        host_club_abbrev,
        host_club_fullname,
    )


def _get_club_slug_by_id(club_id):
    """Return club slug for club_id or None."""
    if not club_id:
        return None
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute(
                "SELECT COALESCE(club_abbrev, club_fullname) AS name FROM clubs WHERE club_id = %s",
                (club_id,),
            )
            row = cur.fetchone()
            if row and row.get("name"):
                return _club_slug_from_name(str(row["name"]))
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception:
        pass
    return None


def _get_regatta_seo_preview(regatta_id: str):
    """Return dict with num_classes, num_sailors, class_names[], top_results[] for server-rendered SEO block."""
    out = {"num_classes": 0, "num_sailors": 0, "class_names": [], "top_results": []}
    if not regatta_id or not table_exists("regattas") or not table_exists("regatta_blocks") or not table_exists("results"):
        return out
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT COALESCE(TRIM(rb.fleet_label), TRIM(rb.class_canonical), TRIM(rb.class_original), 'Class') AS class_name
                FROM regatta_blocks rb
                WHERE rb.regatta_id = %s
                ORDER BY rb.block_id
            """, (regatta_id,))
            rows = cur.fetchall() or []
            seen = set()
            for r in rows:
                name = (r.get("class_name") or "Class").strip()
                if name and name not in seen:
                    seen.add(name)
                    out["class_names"].append(name)
            out["num_classes"] = len(out["class_names"])

            cur.execute("""
                SELECT COUNT(DISTINCT res.helm_sa_sailing_id::text) AS cnt
                FROM results res
                WHERE res.regatta_id = %s AND res.helm_sa_sailing_id IS NOT NULL
            """, (regatta_id,))
            row = cur.fetchone()
            if row and row.get("cnt") is not None:
                out["num_sailors"] = int(row["cnt"])
            if out["num_sailors"] == 0:
                cur.execute("SELECT COUNT(*) AS cnt FROM results res WHERE res.regatta_id = %s", (regatta_id,))
                row = cur.fetchone()
                if row and row.get("cnt") is not None:
                    out["num_sailors"] = int(row["cnt"])

            cur.execute("""
                SELECT DISTINCT ON (res.block_id, res.rank)
                       COALESCE(TRIM(res.helm_name), '') AS helm_name,
                       COALESCE(TRIM(rb.fleet_label), TRIM(rb.class_canonical), TRIM(rb.class_original), '') AS class_name,
                       res.rank
                FROM results res
                JOIN regatta_blocks rb ON rb.block_id = res.block_id AND rb.regatta_id = res.regatta_id
                WHERE res.regatta_id = %s AND res.rank IN (1, 2, 3)
                ORDER BY res.block_id, res.rank
                LIMIT 15
            """, (regatta_id,))
            for r in cur.fetchall() or []:
                out["top_results"].append({
                    "class_name": (r.get("class_name") or "").strip() or "—",
                    "rank": r.get("rank") or 0,
                    "helm_name": (r.get("helm_name") or "").strip() or "—",
                })
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[SEO] _get_regatta_seo_preview: {e}")
    return out


# Standalone /regatta/* sheets: same raster as site header (navy on white) — see sailingsa/frontend/css/main.css.
