def _wc_fleet_editable_cell(
    wc_sa_fleet_edit: bool,
    result_id_row,
    *,
    public_inner_html: str,
    value_plain: str,
    data_field: Optional[str] = None,
    race_key: Optional[str] = None,
    maxlength: int = 220,
    wrap_autocomplete: Optional[str] = None,
    extra_input_attrs: str = "",
    late_entry_block_id: Optional[str] = None,
) -> str:
    """Wrap public table cell HTML with a super-admin-only text input (WC standalone).
    When late_entry_block_id is set, render a NEW/Late entry input (no result_id yet)."""
    if not wc_sa_fleet_edit:
        return public_inner_html
    bid_late = (late_entry_block_id or "").strip()
    if bid_late:
        vq = html_module.escape(value_plain or "", quote=True)
        if race_key:
            rk = html_module.escape(race_key, quote=True)
            extra = f' data-race="{rk}"'
        else:
            if not data_field:
                return public_inner_html
            fk = html_module.escape(data_field, quote=True)
            extra = f' data-field="{fk}"'
        xin = extra_input_attrs or ""
        ac_cls = "wc-result-field-input wc-sa-edit-only"
        if wrap_autocomplete and xin and (
            "data-resolved-club-id" in xin or "data-resolved-class-id" in xin or "data-resolved-person-key" in xin
        ):
            ac_cls += " wc-sa-input--valid"
        bid_attr = html_module.escape(bid_late, quote=True)
        inp = (
            f'<input type="text" class="{ac_cls}" data-block-id="{bid_attr}" data-wc-late-entry="1"{extra}{xin} '
            f'data-original="{vq}" value="{vq}" maxlength="{maxlength}" autocomplete="off" />'
        )
        if wrap_autocomplete:
            ac = html_module.escape(wrap_autocomplete, quote=True)
            inp = (
                f'<div class="wc-sa-ac-wrap" data-wc-ac="{ac}">'
                f"{inp}"
                f'<div class="wc-sa-ac-preview"></div>'
                f'<ul class="wc-sa-ac-list" role="listbox" hidden></ul>'
                f"</div>"
            )
        return f'<span class="wc-sa-edit-hide">{public_inner_html}</span>' + inp
    if not result_id_row:
        return public_inner_html
    rid_attr = html_module.escape(str(result_id_row), quote=True)
    vq = html_module.escape(value_plain or "", quote=True)
    if race_key:
        rk = html_module.escape(race_key, quote=True)
        extra = f' data-race="{rk}"'
    else:
        if not data_field:
            return public_inner_html
        fk = html_module.escape(data_field, quote=True)
        extra = f' data-field="{fk}"'
    xin = extra_input_attrs or ""
    ac_cls = "wc-result-field-input wc-sa-edit-only"
    if wrap_autocomplete and xin and (
        "data-resolved-club-id" in xin or "data-resolved-class-id" in xin or "data-resolved-person-key" in xin
    ):
        ac_cls += " wc-sa-input--valid"
    inp = (
        f'<input type="text" class="{ac_cls}" data-result-id="{rid_attr}"{extra}{xin} '
        f'data-original="{vq}" value="{vq}" maxlength="{maxlength}" autocomplete="off" />'
    )
    if wrap_autocomplete:
        ac = html_module.escape(wrap_autocomplete, quote=True)
        inp = (
            f'<div class="wc-sa-ac-wrap" data-wc-ac="{ac}">'
            f"{inp}"
            f'<div class="wc-sa-ac-preview"></div>'
            f'<ul class="wc-sa-ac-list" role="listbox" hidden></ul>'
            f"</div>"
        )
    return f'<span class="wc-sa-edit-hide">{public_inner_html}</span>' + inp


# Fleet result sheet: one decimal everywhere only if some score is *fractionally* non-integer (ignore 4.0-style).
def _score_text_has_meaningful_decimal(s: str) -> bool:
    if not s:
        return False
    for m in re.finditer(r"\d+\.\d+", s):
        try:
            x = float(m.group(0))
        except ValueError:
            return True
        if abs(x - round(x)) > 1e-9:
            return True
    return False


def _block_scores_need_decimal_display(rows: list) -> bool:
    for r in rows or []:
        for key in ("total", "nett"):
            v = r.get(key)
            if v is None:
                continue
            sv = str(v).strip()
            if not sv:
                continue
            if _score_text_has_meaningful_decimal(sv):
                return True
            if isinstance(v, float) and not v.is_integer():
                return True
            try:
                fv = float(v)
            except (TypeError, ValueError):
                continue
            if abs(fv - round(fv)) > 1e-9:
                return True
        rs = r.get("race_scores") or {}
        if isinstance(rs, str) and rs.strip():
            try:
                rs = json.loads(rs)
            except Exception:
                rs = {}
        if not isinstance(rs, dict):
            continue
        for rk, val in rs.items():
            if not str(rk).upper().startswith("R"):
                continue
            s = (val or "").strip() if isinstance(val, str) else str(val)
            if not s:
                continue
            if _score_text_has_meaningful_decimal(s):
                return True
            inner = s[1:-1].strip() if (s.startswith("(") and s.endswith(")")) else s
            m = re.match(r"^([\d.]+)", inner)
            if m:
                try:
                    x = float(m.group(1))
                except ValueError:
                    continue
                if abs(x - round(x)) > 1e-9:
                    return True
    return False


def _format_total_nett_display(val, use_decimals: bool) -> str:
    if val is None:
        return ""
    try:
        if isinstance(val, str):
            st = val.strip()
            if not st:
                return ""
            f = float(st)
        else:
            f = float(val)
    except (TypeError, ValueError):
        return str(val).strip() if val is not None else ""
    if use_decimals:
        return f"{f:.1f}"
    ir = int(round(f))
    return str(ir) if abs(f - ir) < 1e-9 else f"{f:.1f}"


def _format_race_cell_display(score: str, use_decimals: bool) -> str:
    s = (score or "").strip()
    if not s:
        return s
    wrapped = s.startswith("(") and s.endswith(")")
    inner = s[1:-1].strip() if wrapped else s
    m = re.match(r"^([\d.]+)(.*)$", inner)
    if not m:
        return s
    num_s, rest = m.group(1), m.group(2)
    try:
        v = float(num_s)
    except ValueError:
        return s
    if use_decimals:
        num_out = f"{v:.1f}"
    else:
        ir = int(round(v))
        num_out = str(ir) if abs(v - ir) < 1e-9 else num_s
    out = num_out + rest
    return f"({out})" if wrapped else out


def _wc_late_entry_strip_html(
    fleet: dict,
    *,
    column_prefs: Optional[dict],
    wc_sa_fleet_edit: bool,
    thead: str,
    race_columns: list,
    show_boat: bool,
    show_jib: bool,
    show_bow: bool,
    show_hull: bool,
    show_club: bool,
    show_crew_col: bool,
    show_category: bool = False,
) -> str:
    """NEW/Late strip + on-hold list; thead/race columns must match the main fleet table."""
    prefs = column_prefs if isinstance(column_prefs, dict) else None

    def _pref_on(key: str) -> bool:
        if prefs is None:
            return True
        if key not in prefs:
            return True
        return bool(prefs.get(key))

    regatta_id = fleet.get("regatta_id")
    bid_for_late = (fleet.get("block_id") or "").strip()
    _fl_late_raw = (fleet.get("fleet_label") or "").strip()
    fleet_label = fleet.get("fleet_label_cell") or _wc_dinghy_fleet_column_cell_display(
        _wc_dinghy_fleet_title_display(_fl_late_raw)
    )
    if (
        not wc_sa_fleet_edit
        or not _regatta_slug_is_sa_pilot_standalone(str(regatta_id or ""))
        or not bid_for_late
    ):
        return ""

    late_class_raw = ""
    late_class_str = ""
    late_class_xin = ""

    def _late_cell(
        inner_html: str,
        plain: str,
        field: Optional[str] = None,
        race_k: Optional[str] = None,
        mx: int = 220,
        ac: Optional[str] = None,
        xin: str = "",
    ) -> str:
        return _wc_fleet_editable_cell(
            wc_sa_fleet_edit,
            None,
            public_inner_html=inner_html,
            value_plain=plain,
            data_field=field,
            race_key=race_k,
            maxlength=mx,
            wrap_autocomplete=ac,
            extra_input_attrs=xin,
            late_entry_block_id=bid_for_late,
        )

    late_tr = '<tr class="wc-late-entry-tr medal-gold">'
    if _pref_on("rank"):
        late_tr += (
            '<td class="rank-col">'
            '<button type="button" class="wc-rank-menu-hit wc-rank-menu-hit--late" '
            'aria-haspopup="true" aria-expanded="false" aria-label="New entry: hold or add to fleet">—</button>'
            "</td>"
        )
    if _pref_on("fleet"):
        late_tr += f'<td class="fleet-col">{html_module.escape(fleet_label)}</td>'
    if _pref_on("class"):
        late_tr += f'<td class="class-col">{_late_cell(late_class_str, late_class_raw, "class_name", None, 64, "class", late_class_xin)}</td>'
    if _pref_on("sail_no"):
        late_tr += f'<td class="sail-col">{_late_cell("", "", "sail_number", None, 32)}</td>'
    if show_boat:
        late_tr += f'<td class="wc-meta-col">{_late_cell("", "", "boat_name", None, 120)}</td>'
    if show_jib:
        late_tr += f'<td class="wc-meta-col">{_late_cell("", "", "jib_no", None, 32)}</td>'
    if show_bow:
        late_tr += f'<td class="wc-meta-col">{_late_cell("", "", "bow_no", None, 32)}</td>'
    if show_hull:
        late_tr += f'<td class="wc-meta-col">{_late_cell("", "", "hull_no", None, 32)}</td>'
    if show_club:
        late_tr += f'<td class="club-col">{_late_cell("", "", "club_code", None, 32, "club", "")}</td>'
    if _pref_on("helm"):
        late_tr += f'<td class="helm-col">{_late_cell("", "", "helm_name", None, 120, "helm", "")}</td>'
    if show_category:
        late_tr += '<td class="wc-meta-col"></td>'
    if show_crew_col:
        late_tr += f'<td class="crew-col">{_late_cell("", "", "crew_name", None, 160, "crew", "")}</td>'
    if race_columns:
        for rkey in race_columns:
            late_tr += f'<td class="race-col">{_late_cell("", "", None, rkey, 48)}</td>'
    if _pref_on("total"):
        late_tr += f'<td class="total-col">{_late_cell("", "", "total_points_raw", None, 24)}</td>'
    if _pref_on("nett"):
        late_tr += f'<td class="nett-col">{_late_cell("", "", "nett_points_raw", None, 24)}</td>'
    late_tr += "</tr>"
    rid_for_holds = html_module.escape(str(regatta_id or "").strip(), quote=True)
    bid_esc = html_module.escape(bid_for_late, quote=True)
    holds_inner = _wc_render_entry_holds_inner_html(str(regatta_id or "").strip())
    return (
        f'<div class="wc-late-entry-strip wc-late-entry-strip--below-prefs" role="region" aria-label="New late entry" '
        f'data-regatta-id="{rid_for_holds}" data-anchor-block-id="{bid_esc}">'
        f'<div class="wc-late-entry-label">NEW / Late entry</div>'
        f'<div class="table-wrapper"><table class="fleet-results-table wc-late-entry-table">'
        f"<thead><tr>{thead}</tr></thead><tbody>{late_tr}</tbody></table></div>"
        f'<div class="wc-entry-holds-panel" id="wcEntryHoldsPanel">'
        f'<div class="wc-entry-holds-title">On hold</div>'
        f'<div id="wcEntryHoldsListInner" class="wc-entry-holds-list-inner">{holds_inner}</div>'
        f"</div></div>"
    )


def _regatta_public_club_display_and_slug(row: dict) -> Tuple[str, Optional[str]]:
    """Show PDF club text; only add a link when the club is validated."""
    raw = str(
        row.get("club")
        or row.get("club_abbrev")
        or row.get("club_raw")
        or ""
    ).strip()
    low = raw.lower()
    if not raw or low in ("none", "unk", "unk.", "null", "n/a", "-"):
        return "", None
    if not row.get("club_id"):
        return raw, None
    return raw, row.get("club_slug")



def _fleet_shows_pcs_timing_columns(scoring_system: str | None, rows: list) -> bool:
    """Full PCS timing block (APH + Finish/Elapsed/Corrected/Delta) — not PHRFTOT handicap alone."""
    ss = (scoring_system or "").upper()
    if "PCS" in ss or "CONSTRUCTED" in ss:
        return True
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        for k in ("corrected_time", "duration_time", "finish_time", "delta_time", "aph"):
            v = r.get(k)
            if v is not None and str(v).strip():
                return True
    return False


def _fleet_shows_handicap_rating_column(
    fleet: dict, rows: list, *, show_pcs_times: bool
) -> tuple[bool, str]:
    """Appendix A + PHRFTOT: one rating column only (PDF PHRFTOT), not empty PCS timing cols."""
    if show_pcs_times:
        return False, ""
    label = (fleet.get("rating_system") or "APH").strip() or "APH"
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        if str(r.get("handicap") or "").strip():
            return True, label
    return False, ""


def _fleet_start_time_sast_line(rows: list) -> str:
    """Race start for sailed line: first row start_time as DD/MM/YYYY HH:MM:SS in SAST (GMT+2)."""
    try:
        from zoneinfo import ZoneInfo

        z_sa = ZoneInfo("Africa/Johannesburg")
    except Exception:
        return ""
    raw = None
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        v = r.get("start_time")
        if v is None:
            continue
        if isinstance(v, str) and not str(v).strip():
            continue
        raw = v
        break
    if raw is None:
        return ""
    try:
        if isinstance(raw, datetime):
            dt = raw
        else:
            s = str(raw).strip().replace("Z", "+00:00")
            if len(s) >= 19 and "T" in s[:25]:
                dt = datetime.fromisoformat(s[:26])
            elif len(s) >= 19:
                dt = datetime.strptime(s[:19], "%Y-%m-%d %H:%M:%S")
            else:
                return ""
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        loc = dt.astimezone(z_sa)
        return "Start: " + loc.strftime("%d/%m/%Y %H:%M:%S") + " (GMT+2)"
    except Exception:
        return ""


def _course_data_footer_html(rows: list) -> str:
    def _angle_cell(v) -> str:
        s = str(v if v is not None else "").strip()
        if not s:
            return ""
        if "°" in s:
            return html_module.escape(s)
        try:
            float(s.replace(",", "."))
            return html_module.escape(s + "°")
        except ValueError:
            return html_module.escape(s)

    cd = None
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        raw = r.get("course_data")
        if not raw:
            continue
        if isinstance(raw, str) and raw.strip():
            try:
                cd = json.loads(raw)
            except Exception:
                cd = None
        elif isinstance(raw, list):
            cd = raw
        if isinstance(cd, list) and cd:
            break
    if not isinstance(cd, list) or not cd:
        return ""
    parts = [
        '<div class="wc-course-data-footer" style="margin-top:12px;padding:12px 16px;border:1px solid #1d294d;border-radius:8px;background:#f8fafc;font-size:13px;text-align:center;">',
        '<strong style="display:block;font-size:1.1rem;font-weight:700;margin:0 0 10px 0;">Course data</strong>',
        '<table style="margin-left:auto;margin-right:auto;width:100%;max-width:48rem;border-collapse:collapse;font-size:12px;text-align:center;">',
        "<thead><tr>"
        '<th style="font-weight:700;">Leg</th>'
        '<th style="font-weight:700;">TWD</th>'
        '<th style="font-weight:700;">TWS</th>'
        '<th style="font-weight:700;">Bearing</th>'
        '<th style="font-weight:700;">Distance (nm)</th>'
        "</tr></thead><tbody>",
    ]
    for i, leg in enumerate(cd, start=1):
        if not isinstance(leg, dict):
            continue
        twd_h = _angle_cell(leg.get("twd"))
        brg_h = _angle_cell(leg.get("bearing"))
        tws_raw = str(leg.get("tws") or "").strip()
        tws_h = html_module.escape(tws_raw) if tws_raw else ""
        dist_raw = str(leg.get("distance") or "").strip()
        dist_h = html_module.escape(dist_raw) if dist_raw else ""
        parts.append(
            "<tr>"
            f"<td>{i}</td>"
            f"<td>{twd_h}</td>"
            f"<td>{tws_h}</td>"
            f"<td>{brg_h}</td>"
            f"<td>{dist_h}</td>"
            "</tr>"
        )
    parts.append("</tbody></table></div>")
    return "".join(parts)


def _sailed_line_scoring_template_display(regatta_id: Optional[str], scoring_system: str) -> str:
    """Fleet status line — show template family on the page (Windsurfer / PCS Gimco), not only 'Appendix A'."""
    rid = str(regatta_id or "").strip()
    ss = (scoring_system or "").strip() or "Appendix A"
    if rid == "2026-03-22-windsurfer-lt-nationals":
        return "Windsurfer LT"
    if rid == "2026-02-01-rcyc-gimco" or rid.startswith("2026-02-01-rcyc-gimco-"):
        if "PCS" in ss.upper() or "CONSTRUCTED" in ss.upper():
            return ss
        return "PCS - Constructed Course"
    return ss




def _fleet_is_mac_endurance_laps(fleet: dict) -> bool:
    """True when block uses MAC 24hr-style laps scoring (not Appendix A)."""
    ss = (fleet.get("scoring_system") or "").strip().lower()
    return ss.startswith("mac endurance")


def _mac_block_is_class_results_header(fleet: dict) -> bool:
    """True for MAC class-results block with no result rows yet (header-only section)."""
    bid = (fleet.get("block_id") or "").strip().lower()
    if not bid.endswith(":class-results"):
        return False
    return not (fleet.get("rows") or [])


def _mac_block_is_class_dual_laps(fleet: dict) -> bool:
    """True for MAC class sub-block ranked by laps + laps handicap (no Class column)."""
    bid = (fleet.get("block_id") or "").lower()
    if ":class-results:" not in bid:
        return False
    label = (fleet.get("block_label_raw") or "").lower()
    return "handicap" in label


def _mac_block_is_class_line_laps(fleet: dict) -> bool:
    """True for MAC class sub-block with line-honours laps only (Rank/Boat/Laps)."""
    bid = (fleet.get("block_id") or "").lower()
    if ":class-results:" not in bid:
        return False
    label = (fleet.get("block_label_raw") or "").lower()
    return "line honour" in label or "line honor" in label




def _mac_endurance_fleet_header_html(
    fleet: dict,
    regatta_id: str,
    header_title: str,
    sailed_line: str,
) -> str:
    """MAC laps block header with optional fleet logos (JSON fleet_logos / class logo)."""
    left_col, right_col = _fleet_class_header_logo_columns_html(fleet, regatta_id)
    title_s = html_module.escape(header_title)
    line_s = html_module.escape(sailed_line)
    if left_col or right_col:
        return (
            '<div class="class-header class-header--with-logos">'
            f"{left_col}"
            '<div class="class-header-main-col">'
            f'<div class="fleet-title-row">{title_s}</div>'
            f'<div class="sailed-line">{line_s}</div>'
            "</div>"
            f"{right_col}"
            "</div>"
        )
    return (
        f'<div class="class-header"><div class="fleet-title-row">{title_s}</div>'
        f'<div class="sailed-line">{line_s}</div></div>'
    )

def _render_mac_endurance_laps_fleet(fleet: dict) -> str:
    """MAC endurance: block header + Ranked by Laps subtitle + Rank/Boat/Class/Laps table."""
    block_id = (fleet.get("block_id") or "").strip()
    header_title = (fleet.get("block_label_raw") or fleet.get("name") or "Results").strip()
    rows = list(fleet.get("rows") or [])
    is_header_only = _mac_block_is_class_results_header(fleet)
    entries = fleet.get("entries")
    if entries is None:
        entries = fleet.get("entries_raced") or len(rows)
    rank_subtitle = (fleet.get("rating_system") or "").strip()
    if is_header_only:
        sailed_line = f"Entries: {int(entries)}"
    elif rank_subtitle:
        sailed_line = f"{rank_subtitle}, Entries: {int(entries)}"
    else:
        sailed_line = f"Entries: {int(entries)}"
    bid_attr = f' data-block-id="{html_module.escape(block_id, quote=True)}"' if block_id else ""
    _mac_rid = str(fleet.get("regatta_id") or "").strip()
    if is_header_only:
        return (
            f'<div class="fleet-section mac-endurance-laps"{bid_attr}>'
            + _mac_endurance_fleet_header_html(fleet, _mac_rid, header_title, sailed_line)
            + "</div>"
        )
    if _mac_block_is_class_dual_laps(fleet):
        def _rank_sort_key(x: dict):
            try:
                return (int(x.get("rank") or 10**9), str(x.get("result_id") or ""))
            except (TypeError, ValueError):
                return (10**9, str(x.get("result_id") or ""))

        rows.sort(key=_rank_sort_key)
        trs = []
        for r in rows:
            rk = r.get("rank")
            boat = html_module.escape(str(r.get("boat_name") or "").strip())
            laps_raw = r.get("laps") or ""
            hcap_raw = r.get("handicap") or ""
            laps_val = laps_raw.strip() if isinstance(laps_raw, str) else str(laps_raw or "").strip()
            hcap_val = hcap_raw.strip() if isinstance(hcap_raw, str) else str(hcap_raw or "").strip()
            try:
                rank_num = int(rk) if rk is not None else 0
            except (TypeError, ValueError):
                rank_num = 0
            rank_str = _format_rank(rk)
            medal_class = ""
            if rank_num == 1:
                medal_class = "medal-gold"
            elif rank_num == 2:
                medal_class = "medal-silver"
            elif rank_num == 3:
                medal_class = "medal-bronze"
            trs.append(
                f'<tr class="{medal_class}">'
                f'<td class="rank-col">{html_module.escape(rank_str)}</td>'
                f'<td class="boat-col">{boat}</td>'
                f'<td class="laps-col">{html_module.escape(laps_val)}</td>'
                f'<td class="laps-col">{html_module.escape(hcap_val)}</td>'
                + "</tr>"
            )
        thead = (
            '<th class="rank-col">Rank</th>'
            '<th class="boat-col">Boat</th>'
            '<th class="laps-col">Laps</th>'
            '<th class="laps-col">Laps (H-Cap)</th>'
        )
        table_html = f'<table class="fleet-results-table mac-laps-table"><thead><tr>{thead}</tr></thead><tbody>{"".join(trs)}</tbody></table>'
        return (
            f'<div class="fleet-section mac-endurance-laps mac-class-subtable"{bid_attr}>'
            + _mac_endurance_fleet_header_html(fleet, _mac_rid, header_title, sailed_line)
            + f'<div class="table-wrapper">{table_html}</div></div>'
        )

    if _mac_block_is_class_line_laps(fleet):
        def _rank_sort_key(x: dict):
            try:
                return (int(x.get("rank") or 10**9), str(x.get("result_id") or ""))
            except (TypeError, ValueError):
                return (10**9, str(x.get("result_id") or ""))

        rows.sort(key=_rank_sort_key)
        trs = []
        for r in rows:
            rk = r.get("rank")
            boat = html_module.escape(str(r.get("boat_name") or "").strip())
            laps_raw = r.get("laps") or ""
            laps_val = laps_raw.strip() if isinstance(laps_raw, str) else str(laps_raw or "").strip()
            try:
                rank_num = int(rk) if rk is not None else 0
            except (TypeError, ValueError):
                rank_num = 0
            rank_str = _format_rank(rk)
            medal_class = ""
            if rank_num == 1:
                medal_class = "medal-gold"
            elif rank_num == 2:
                medal_class = "medal-silver"
            elif rank_num == 3:
                medal_class = "medal-bronze"
            trs.append(
                f'<tr class="{medal_class}">'
                f'<td class="rank-col">{html_module.escape(rank_str)}</td>'
                f'<td class="boat-col">{boat}</td>'
                f'<td class="laps-col">{html_module.escape(laps_val)}</td>'
                + "</tr>"
            )
        thead = (
            '<th class="rank-col">Rank</th>'
            '<th class="boat-col">Boat</th>'
            '<th class="laps-col">Laps</th>'
        )
        table_html = f'<table class="fleet-results-table mac-laps-table"><thead><tr>{thead}</tr></thead><tbody>{"".join(trs)}</tbody></table>'
        return (
            f'<div class="fleet-section mac-endurance-laps mac-class-subtable"{bid_attr}>'
            + _mac_endurance_fleet_header_html(fleet, _mac_rid, header_title, sailed_line)
            + f'<div class="table-wrapper">{table_html}</div></div>'
        )

    rl = rank_subtitle.lower() if rank_subtitle else ""
    is_handicap_block = "handicap" in rl
    laps_col = "Laps (Handicap)" if is_handicap_block else "Laps"

    def _rank_sort_key(x: dict):
        try:
            return (int(x.get("rank") or 10**9), str(x.get("result_id") or ""))
        except (TypeError, ValueError):
            return (10**9, str(x.get("result_id") or ""))

    rows.sort(key=_rank_sort_key)
    regatta_id = str(fleet.get("regatta_id") or "").strip()

    def _class_cell(r: dict) -> str:
        cn = (r.get("class_name") or r.get("class_canonical") or r.get("class_original") or "").strip()
        if cn.startswith("Sonnet (") or cn.startswith("Sonnet("):
            cn = "Sonnet"
        if not cn:
            return '<td class="class-col"></td>'
        cid = r.get("result_class_id") or r.get("class_id")
        slug = ""
        if cid:
            try:
                slug = _class_canonical_slug(cn) or ""
            except Exception:
                slug = ""
        if cid is not None and cn:
            try:
                canon = _class_canonical_slug(cn) or ""
                slug = f"{int(cid)}-{canon}" if canon else str(int(cid))
            except Exception:
                slug = ""
        else:
            slug = ""
        if slug:
            href = f"/class/{html_module.escape(slug)}"
            inner = f'<a href="{href}">{html_module.escape(cn)}</a>'
        else:
            inner = html_module.escape(cn)
        return f'<td class="class-col">{inner}</td>'

    trs = []
    for r in rows:
        rk = r.get("rank")
        boat = html_module.escape(str(r.get("boat_name") or "").strip())
        laps_raw = (r.get("laps") if not is_handicap_block else None) or r.get("handicap") or r.get("laps") or ""
        laps_val = laps_raw.strip() if isinstance(laps_raw, str) else str(laps_raw or "").strip()
        try:
            rank_num = int(rk) if rk is not None else 0
        except (TypeError, ValueError):
            rank_num = 0
        rank_str = _format_rank(rk)
        medal_class = ""
        if rank_num == 1:
            medal_class = "medal-gold"
        elif rank_num == 2:
            medal_class = "medal-silver"
        elif rank_num == 3:
            medal_class = "medal-bronze"
        trs.append(
            f'<tr class="{medal_class}">'
            f'<td class="rank-col">{html_module.escape(rank_str)}</td>'
            f'<td class="boat-col">{boat}</td>'
            + _class_cell(r)
            + f'<td class="laps-col">{html_module.escape(laps_val)}</td>'
            + "</tr>"
        )
    thead = (
        '<th class="rank-col">Rank</th>'
        '<th class="boat-col">Boat</th>'
        '<th class="class-col">Class</th>'
        f'<th class="laps-col">{html_module.escape(laps_col)}</th>'
    )
    table_html = f'<table class="fleet-results-table mac-laps-table"><thead><tr>{thead}</tr></thead><tbody>{"".join(trs)}</tbody></table>'
    bid_attr = f' data-block-id="{html_module.escape(block_id, quote=True)}"' if block_id else ""
    return (
        f'<div class="fleet-section mac-endurance-laps"{bid_attr}>'
        + _mac_endurance_fleet_header_html(fleet, _mac_rid, header_title, sailed_line)
        + f'<div class="table-wrapper">{table_html}</div></div>'
    )

def _fleet_class_header_logo_columns_html(
    fleet: dict,
    regatta_id: Optional[str],
) -> tuple[str, str]:
    """Fleet header: single class logo left and right — no club, no icon+logo duplicate."""
    rid = str(regatta_id or fleet.get("regatta_id") or "").strip()
    bid = str(fleet.get("block_id") or "").strip()
    logo_url = _wc_regatta_fleet_block_logo_url(rid, bid)
    if not logo_url:
        logo_url = (fleet.get("class_logo_path") or "").strip() or None
    if not logo_url:
        logo_url = _catalogue_logo_path_for_class_name(
            (fleet.get("class_canonical") or fleet.get("name") or "").strip() or None
        )
    icon_url = (fleet.get("class_icon_path") or "").strip() or None
    if not logo_url and fleet.get("class_id") and table_exists("classes"):
        try:
            conn = get_db_connection()
            cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
            try:
                cur.execute(
                    "SELECT logo_path, icon_path FROM classes WHERE class_id = %s LIMIT 1",
                    (int(fleet.get("class_id")),),
                )
                row = cur.fetchone()
                if row:
                    logo_url = (row.get("logo_path") or "").strip() or logo_url
                    icon_url = (row.get("icon_path") or "").strip() or icon_url
            finally:
                cur.close()
                return_db_connection(conn)
        except Exception:
            pass
    # One image per side: prefer logo_path; icon_path only when no logo.
    if not logo_url and not icon_url and _is_df95_ec_regional_fleet_block(fleet, rid):
        logo_url = DF95_EC_REGIONAL_FLEET_LOGO
    if not logo_url and not icon_url and _is_port_owen_dinghy_fleet(fleet, rid):
        logo_url = PORT_OWEN_DINGHY_FLEET_LOGO
    if not logo_url and not icon_url and _is_generic_hobie_fleet(fleet):
        logo_url = GENERIC_HOBIE_FLEET_LOGO
    display_url = logo_url or icon_url
    left_col = ""
    right_col = ""
    if display_url:
        img = (
            f'<img src="{html_module.escape(display_url)}" alt="" class="class-header-logo-img" '
            f'loading="lazy" decoding="async" />'
        )
        left_col = f'<div class="class-header-logo-col">{img}</div>'
    right_logo_url = _wc_regatta_fleet_block_logo_url_right(rid, bid)
    right_display = right_logo_url or display_url
    if right_display:
        img_r = (
            f'<img src="{html_module.escape(right_display)}" alt="" class="class-header-logo-img" '
            f'loading="lazy" decoding="async" />'
        )
        right_col = f'<div class="class-header-club-logo-col">{img_r}</div>'
    return left_col, right_col



def _parsed_race_scores_dict(row: dict) -> dict:
    rs = row.get("race_scores") or {}
    if isinstance(rs, str) and rs.strip():
        try:
            rs = json.loads(rs)
        except Exception:
            rs = {}
    return rs if isinstance(rs, dict) else {}


def _fleet_is_df95_class(fleet: dict, rows: list) -> bool:
    """True for catalogue DF95 (class_id 24) — all DF95 tables show Total/Disc/Nett."""
    cid = fleet.get("class_id")
    if cid is not None and int(cid) == 24:
        return True
    class_hint = str(fleet.get("class_canonical") or fleet.get("class_original") or "").lower()
    if "df95" in class_hint:
        return True
    for row in rows:
        rcid = row.get("class_id")
        if rcid is not None and int(rcid) == 24:
            return True
        rh = str(row.get("class_canonical") or row.get("class_original") or "").lower()
        if "df95" in rh:
            return True
    return False


def _fleet_has_qf_race_scores(rows: list) -> bool:
    """True when any row stores Q/F race keys (387 gold-standard layout)."""
    for row in rows:
        for k in _parsed_race_scores_dict(row):
            if isinstance(k, str) and (re.match(r"^Q\d+$", k, re.I) or re.match(r"^F\d+$", k, re.I)):
                return True
    return False


def _standard_r_race_column_keys(rows: list) -> list:
    max_idx = 0
    for row in rows:
        for k in _parsed_race_scores_dict(row):
            if not isinstance(k, str):
                continue
            ku = k.upper()
            if ku.startswith("R") and len(ku) > 1 and ku[1:].isdigit():
                max_idx = max(max_idx, int(ku[1:]))
    # No invent R1 when sheet has Total/Nett only (empty race_scores).
    if max_idx == 0:
        return []
    cols: list[str] = []
    for i in range(1, max_idx + 1):
        key = f"R{i}"
        if any(str(_parsed_race_scores_dict(r).get(key) or "").strip() for r in rows):
            cols.append(key)
    return cols


def _df95_race_column_keys(rows: list) -> list:
    """Q1..Qn then F1..Fm — only columns with at least one non-empty cell."""
    q_max = f_max = 0
    for row in rows:
        rs = _parsed_race_scores_dict(row)
        for k in rs:
            if not isinstance(k, str):
                continue
            qm = re.match(r"^Q(\d+)$", k, re.I)
            fm = re.match(r"^F(\d+)$", k, re.I)
            if qm:
                q_max = max(q_max, int(qm.group(1)))
            if fm:
                f_max = max(f_max, int(fm.group(1)))
    cols: list[str] = []
    for i in range(1, q_max + 1):
        key = f"Q{i}"
        if any(str(_parsed_race_scores_dict(r).get(key) or "").strip() for r in rows):
            cols.append(key)
    for i in range(1, f_max + 1):
        key = f"F{i}"
        if any(str(_parsed_race_scores_dict(r).get(key) or "").strip() for r in rows):
            cols.append(key)
    return cols


def _df95_disc_display(total_val, nett_val, use_decimals: bool) -> str:
    try:
        tp = float(total_val)
        npv = float(nett_val)
    except (TypeError, ValueError):
        return ""
    disc = round(tp - npv, 1)
    if disc == 0:
        return "0" if not use_decimals else "0.0"
    sign = "-" if disc > 0 else ""
    mag = abs(disc)
    if use_decimals:
        return f"{sign}{mag:.1f}"
    if mag == int(mag):
        return f"{sign}{int(mag)}"
    return f"{sign}{mag:.1f}"


def _render_result_sheet_fleet(
    fleet: dict,
    standalone_class_page: bool = False,
    *,
    column_prefs: Optional[dict] = None,
    wc_sa_fleet_edit: bool = False,
    wc_show_late_entry_strip: bool = False,
    wc_late_strip_external: bool = False,
    show_fleet_header_logos: bool = True,
    boat_norm_slug_map: Optional[dict] = None,
) -> Tuple[str, Optional[str]]:
    """Render one fleet as HTML using the same structure and class names as admin regatta_viewer result sheet popup.
    When standalone_class_page is True (e.g. /regatta/{id}/class-{slug}), header is class name only, no 'Fleet' suffix.
    When column_prefs is set (WC pilot), unchecked keys hide columns; checked keys show columns for everyone (admin and public).
    Optional columns (boat/jib/bow/hull/crew) show when the pref is on even if cells are empty.
    When column_prefs is None (other regattas), optional columns only appear when at least one row has data (legacy).
    SA-only blocks (editable cells, NEW/Late entry strip with class wc-late-entry-strip) must be emitted only when
    wc_sa_fleet_edit is True (super admin on WC pilot); public pages omit that HTML entirely."""
    prefs = column_prefs if isinstance(column_prefs, dict) else None
    if boat_norm_slug_map is None:
        boat_norm_slug_map = _load_boat_norm_slug_map()

    if _fleet_is_tsc_9hr_endurance(fleet):
        return (_render_tsc_9hr_endurance_fleet(fleet), None if not wc_late_strip_external else None)

    if _fleet_is_mac_endurance_laps(fleet):
        return (_render_mac_endurance_laps_fleet(fleet), None if not wc_late_strip_external else None)


    def _pref_on(key: str) -> bool:
        if prefs is None:
            return True
        if key not in prefs:
            return True
        return bool(prefs.get(key))

    def _optional_col_visible(pref_key: str, has_data: bool) -> bool:
        """Hide optional columns only when every row in the fleet is blank."""
        return bool(has_data)

    _rid_ft = str((fleet.get("regatta_id") or "")).strip()
    fname = (fleet.get("name") or "Fleet").strip()
    _fl_raw_block = (fleet.get("fleet_label") or "").strip()
    fleet_label = _fl_raw_block
    class_canonical = (fleet.get("class_canonical") or "").strip()
    if _regatta_slug_is_sa_pilot_standalone(_rid_ft):
        fname = _wc_dinghy_fleet_title_display(fname)
        fleet_label = _wc_dinghy_fleet_title_display(fleet_label)
        class_canonical = _wc_dinghy_fleet_title_display(class_canonical)
        fleet_label_cell = fleet.get("fleet_label_cell") or _wc_dinghy_fleet_column_cell_display(
            _wc_dinghy_fleet_title_display(_fl_raw_block)
        )
    else:
        fleet_label_cell = fleet_label
    # Header title: must show e.g. "420 Fleet" not just "Fleet". Use fleet_label or class_canonical from block/rows when name is fallback.
    _bl_raw_title = (fleet.get("block_label_raw") or "").strip()
    if _bl_raw_title:
        # Keep numbered prefix in DB for sort; bar title is unnumbered (420 lesson).
        _display_raw_title = _strip_numbered_block_label_prefix(_bl_raw_title) or _bl_raw_title
        if standalone_class_page:
            fleet_header_title = _display_raw_title
        else:
            fleet_header_title = (
                _display_raw_title
                if _display_raw_title.endswith(" Fleet")
                else _display_raw_title + " Fleet"
            )
    elif standalone_class_page:
        base = (fleet_label or class_canonical or fname).strip()
        fleet_header_title = base.replace(" Fleet", "").strip() or "Results"
    elif fname == "Fleet" and (fleet_label or class_canonical):
        fleet_header_title = (fleet_label or class_canonical) + (" Fleet" if not (fleet_label or class_canonical).endswith(" Fleet") else "")
    elif fname.endswith(" Fleet") or fname == "Fleet" or re.search(r"\bUnder\s+\d+\b", fname, re.I):
        fleet_header_title = fname
    else:
        fleet_header_title = fname + " Fleet" if not fname.endswith(" Fleet") else fname
    if _regatta_slug_is_sa_pilot_standalone(_rid_ft):
        fleet_header_title = _wc_dinghy_fleet_title_display(fleet_header_title)
    fleet_title_inner = fleet_header_title
    regatta_id = fleet.get("regatta_id")
    class_slug = (fleet.get("class_slug") or "").strip()
    fleet_shell_href = (fleet.get("fleet_shell_href") or "").strip()
    if regatta_id and fleet_shell_href:
        fleet_header_title = f'<a href="{html_module.escape(fleet_shell_href)}">{html_module.escape(fleet_title_inner)}</a>'
    elif regatta_id and class_slug:
        fleet_header_title = f'<a href="/class/{html_module.escape(class_slug)}">{html_module.escape(fleet_title_inner)}</a>'
    else:
        fleet_header_title = html_module.escape(fleet_title_inner)
    block_id = (fleet.get("block_id") or "").strip()
    if wc_sa_fleet_edit and block_id and regatta_id:
        rid_s = html_module.escape(str(regatta_id))
        bid_s = html_module.escape(block_id)
        inner_s = html_module.escape(fleet_title_inner)
        fleet_header_html = (
            f'<div class="fleet-header-title-wrap">'
            f'<span class="fleet-title-public-nav">{fleet_header_title}</span>'
            f'<button type="button" class="fleet-sa-edit-hit" data-block-id="{bid_s}" data-regatta-id="{rid_s}" aria-label="Edit fleet or class">{inner_s}</button>'
            f"</div>"
        )
    else:
        fleet_header_html = fleet_header_title
    rows = list(fleet.get("rows") or [])
    is_wc_fleet_sheet = str(regatta_id or "") == WC_DINGHY_CHAMPS_REGATTA_SLUG
    # SA pilot (e.g. Brass Monkey): same edit/delete/race-score tools as WC when SA edit on
    sa_fleet_ops = bool(wc_sa_fleet_edit)
    entries_closed = bool(fleet.get("entries_closed"))
    if is_wc_fleet_sheet:
        rows = [r for r in rows if not _wc_result_row_hidden_from_wc_sheet(r, fleet)]

        def _wc_fleet_rank_sort_key(x: dict):
            rk = x.get("rank")
            try:
                ir = int(rk) if rk is not None else 10**9
            except (TypeError, ValueError):
                ir = 10**9
            return (ir, str(x.get("result_id") or ""))

        rows.sort(key=_wc_fleet_rank_sort_key)
    use_decimals_in_block = _block_scores_need_decimal_display(rows)
    if _rid_ft == "2026-02-16-hyc-cape-classic":
        use_decimals_in_block = True

    def _max_race_idx_from_result_rows(result_rows):
        """Max R index present in any row's race_scores keys (0 if none)."""
        m = 0
        for r in result_rows:
            rs = r.get("race_scores") or {}
            if isinstance(rs, str) and rs.strip():
                try:
                    rs = json.loads(rs)
                except Exception:
                    rs = {}
            if not isinstance(rs, dict):
                continue
            for k in rs:
                if not isinstance(k, str):
                    continue
                ku = k.upper()
                if (
                    ku.startswith("R")
                    and len(ku) > 1
                    and ku[1:].isdigit()
                    and str(rs.get(k) or "").strip()
                ):
                    m = max(m, int(ku[1:]))
        return m

    races_sailed_db = int(fleet.get("races_sailed") or 0)
    max_race_from_scores = _max_race_idx_from_result_rows(rows)
    # Sailed band = declared race count only. Time/Pos layout keys are NOT races.
    races_sailed = races_sailed_db if races_sailed_db > 0 else max_race_from_scores
    discard_count = fleet.get("discard_count") or 0
    to_count = fleet.get("to_count")
    if to_count is None and discard_count is not None:
        to_count = max(0, int(races_sailed) - int(discard_count))
    entries = len(rows) if is_wc_fleet_sheet else (fleet.get("entries") or 0)
    scoring_system = fleet.get("scoring_system") or "Appendix A"
    score_line_disp = _sailed_line_scoring_template_display(
        str(regatta_id) if regatta_id is not None else "",
        scoring_system,
    )
    rating_system = (fleet.get("rating_system") or "").strip()
    _sailed_parts = [
        f"Sailed: {races_sailed}",
        f"Discards: {discard_count}",
        f"To count: {to_count}",
    ]
    if rating_system:
        _sailed_parts.append(f"Rating system: {rating_system}")
    _sailed_parts.append(f"Entries: {entries}")
    _sailed_parts.append(f"Scoring system: {score_line_disp}")
    sailed_line = ", ".join(_sailed_parts)
    _start_ln = _fleet_start_time_sast_line(rows)
    if _start_ln:
        sailed_line = sailed_line + " | " + _start_ln
    show_pcs_times = _fleet_shows_pcs_timing_columns(scoring_system, rows)
    show_delta_col = show_pcs_times and any(
        isinstance(r, dict) and str(r.get("delta_time") or "").strip() for r in rows
    )
    show_aph_col = show_pcs_times and any(
        isinstance(r, dict) and str(r.get("aph") or "").strip() for r in rows
    )
    show_finish_col = show_pcs_times and any(
        isinstance(r, dict) and str(r.get("finish_time") or "").strip() for r in rows
    )
    show_elapsed_col = show_pcs_times and any(
        isinstance(r, dict) and str(r.get("duration_time") or "").strip() for r in rows
    )
    show_corrected_col = show_pcs_times and any(
        isinstance(r, dict) and str(r.get("corrected_time") or "").strip() for r in rows
    )
    show_pcs_tcf_col = show_pcs_times and any(
        isinstance(r, dict) and str(r.get("handicap") or "").strip() for r in rows
    )
    show_pcs_start_col = show_pcs_times and any(
        isinstance(r, dict) and str(r.get("start_time") or "").strip() for r in rows
    )
    show_handicap_col, handicap_col_label = _fleet_shows_handicap_rating_column(
        fleet, rows, show_pcs_times=show_pcs_times
    )
    _pcs_col_labels = {}
    try:
        _icons_raw = _read_wc_regatta_header_icons().get(str(fleet.get("regatta_id") or "").strip())
        if isinstance(_icons_raw, dict) and isinstance(_icons_raw.get("column_labels"), dict):
            _pcs_col_labels = _icons_raw.get("column_labels") or {}
    except Exception:
        _pcs_col_labels = {}
    pcs_aph_label = str(_pcs_col_labels.get("aph") or "APH").strip() or "APH"
    pcs_delta_label = str(_pcs_col_labels.get("delta") or "Delta").strip() or "Delta"
    pcs_finish_label = str(_pcs_col_labels.get("finish") or "Finish Time").strip() or "Finish Time"
    pcs_tcf_label = (
        str(_pcs_col_labels.get("handicap") or _pcs_col_labels.get("tcf") or "").strip()
        or (fleet.get("rating_system") or "TCF").strip()
        or "TCF"
    )
    pcs_start_label = str(_pcs_col_labels.get("start") or "Start").strip() or "Start"

    def _row_has_crew(row):
        if (row.get("crew_name") or "").strip():
            return True
        cl = row.get("crew_list") or []
        return any((x.get("role") or "").strip().lower() == "crew" for x in cl)

    has_crew = any(_row_has_crew(r) for r in rows)
    has_boat_name = any((r.get("boat_name") or "").strip() for r in rows)
    has_jib_no = any((r.get("jib_no") or "").strip() for r in rows)
    has_bow_no = any((r.get("bow_no") or "").strip() for r in rows)
    has_hull_no = any((r.get("hull_no") or "").strip() for r in rows)
    has_age_category = any((r.get("age_category") or "").strip() for r in rows)
    has_nat = any(not _is_rsa_nationality(r.get("nationality")) for r in rows)
    has_club = any(
        (str(r.get("club") or "").strip()
         or str(r.get("club_raw") or "").strip()
         or str(r.get("club_code") or "").strip()
         or r.get("club_id"))
        for r in rows
    )
    show_df95_disc_column = _fleet_is_df95_class(fleet, rows)
    use_df95_qf_columns = _fleet_has_qf_race_scores(rows)
    if use_df95_qf_columns:
        dc = int(discard_count or 0)
        q_discards = max(0, dc - 1) if dc > 0 else 0
        f_discards = min(1, dc) if dc > 0 else 0
        sailed_line = (
            f"Results are after {races_sailed} races with {q_discards} Qualifying Discards "
            f"and {f_discards} Finals Discard. Scoring check: Total = sum(Q+F), Nett = Total - Disc."
        )
    # Race columns: DF95 Q/F (387 gold std) or R1..Rmax; Disc column when show_df95_disc_column.
    race_columns = []
    if _pref_on("race_scores"):
        if use_df95_qf_columns:
            race_columns = _df95_race_column_keys(rows)
        elif show_df95_disc_column:
            race_columns = _standard_r_race_column_keys(rows)
        else:
            race_columns = _standard_r_race_column_keys(rows)

    # Explicit empty race_column_labels [] = Total/Nett-only sheet (suppress R columns).
    _rcl_suppress = fleet.get("race_column_labels")
    if isinstance(_rcl_suppress, list) and len(_rcl_suppress) == 0:
        race_columns = []
    elif isinstance(_rcl_suppress, str) and _rcl_suppress.strip() in ("[]", "null"):
        race_columns = []
    elif use_df95_qf_columns:
        pass  # keep Q/F keys from scores
    else:
        _rcl_early = fleet.get("race_column_labels")
        _rcl_map_early = {}
        if isinstance(_rcl_early, str) and _rcl_early.strip():
            try:
                _rcl_map_early = json.loads(_rcl_early)
            except Exception:
                _rcl_map_early = {}
        elif isinstance(_rcl_early, dict):
            _rcl_map_early = _rcl_early
        if isinstance(_rcl_map_early, dict) and _rcl_map_early:
            def _rk(k):
                s = str(k)
                if s[:1].upper() == "R" and s[1:].isdigit():
                    return int(s[1:])
                return 10**9
            race_columns = sorted(_rcl_map_early.keys(), key=_rk)
        elif int(races_sailed) > 0:
            # HARD RULE: fleet band Sailed: n ⇒ exactly R1…Rn
            race_columns = [f"R{i}" for i in range(1, int(races_sailed) + 1)]
        elif not race_columns and races_sailed_db > 0:
            race_columns = [f"R{i}" for i in range(1, int(races_sailed_db) + 1)]

    show_boat = _optional_col_visible("boat_name", has_boat_name)
    show_jib = _optional_col_visible("jib", has_jib_no)
    show_bow = _optional_col_visible("bow", has_bow_no)
    show_hull = _optional_col_visible("hull", has_hull_no)
    show_category = _optional_col_visible("category", has_age_category)
    show_club = _optional_col_visible("club", has_club)

    show_crew_col = _optional_col_visible("crew", has_crew)

    def _norm_result_sheet_label(v: object) -> str:
        s = str(v or "").strip()
        if not s:
            return ""
        s = re.sub(r"\s+fleet$", "", s, flags=re.I).strip()
        return re.sub(r"\s+", " ", s).casefold()

    _fleet_header_norms = {
        _norm_result_sheet_label(fleet_label_cell),
        _norm_result_sheet_label(fleet_label),
        _norm_result_sheet_label(class_canonical),
        _norm_result_sheet_label(fleet_title_inner),
    }
    _fleet_header_norms.discard("")
    _class_row_norms = [_norm_result_sheet_label(r.get("class_name")) for r in rows]
    _hide_redundant_fleet_col = bool(rows) and bool(_fleet_header_norms)
    _hide_redundant_class_col = (
        bool(rows)
        and bool(_fleet_header_norms)
        and len(_class_row_norms) == len(rows)
        and all(v and v in _fleet_header_norms for v in _class_row_norms)
    )
    show_fleet_col = _pref_on("fleet") and not _hide_redundant_fleet_col
    show_class_col = _pref_on("class") and (
        not _hide_redundant_class_col or _rid_ft == "2026-02-16-hyc-cape-classic"
    )

    show_races = bool(race_columns)

    # Windsurfer / custom race headers: regatta_blocks.race_column_labels JSON {"R9":"Slalom",...} — non-standard template; do not strip.
    rcl_raw = fleet.get("race_column_labels")
    rcl_map = {}
    if rcl_raw:
        if isinstance(rcl_raw, str) and rcl_raw.strip():
            try:
                rcl_map = json.loads(rcl_raw)
            except Exception:
                rcl_map = {}
        elif isinstance(rcl_raw, dict):
            rcl_map = rcl_raw
    if not isinstance(rcl_map, dict):
        rcl_map = {}

    def _race_legend_line() -> str:
        parts: list[str] = []
        for rc in race_columns:
            ru = (rc or "").upper()
            rl = (rc or "").lower()
            v = rcl_map.get(rc) or rcl_map.get(ru) or rcl_map.get(rl)
            label = (str(v).strip() if v is not None else "")
            if label:
                parts.append(f"{rc} = {label}")
        return " | ".join(parts)

    def _race_header_label(rk: str) -> str:
        # Brass Monkey / Windsurfer: race_column_labels dict renames R# header text
        v = rcl_map.get(rk) or rcl_map.get((rk or "").upper()) or rcl_map.get((rk or "").lower())
        if v is not None and str(v).strip():
            return str(v).strip()
        return rk

    sail_label = "SailNo" if _rid_ft == "2026-02-16-hyc-cape-classic" else "Sail No"
    helm_label = "HelmName" if _rid_ft == "2026-02-16-hyc-cape-classic" else "Helm"
    crew_label = "CrewName" if _rid_ft == "2026-02-16-hyc-cape-classic" else "Crew"
    thead = ""
    if _pref_on("rank"):
        thead += '<th class="rank-col">Rank</th>'
    if show_fleet_col:
        thead += '<th class="fleet-col">Fleet</th>'
    if show_class_col:
        thead += '<th class="class-col">Class</th>'
    if _pref_on("sail_no"):
        thead += f'<th class="sail-col">{html_module.escape(sail_label)}</th>'
    if has_nat:
        thead += '<th class="nat-col">Nat</th>'
    if show_boat:
        thead += '<th class="wc-meta-col">Boat Name</th>'
    if show_jib:
        thead += '<th class="wc-meta-col">Jib No</th>'
    if show_bow:
        _bow_lab = 'Bow No'
        try:
            _ir = _read_wc_regatta_header_icons().get(str(fleet.get('regatta_id') or '').strip())
            if isinstance(_ir, dict) and isinstance(_ir.get('column_labels'), dict):
                _bow_lab = str(_ir['column_labels'].get('bow') or _bow_lab).strip() or _bow_lab
        except Exception:
            pass
        thead += f'<th class="wc-meta-col">{html_module.escape(_bow_lab)}</th>'
    if show_hull:
        thead += '<th class="wc-meta-col">Hull No</th>'
    if show_club:
        thead += '<th class="club-col">Club</th>'
    if show_category:
        thead += '<th class="wc-meta-col">Age</th>'
    if _pref_on("helm"):
        thead += f'<th class="helm-col">{html_module.escape(helm_label)}</th>'
    if show_crew_col:
        thead += f'<th class="crew-col">{html_module.escape(crew_label)}</th>'
    if show_races:
        for rc in race_columns:
            rc_head = _race_header_label(rc)
            clear_race_html = ""
            if sa_fleet_ops:
                rk_attr = html_module.escape(rc, quote=True)
                clear_race_html = (
                    f'<span class="wc-clear-race" role="button" tabindex="0" '
                    f'data-race="{rk_attr}" title="Clear {rk_attr}">🧹</span>'
                )
            thead += f'<th class="race-col">{html_module.escape(rc_head)}{clear_race_html}</th>'
    if show_pcs_times:
        if show_pcs_tcf_col:
            thead += f'<th class="wc-meta-col">{html_module.escape(pcs_tcf_label)}</th>'
        if show_pcs_start_col:
            thead += f'<th class="wc-meta-col">{html_module.escape(pcs_start_label)}</th>'
        if show_finish_col:
            thead += f'<th class="wc-meta-col">{html_module.escape(pcs_finish_label)}</th>'
        if show_elapsed_col:
            thead += '<th class="wc-meta-col">Elapsed</th>'
        if show_corrected_col:
            thead += '<th class="wc-meta-col">Corrected</th>'
        if show_delta_col:
            thead += f'<th class="wc-meta-col">{html_module.escape(pcs_delta_label)}</th>'
        if show_aph_col:
            thead += f'<th class="wc-meta-col">{html_module.escape(pcs_aph_label)}</th>'
    elif show_handicap_col:
        thead += f'<th class="wc-meta-col">{html_module.escape(handicap_col_label)}</th>'
    if _pref_on("total"):
        thead += '<th class="total-col">Total</th>'
    if show_df95_disc_column and _pref_on("total"):
        thead += '<th class="disc-col">Disc</th>'
    if _pref_on("nett"):
        thead += '<th class="nett-col">Nett</th>'

    late_part = ""
    late_external_out: Optional[str] = None
    bid_for_late = (block_id or "").strip()
    if wc_sa_fleet_edit and is_wc_fleet_sheet and wc_show_late_entry_strip and bid_for_late:
        late_frag = _wc_late_entry_strip_html(
            fleet,
            column_prefs=column_prefs,
            wc_sa_fleet_edit=wc_sa_fleet_edit,
            thead=thead,
            race_columns=race_columns,
            show_boat=show_boat,
            show_jib=show_jib,
            show_bow=show_bow,
            show_hull=show_hull,
            show_club=show_club,
            show_crew_col=show_crew_col,
            show_category=show_category,
        )
        if wc_late_strip_external:
            late_external_out = late_frag or None
            late_part = ""
        else:
            late_part = late_frag

    trs = []
    for rank_disp, r in enumerate(rows, start=1):
        race_scores = r.get("race_scores") or {}
        if isinstance(race_scores, str) and race_scores.strip():
            try:
                race_scores = json.loads(race_scores)
            except Exception:
                race_scores = {}
        if not isinstance(race_scores, dict):
            race_scores = {}
        if is_wc_fleet_sheet:
            rank_num = rank_disp
            rank_str = _format_rank(rank_disp)
        else:
            rank_num = int(r.get("rank")) if r.get("rank") is not None else 0
            rank_str = _format_rank(r.get("rank"))
        medal_class = ""
        if rank_num == 1:
            medal_class = "medal-gold"
        elif rank_num == 2:
            medal_class = "medal-silver"
        elif rank_num == 3:
            medal_class = "medal-bronze"
        _rank_strike = int(r.get("rank") or 0) if r.get("rank") is not None else 0
        did_not_race = (r.get("raced") is False or r.get("raced") == 0) and _rank_strike <= 0
        strike_class = "strike-out" if did_not_race else ""
        row_classes = " ".join(c for c in (medal_class,) if c)
        fleet_str = html_module.escape(fleet_label_cell)
        class_name_for_link = (r.get("class_name") or "")
        class_display_raw = str(class_name_for_link)
        if (
            _rid_ft == "2026-02-16-hyc-cape-classic"
            and fleet_label == "ILCA 4"
            and class_display_raw.strip().casefold() == "ilca 4.7"
        ):
            class_name_for_link = "ILCA 4"
            class_display_raw = "ILCA 4"
        _rcid_for_link = r.get("result_class_id")
        if _rcid_for_link is None:
            _rcid_for_link = r.get("class_id")
        _class_href_slug = ""
        if _rcid_for_link is not None and class_display_raw.strip():
            _cn_link = class_display_raw.strip()
            _canon_link = _class_canonical_slug(_cn_link)
            _class_href_slug = (
                f"{int(_rcid_for_link)}-{_canon_link}" if _canon_link else str(int(_rcid_for_link))
            )
        if _class_href_slug:
            class_str = (
                f'<a href="/class/{html_module.escape(_class_href_slug)}">'
                f"{html_module.escape(class_display_raw)}</a>"
            )
        elif class_display_raw.strip():
            class_str = (
                f'<span class="wc-class-unmatched" title="Class on result sheet — not yet in catalogue">'
                f"{html_module.escape(class_display_raw)}</span>"
            )
        else:
            class_str = html_module.escape(class_display_raw)
        sail_raw = str(r.get("sail_number") or "")
        sail_str = html_module.escape(sail_raw)
        sail_link_html = sail_str
        sail_class_slug = _class_canonical_slug(class_display_raw.strip()) if class_display_raw.strip() else ""
        if sail_class_slug and sail_raw.strip():
            sail_href = f"/boat/{quote(sail_class_slug, safe='')}-{quote(sail_raw.strip(), safe='')}"
            sail_link_html = (
                f'<span class="wc-boat-linked">'
                f'<a href="{sail_href}">{sail_str}</a>'
                f"</span>"
            )
        club_raw, club_slug = _regatta_public_club_display_and_slug(r)
        club_link_html = (
            f'<a href="/club/{html_module.escape(str(club_slug))}">{html_module.escape(club_raw)}</a>'
            if club_slug and club_raw
            else html_module.escape(club_raw)
        )
        result_id_row = r.get("result_id")
        crew_list = r.get("crew_list") or []
        crew_raw_for_edit = ""
        if crew_list:
            helm_entries = [x for x in crew_list if (x.get("role") or "").strip().lower() == "helm"]
            crew_entries = [x for x in crew_list if (x.get("role") or "").strip().lower() == "crew"]
            helm_raw = (helm_entries[0].get("sailor_name") or "").strip() if helm_entries else str(r.get("helm_name") or "")
            helm_slug = r.get("helm_slug")
            helm_str = (
                f'<a href="/sailor/{html_module.escape(helm_slug)}">{html_module.escape(helm_raw)}</a>'
                if helm_slug and helm_raw
                else html_module.escape(helm_raw)
            )
            crew_names = [(x.get("sailor_name") or "").strip() for x in crew_entries if (x.get("sailor_name") or "").strip()]
            crew_raw_for_edit = ", ".join(crew_names) if crew_names else (r.get("crew_name") or "").strip()
            crew_str = "Crew: " + ", ".join(html_module.escape(n) for n in crew_names) if crew_names else ""
        else:
            helm_raw = str(r.get("helm_name") or "")
            helm_slug = r.get("helm_slug")
            helm_str = (
                f'<a href="/sailor/{html_module.escape(helm_slug)}">{html_module.escape(helm_raw)}</a>'
                if helm_slug and helm_raw
                else html_module.escape(helm_raw)
            )
            def _crew_slot_link(nm: str, sid, slug) -> str:
                nm = (nm or "").strip()
                if not nm:
                    return ""
                matched = sid is not None and str(sid).strip().isdigit()
                if slug:
                    inner = f'<a href="/sailor/{html_module.escape(slug)}">{html_module.escape(nm)}</a>'
                    c_cls = "wc-sailor-linked" if matched else "wc-sailor-unmatched"
                    return f'<span class="{c_cls}">{inner}</span>'
                if matched:
                    return html_module.escape(nm)
                return f'<span class="wc-sailor-unmatched">{html_module.escape(nm)}</span>'

            crew_parts = []
            crew_plain = []
            for nm, sid, slug in (
                (r.get("crew_name"), r.get("crew_sa_sailing_id"), r.get("crew_slug")),
                (r.get("crew2_name"), r.get("crew2_sa_sailing_id"), r.get("crew2_slug")),
                (r.get("crew3_name"), r.get("crew3_sa_sailing_id"), r.get("crew3_slug")),
            ):
                if (nm or "").strip():
                    crew_plain.append((nm or "").strip())
                    crew_parts.append(_crew_slot_link(nm, sid, slug))
            crew_raw_for_edit = ", ".join(crew_plain)
            crew_str = ", ".join(p for p in crew_parts if p)

        # Public ladder: SAS id matched → blue link; no SAS id → red underline (all regattas).
        helm_matched = r.get("helm_sa_sailing_id") is not None and str(r.get("helm_sa_sailing_id") or "").strip().isdigit()
        if helm_matched and helm_slug and str(helm_raw or "").strip():
            helm_str = f'<span class="wc-sailor-linked">{helm_str}</span>'
        elif str(helm_raw or "").strip():
            helm_str = f'<span class="wc-sailor-unmatched">{helm_str}</span>'
        if crew_list:
            if crew_str:
                crew_str = f'<span class="wc-sailor-unmatched">{crew_str}</span>'
        elif crew_str and not (
            r.get("crew_sa_sailing_id") is not None and str(r.get("crew_sa_sailing_id") or "").strip().isdigit()
        ):
            if "wc-sailor-unmatched" not in crew_str:
                crew_str = f'<span class="wc-sailor-unmatched">{crew_str}</span>'

        def _wc_cell(
            inner_html: str,
            plain: str,
            field: Optional[str] = None,
            race_k: Optional[str] = None,
            mx: int = 220,
            ac: Optional[str] = None,
            xin: str = "",
        ) -> str:
            return _wc_fleet_editable_cell(
                wc_sa_fleet_edit,
                result_id_row,
                public_inner_html=inner_html,
                value_plain=plain,
                data_field=field,
                race_key=race_k,
                maxlength=mx,
                wrap_autocomplete=ac,
                extra_input_attrs=xin,
            )

        class_name_raw = (r.get("class_name") or "")
        club_row_id = r.get("club_id")
        club_xin = ""
        if club_row_id is not None and str(club_raw).strip():
            cs = str(club_raw).strip().upper()
            club_xin = (
                f' data-resolved-club-id="{html_module.escape(str(int(club_row_id)), quote=True)}"'
                f' data-original-resolved-club-id="{html_module.escape(str(int(club_row_id)), quote=True)}"'
                f' data-resolved-code="{html_module.escape(cs, quote=True)}"'
            )
        rcid = r.get("result_class_id")
        class_xin = ""
        if rcid is not None and (class_name_raw or "").strip():
            cn = (class_name_raw or "").strip()
            canon = _class_canonical_slug(cn)
            cpath = f"/class/{int(rcid)}-{canon}" if canon else f"/class/{int(rcid)}"
            class_xin = (
                f' data-resolved-class-id="{html_module.escape(str(int(rcid)), quote=True)}"'
                f' data-original-resolved-class-id="{html_module.escape(str(int(rcid)), quote=True)}"'
                f' data-class-path="{html_module.escape(cpath, quote=True)}"'
            )
        helm_xin = ""
        hs = r.get("helm_sa_sailing_id")
        if hs is not None and str(hs).strip().isdigit() and (helm_raw or "").strip():
            hk = f"SAS:{int(hs)}"
            hnm = (helm_raw or "").strip()
            helm_xin = (
                f' data-resolved-person-key="{html_module.escape(hk, quote=True)}"'
                f' data-original-resolved-person-key="{html_module.escape(hk, quote=True)}"'
                f' data-resolved-person-name="{html_module.escape(hnm, quote=True)}"'
            )
        crew_xin = ""
        csid = r.get("crew_sa_sailing_id")
        if csid is not None and str(csid).strip().isdigit() and crew_raw_for_edit.strip():
            ck = f"SAS:{int(csid)}"
            cnm = crew_raw_for_edit.strip()
            crew_xin = (
                f' data-resolved-person-key="{html_module.escape(ck, quote=True)}"'
                f' data-original-resolved-person-key="{html_module.escape(ck, quote=True)}"'
                f' data-resolved-person-name="{html_module.escape(cnm, quote=True)}"'
            )
        sail_raw = str(r.get("sail_number") or "")
        total_plain = _format_total_nett_display(r.get("total"), use_decimals_in_block)
        nett_plain = _format_total_nett_display(r.get("nett"), use_decimals_in_block)
        total_str = html_module.escape(total_plain)
        nett_str = html_module.escape(nett_plain)
        row_html = f'<tr class="{row_classes}">'
        if _pref_on("rank"):
            rid_attr = html_module.escape(str(result_id_row), quote=True) if result_id_row is not None else ""
            reg_esc = html_module.escape(str(regatta_id or ""), quote=True)
            bid_hit = html_module.escape(str(block_id or ""), quote=True)
            # Filled entry = has helm name or SAS (stub empty ranks stay plain)
            _filled = bool(
                (str(r.get("helm_name") or "").strip())
                or (r.get("helm_sa_sailing_id") is not None and str(r.get("helm_sa_sailing_id")).strip())
                or (str(r.get("crew_name") or "").strip())
            )
            _del_btn = ""
            if sa_fleet_ops and result_id_row is not None and _filled:
                _del_btn = (
                    f'<button type="button" class="fleet-entry-del" data-result-id="{rid_attr}" '
                    f'data-regatta-id="{reg_esc}" data-block-id="{bid_hit}" '
                    f'title="Delete / clear this entry" aria-label="Delete entry">&times;</button>'
                )
            if wc_sa_fleet_edit and is_wc_fleet_sheet and result_id_row is not None:
                row_html += (
                    f'<td class="rank-col rank-col--with-del">'
                    f"{_del_btn}"
                    f'<button type="button" class="wc-rank-menu-hit wc-rank-menu-hit--active" '
                    f'data-result-id="{rid_attr}" data-regatta-id="{reg_esc}" data-block-id="{bid_hit}" '
                    f'aria-haspopup="true" aria-expanded="false" '
                    f'aria-label="Rank {html_module.escape(rank_str)}, move to hold">{html_module.escape(rank_str)}</button>'
                    f"</td>"
                )
            elif sa_fleet_ops and result_id_row is not None:
                row_html += (
                    f'<td class="rank-col rank-col--with-del">'
                    f"{_del_btn}"
                    f"{html_module.escape(rank_str)}"
                    f"</td>"
                )
            else:
                row_html += f'<td class="rank-col">{html_module.escape(rank_str)}</td>'
        if show_fleet_col:
            row_html += f'<td class="fleet-col">{fleet_str}</td>'
        if show_class_col:
            class_cell = _wc_cell(class_str, class_name_raw, "class_name", None, 64, "class", class_xin)
            if wc_sa_fleet_edit and is_wc_fleet_sheet and result_id_row is not None:
                rid_h = html_module.escape(str(result_id_row), quote=True)
                bid_h = html_module.escape(str(block_id or ""), quote=True)
                row_html += (
                    f'<td class="class-col">'
                    f'<div class="wc-class-col-sa">'
                    f'<button type="button" class="wc-class-hold-menu-hit" data-result-id="{rid_h}" data-block-id="{bid_h}" '
                    f'aria-label="Put this entry on hold: Hold then SURE in the menu">Hold</button>'
                    f"{class_cell}</div></td>"
                )
            else:
                row_html += f'<td class="class-col">{class_cell}</td>'
        if _pref_on("sail_no"):
            row_html += f'<td class="sail-col">{_wc_cell(sail_link_html, sail_raw, "sail_number", None, 32)}</td>'
        if has_nat:
            row_html += f'<td class="nat-col">{_nationality_flag_cell_html(r.get("nationality"))}</td>'
        if show_boat:
            bn = str(r.get("boat_name") or "")
            bn_html = _boat_name_display_html(bn, boat_norm_slug_map)
            row_html += f'<td class="wc-meta-col">{_wc_cell(bn_html, bn, "boat_name", None, 120)}</td>'
        if show_jib:
            jv = str(r.get("jib_no") or "")
            row_html += f'<td class="wc-meta-col">{_wc_cell(html_module.escape(jv), jv, "jib_no", None, 32)}</td>'
        if show_bow:
            bv = str(r.get("bow_no") or "")
            row_html += f'<td class="wc-meta-col">{_wc_cell(html_module.escape(bv), bv, "bow_no", None, 32)}</td>'
        if show_hull:
            hv = str(r.get("hull_no") or "")
            row_html += f'<td class="wc-meta-col">{_wc_cell(html_module.escape(hv), hv, "hull_no", None, 32)}</td>'
        if show_club:
            row_html += f'<td class="club-col">{_wc_cell(club_link_html, club_raw, "club_code", None, 32, "club", club_xin)}</td>'
        if show_category:
            ac = str(r.get("age_category") or "").strip()
            age_html = html_module.escape(ac)
            if ac:
                age_html = f'<span style="color:#0000ee;font-weight:700" title="PDF age">{html_module.escape(ac)}</span>'
            row_html += f'<td class="wc-meta-col">{age_html}</td>'
        if _pref_on("helm"):
            row_html += f'<td class="helm-col">{_wc_cell(helm_str, helm_raw or "", "helm_name", None, 120, "helm", helm_xin)}</td>'
        if show_crew_col:
            row_html += f'<td class="crew-col">{_wc_cell(crew_str, crew_raw_for_edit, "crew_name", None, 160, "crew", crew_xin)}</td>'
        if show_races:
            for rkey in race_columns:
                score = (race_scores.get(rkey) or "").strip()
                if is_wc_fleet_sheet or sa_fleet_ops:
                    # Display only: discard from stored parens; split number vs code for typography (WC only).
                    is_discarded = score.startswith("(") and score.endswith(")")
                    parse_src = (
                        score[1:-1].strip()
                        if is_discarded
                        else score
                    )
                    pn, pcode = _wc_parse_race_cell_parts(parse_src)
                    if not score.strip():
                        inner = ""
                    elif pn is None and pcode is None:
                        sd = (
                            _format_race_cell_display(score, True)
                            if use_decimals_in_block
                            else score
                        )
                        inner = f'<span class="wc-score">{html_module.escape(sd)}</span>'
                    else:
                        val_str = (
                            _wc_format_points_for_display(float(pn), use_decimals_in_block)
                            if pn is not None
                            else ""
                        )
                        if pcode:
                            inner = (
                                f'<span class="wc-score">{html_module.escape(val_str)}</span>'
                                f'<span class="wc-code">{html_module.escape(pcode)}</span>'
                            )
                        else:
                            inner = f'<span class="wc-score">{html_module.escape(val_str)}</span>'
                    if inner and is_discarded:
                        inner = f"({inner})"
                    has_penalty = bool(
                        re.search(
                            r"\b(DNC|DNS|DNF|DNR|RET|DSQ|UFD|BFD|DPI|OCS|NSC|DNE|ZFP|SCP|RDG|TLE)\b",
                            score,
                            re.I,
                        )
                    ) if score else False
                    # Strikethrough only when discarded and a letter code is present (numeric discards: no strike).
                    td_class = (
                        "race-col discard"
                        if is_discarded and (has_penalty or bool(pcode))
                        else "race-col"
                    )
                    rc_parts = [td_class]
                    if has_penalty:
                        rc_parts.append("code")
                    elif score:
                        rc_parts.append("score-counts")
                    rc_cls = " ".join(rc_parts)
                    row_html += f'<td class="{rc_cls}">{_wc_cell(inner, score, None, rkey, 48)}</td>'
                else:
                    # ASSIGNED_TIME_PLUS_RED: trailing + = worst+1min assigned time (show red, hide +)
                    _score_s = str(score or "")
                    _assigned = _score_s.endswith("+") or _score_s.rstrip("+") in {"35:26","29:32","27:10","1h 24min","1h 28min","1h 32min"}
                    _score_raw = _score_s[:-1] if _score_s.endswith("+") else score
                    score_display = _format_race_cell_display(_score_raw, use_decimals_in_block)
                    is_discarded = str(_score_raw).startswith("(") and str(_score_raw).endswith(")")
                    has_penalty = bool(
                        re.search(
                            r"\b(DNC|DNS|DNF|DNR|RET|DSQ|UFD|BFD|DPI|OCS|NSC|DNE|ZFP|SCP|RDG|TLE)\b",
                            str(_score_raw),
                            re.I,
                        )
                    ) if _score_raw else False
                    # Both classes when (23 DNC) discard — previously `code` alone dropped strikethrough.
                    inner_cls: List[str] = []
                    if has_penalty:
                        inner_cls.append("code")
                    if is_discarded:
                        inner_cls.append("disc")
                    if not inner_cls and _score_raw:
                        inner_cls.append("score-counts")
                    if _assigned:
                        inner_cls.append("assigned-time")
                    cell_class = " ".join(inner_cls)
                    rc_parts = [c for c in (cell_class, "race-col") if c]
                    rc_cls = " ".join(rc_parts)
                    # ASSIGNED_TIME_INLINE_RED: inline style beats td{color} / SA edit paint
                    _style = ' style="color:#c62828!important;font-weight:700"' if _assigned else ""
                    _inner = (
                        f'<span style="color:#c62828!important;font-weight:700">{html_module.escape(score_display)}</span>'
                        if _assigned
                        else html_module.escape(score_display)
                    )
                    row_html += f'<td class="{rc_cls}"{_style}>{_wc_cell(_inner, _score_raw, None, rkey, 48)}</td>'
        if show_pcs_times:
            tcf_disp = html_module.escape(str(r.get("handicap") or ""))
            st_disp = html_module.escape(str(r.get("start_time") or ""))
            aph_disp = html_module.escape(str(r.get("aph") or ""))
            ft_disp = html_module.escape(str(r.get("finish_time") or ""))
            el_disp = html_module.escape(str(r.get("duration_time") or ""))
            co_disp = html_module.escape(str(r.get("corrected_time") or ""))
            de_disp = html_module.escape(str(r.get("delta_time") or ""))
            if show_pcs_tcf_col:
                row_html += f'<td class="wc-meta-col">{tcf_disp}</td>'
            if show_pcs_start_col:
                row_html += f'<td class="wc-meta-col">{st_disp}</td>'
            if show_finish_col:
                row_html += f'<td class="wc-meta-col">{ft_disp}</td>'
            if show_elapsed_col:
                row_html += f'<td class="wc-meta-col">{el_disp}</td>'
            if show_corrected_col:
                row_html += f'<td class="wc-meta-col">{co_disp}</td>'
            if show_delta_col:
                row_html += f'<td class="wc-meta-col">{de_disp}</td>'
            if show_aph_col:
                row_html += f'<td class="wc-meta-col">{aph_disp}</td>'
        elif show_handicap_col:
            hc_disp = html_module.escape(str(r.get("handicap") or r.get("aph") or ""))
            row_html += f'<td class="wc-meta-col">{hc_disp}</td>'
        if _pref_on("total"):
            row_html += f'<td class="total-col {strike_class}">{_wc_cell(total_str, total_plain, "total_points_raw", None, 24)}</td>'
        if show_df95_disc_column and _pref_on("total"):
            disc_plain = _df95_disc_display(r.get("total"), r.get("nett"), use_decimals_in_block)
            disc_str = html_module.escape(disc_plain)
            row_html += f'<td class="disc-col {strike_class}">{disc_str}</td>'
        if _pref_on("nett"):
            row_html += f'<td class="nett-col {strike_class}">{_wc_cell(nett_str, nett_plain, "nett_points_raw", None, 24)}</td>'
        row_html += "</tr>"
        trs.append(row_html)
    table_html = f'<table class="fleet-results-table"><thead><tr>{thead}</tr></thead><tbody>{"".join(trs)}</tbody></table>'
    course_footer_html = _course_data_footer_html(rows) if show_pcs_times else ""
    bid_data = (block_id or "").strip()
    bid_attr = f' data-block-id="{html_module.escape(bid_data, quote=True)}"' if bid_data else ""
    _fleet_left_col, _fleet_right_col = ("", "")
    if show_fleet_header_logos:
        _fleet_left_col, _fleet_right_col = _fleet_class_header_logo_columns_html(fleet, regatta_id)
    _closed_badge = (
        '<span class="fleet-entries-closed-badge">Entries closed</span>' if entries_closed else ""
    )
    if sa_fleet_ops and (block_id or "").strip():
        _bid_esc = html_module.escape(str(block_id), quote=True)
        _rid_esc = html_module.escape(str(regatta_id or ""), quote=True)
        _chk = " checked" if entries_closed else ""
        _ops_left = (
            f'<div class="fleet-ops-left wc-sa-edit-only">'
            f'<label class="fleet-close-entry">'
            f'<input type="checkbox" class="fleet-entries-closed" data-block-id="{_bid_esc}" '
            f'data-regatta-id="{_rid_esc}"{_chk}>'
            f"Close entry</label></div>"
        )
        _ops_right = (
            f'<div class="fleet-ops-right wc-sa-edit-only">'
            f'<label class="fleet-races-n">Races '
            f'<input type="number" class="fleet-races-input" min="0" max="99" step="1" '
            f'value="{int(races_sailed_db)}" data-block-id="{_bid_esc}" data-regatta-id="{_rid_esc}">'
            f"</label></div>"
        )
        _fleet_center_inner = (
            f'<div class="fleet-title-row fleet-title-row--ops">'
            f"{_ops_left}"
            f'<div class="fleet-ops-center">{fleet_header_html}{_closed_badge}</div>'
            f"{_ops_right}"
            f"</div>"
            f'<div class="sailed-line">{html_module.escape(sailed_line)}</div>'
        )
    else:
        _fleet_center_inner = (
            f'<div class="fleet-title-row">{fleet_header_html}{_closed_badge}</div>'
            f'<div class="sailed-line">{html_module.escape(sailed_line)}</div>'
        )
    _race_legend = _race_legend_line()
    if _race_legend:
        _fleet_center_inner += f'<div class="sailed-line">{html_module.escape(_race_legend)}</div>'
    if _fleet_left_col or _fleet_right_col:
        _fleet_hdr_cls = "class-header class-header--with-logos"
        _fleet_hdr_body = (
            f'{_fleet_left_col}<div class="class-header-main-col">{_fleet_center_inner}</div>{_fleet_right_col}'
        )
    else:
        _fleet_hdr_cls = "class-header"
        _fleet_hdr_body = _fleet_center_inner
    section_html = (
        f'<div class="fleet-section"{bid_attr}>'
        f"{late_part}"
        f'<div class="{_fleet_hdr_cls}">{_fleet_hdr_body}</div>'
        f'<div class="table-wrapper">{table_html}{course_footer_html}</div></div>'
    )
    return (section_html, late_external_out)


def _render_fleet_section_html_for_block(
    regatta_id: str,
    block_id: str,
    *,
    standalone_class_page: bool = False,
    wc_sa_fleet_edit: bool = True,
) -> Optional[str]:
    """Rebuild one `.fleet-section` using the same pipeline as standalone regatta pages (live refresh after PATCH)."""
    data = _get_regatta_full_page_data(str(regatta_id))
    if not data or len(data) < 5:
        return None
    fleets = data[4]
    _rid_rb = str(regatta_id)
    _use_wc_rb = _regatta_slug_is_sa_pilot_standalone(_rid_rb)
    wc_prefs = _merge_wc_column_prefs_for_regatta(_rid_rb) if _use_wc_rb else None
    _show_fleet_hdr_logos = _wc_regatta_show_fleet_header_logos(_rid_rb) if _use_wc_rb else True
    for f in fleets:
        if str(f.get("block_id") or "") == str(block_id):
            sec, _late_ext = _render_result_sheet_fleet(
                f,
                standalone_class_page=standalone_class_page,
                column_prefs=wc_prefs if _use_wc_rb else None,
                wc_sa_fleet_edit=wc_sa_fleet_edit,
                show_fleet_header_logos=_show_fleet_hdr_logos,
                # Late strip + holds live outside `.fleet-section` on full page; omit from PATCH HTML to avoid duplicates.
                wc_show_late_entry_strip=False,
            )
            return sec
    return None


