def _club_page_normalize_event_stem(name: str) -> str:
    """Collapse year/date/fleet suffixes so recurring HOSTED events group together."""
    s = (name or "").lower()
    s = re.sub(r"\b20\d{2}\b", " ", s)
    s = re.sub(r"\b\d{4}-\d{2}-\d{2}\b", " ", s)
    s = re.sub(r"\b(results?|provisional|final|as at)\b", " ", s)
    s = re.sub(r"[^a-z0-9\s]", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    if "cape classic" in s:
        m = re.search(r"\b([a-z]{2,6})\s+cape classic\b", s)
        return ((m.group(1) + " cape classic") if m else "cape classic")
    if "sonnet national" in s:
        return "sonnet nationals"
    if "youth national" in s:
        return "youth nationals"
    if "windsurfer" in s:
        return "windsurfer lt nationals"
    s = re.sub(
        r"\b(optimist\s*[abc]?|ilca\s*[0-9.]+|dabchick|sonnet|mirror|hobie\s*\d*|29er|420|open)\b$",
        " ",
        s,
    )
    return re.sub(r"\s+", " ", s).strip()


def _club_page_pretty_event_title(stem: str, sample: str = "") -> str:
    st = (stem or "").strip().lower()
    if "cape classic" in st:
        m = re.search(r"\b([a-z]{2,6})\s+cape classic\b", st)
        return f"{(m.group(1).upper() + ' ') if m else ''}Cape Classic"
    if st == "sonnet nationals":
        return "Sonnet Nationals"
    if st == "youth nationals":
        return "Youth Nationals"
    if st == "windsurfer lt nationals":
        return "Windsurfer LT Nationals"
    raw = (sample or stem or "").strip()
    raw = re.sub(r"^\d{4}-\d{2}-\d{2}\s+", "", raw)
    raw = re.sub(r"\b20\d{2}\b", "", raw)
    raw = re.sub(r"\b(results?|provisional|final|dec|jan|feb|mar|apr)\b", "", raw, flags=re.I)
    raw = re.sub(r"\s+", " ", raw).strip(" -")
    if not raw:
        raw = stem
    parts = []
    for w in raw.split():
        if w.upper() in {"HYC", "SA", "SAS", "WC", "ILCA", "RCYC", "HMYC", "LT"}:
            parts.append(w.upper())
        elif re.match(r"^[0-9]", w):
            parts.append(w)
        else:
            parts.append(w[:1].upper() + w[1:].lower())
    return " ".join(parts)


def _club_page_recurring_event_insights(club_id: int, cur=None, limit: int = 6) -> list:
    """Recurring HOSTED events only (host_club_id). Never invent — needs 2+ years of data."""
    if not club_id:
        return []
    rows = []
    own = cur is None
    conn = None
    try:
        if own:
            conn = get_db_connection()
            cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        # Hosted only — regattas + SAS calendar events with this host
        cur.execute(
            """
            SELECT event_name, start_date::date AS d, regatta_id::text AS link_id, 'regatta' AS kind
            FROM regattas
            WHERE host_club_id = %s AND event_name IS NOT NULL AND start_date IS NOT NULL
            UNION ALL
            SELECT event_name, start_date::date AS d, NULL::text AS link_id, 'event' AS kind
            FROM events
            WHERE host_club_id = %s AND event_name IS NOT NULL AND start_date IS NOT NULL
            """,
            (int(club_id), int(club_id)),
        )
        rows = cur.fetchall() or []
    except Exception as e:
        print(f"[club page] recurring: {e}")
        rows = []
    finally:
        if own and conn is not None:
            try:
                cur.close()
            except Exception:
                pass
            return_db_connection(conn)

    buckets = {}
    for r in rows:
        name = (r.get("event_name") or "").strip()
        d = r.get("d")
        if not name or not d:
            continue
        stem = _club_page_normalize_event_stem(name)
        if len(stem) < 6:
            continue
        if stem in {"nationals", "championship", "regatta", "results"}:
            continue
        try:
            mon = int(d.month)
            yr = int(d.year)
        except Exception:
            continue
        b = buckets.setdefault(
            stem, {"months": [], "years": set(), "samples": [], "count": 0, "regatta_ids": []}
        )
        b["months"].append(mon)
        b["years"].add(yr)
        b["samples"].append(name)
        b["count"] += 1
        rid = (r.get("link_id") or "").strip()
        if rid and rid not in b["regatta_ids"]:
            b["regatta_ids"].append(rid)

    insights = []
    from collections import Counter

    for stem, b in buckets.items():
        years = sorted(b["years"])
        # Hard gate: do not claim annual/recurring without 2+ distinct years
        if len(years) < 2:
            continue
        mc = Counter(b["months"])
        mon, mon_n = mc.most_common(1)[0]
        month_name = _MONTH_NAMES[mon] if 1 <= mon <= 12 else ""
        title = _club_page_pretty_event_title(stem, b["samples"][0] if b["samples"] else stem)
        is_series = ("series" in stem) or ("classic" in stem) or (b["count"] >= 4 and len(years) >= 2)
        # Month claim only when that month appears in ≥2 years (not one busy multi-fleet weekend)
        month_years = set()
        # approximate: if modal month count spans multiple years via year set size and mon_n
        months_by_year_ok = mon_n >= 2 and len(years) >= 2

        if is_series and months_by_year_ok and month_name:
            text = (
                f"{title} is a series hosted at this club and normally takes place "
                f"in {month_name} each year ({years[0]}–{years[-1]})."
            )
        elif months_by_year_ok and month_name:
            text = (
                f"{title} is regularly hosted at this club, typically in {month_name} "
                f"({years[0]}–{years[-1]})."
            )
        else:
            text = (
                f"{title} has been hosted at this club in {len(years)} years "
                f"({years[0]}–{years[-1]})."
            )

        href = ""
        if b["regatta_ids"]:
            href = f"/regatta/{b['regatta_ids'][0]}"
        insights.append(
            {
                "stem": stem,
                "title": title,
                "text": text,
                "href": href,
                "score": len(years) * 10 + mon_n + (8 if "classic" in stem else 0) + (5 if is_series else 0),
                "count": b["count"],
            }
        )

    insights.sort(key=lambda x: (-x["score"], -x["count"], x["title"]))
    out = []
    seen_t = set()
    for it in insights:
        key = re.sub(r"[^a-z0-9]", "", it["title"].lower())[:40]
        if key in seen_t:
            continue
        seen_t.add(key)
        out.append(it)
        if len(out) >= limit:
            break
    return out



def _event_logo_catalogue_href(src: str, fallback_regatta_id: str = "") -> str:
    """Event Logo tile → /events-logos/{slug} (all years). Class Logo → /classes or regatta."""
    from pathlib import Path as _P
    import re as _re
    s = (src or "").strip()
    if "/Class Logo/" in s or "/artwork/Class Logo/" in s:
        name = _P(s.split("?")[0]).name
        stem = _P(name).stem
        stem = _re.sub(r"(?i)[\s_-]+(class[\s_-]*logo|logo)$", "", stem)
        slug = _re.sub(r"[^a-z0-9]+", "-", stem.lower()).strip("-")
        if slug:
            return f"/classes/{slug}"
        rid = (fallback_regatta_id or "").strip()
        return f"/regatta/{rid}" if rid else "/classes"
    name = _P(s.split("?")[0]).name
    stem = _P(name).stem
    stem = _re.sub(r"(?i)[\s_-]+(class[\s_-]*logo|event[\s_-]*logo|logo)$", "", stem)
    slug = _re.sub(r"[^a-z0-9]+", "-", stem.lower()).strip("-") or "event"
    return f"/events-logos/{slug}"

def _club_page_hosted_event_logos(club_id: int, limit: int = 40, cur=None) -> list:
    """Event logos for events this club HOSTED (host_club_id).

    Sources (in order):
      1) wc_regatta_header_icons.json left artwork for hosted regatta_ids
      2) specific name→logo rules (_CLUB_EVENT_LOGO_RULES)

    Deduped by logo path; sorted alphabetically by label.
    """
    if not club_id:
        return []
    rows = []
    own = cur is None
    conn = None
    try:
        if own:
            conn = get_db_connection()
            cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        cur.execute(
            """
            SELECT event_name, regatta_id::text AS regatta_id
            FROM regattas
            WHERE host_club_id = %s AND event_name IS NOT NULL
            ORDER BY COALESCE(start_date, end_date) DESC NULLS LAST
            LIMIT 120
            """,
            (int(club_id),),
        )
        rows = list(cur.fetchall() or [])
        # Calendar events.host_club_id is often wrong — logos use regattas only.
    except Exception as e:
        print(f"[club page] event logos: {e}")
        rows = []
    finally:
        if own and conn is not None:
            try:
                cur.close()
            except Exception:
                pass
            return_db_connection(conn)

    header_map = {}
    for hp in (
        Path("/var/www/sailingsa/data/wc_regatta_header_icons.json"),
        Path("/var/www/sailingsa/deploy/wc_regatta_header_icons.json"),
    ):
        try:
            if hp.is_file():
                import json as _json

                raw = _json.loads(hp.read_text(encoding="utf-8"))
                if isinstance(raw, dict):
                    header_map = raw
                    break
        except Exception:
            pass

    def _disk_ok(src: str) -> bool:
        rel = (src or "").lstrip("/")
        if not rel:
            return False
        return (Path("/var/www/sailingsa/api") / rel).is_file() or (
            Path("/var/www/sailingsa") / rel
        ).is_file()



    def _pretty_hosted_label(ename: str, src: str) -> str:
        """Human label from event name; never show raw Class/Event Logo filename stems."""
        src_l = (src or "").lower()
        if "western-cape-dinghy" in src_l or "wc-dinghy-champs" in src_l:
            return "WC Dinghy Champs"
        if "cape-classic" in src_l:
            return "Cape Classic"
        if "youth-nationals" in src_l:
            return "Youth Nationals"
        if "sonnet-nationals" in src_l:
            return "Sonnet Nationals"
        if "overberg" in src_l:
            return "Overberg Champs"
        if "sa-sailing-wc-youth" in src_l:
            return "WC Youth"
        if "sa-nationals" in src_l:
            return "Nationals"
        if "windsurfer" in src_l:
            return "Windsurfer LT"
        en = (ename or "").strip()
        if en:
            raw = re.sub(r"^\d{4}-\d{2}-\d{2}\s+", "", en)
            raw = re.sub(r"\b20\d{2}\b", "", raw)
            raw = re.sub(
                r"\b(results?|provisional|final|as at)\b.*$",
                "",
                raw,
                flags=re.I,
            )
            raw = re.sub(r"\s+", " ", raw).strip(" -")
            low = raw.lower()
            if "dinghy" in low and (
                "wc" in low
                or "western cape" in low
                or "w. cape" in low
                or "w cape" in low
            ):
                return "WC Dinghy Champs"
            if "29er" in low and "national" in low:
                return "29er Nationals"
            if "rs tera" in low and ("western cape" in low or "wc" in low):
                return "RS Tera WC Champs"
            parts = []
            for w in raw.split():
                wu = w.upper()
                if wu in {
                    "WC", "SA", "SAS", "RSA", "ILCA", "RCYC", "HYC", "SBYC",
                    "DF95", "IOM", "RS",
                }:
                    parts.append(wu)
                elif re.match(r"^[0-9]", w):
                    parts.append(w)
                else:
                    parts.append(w[:1].upper() + w[1:].lower())
            label = " ".join(parts).strip()
            if label:
                return label
        base = Path((src or "").split("?")[0]).stem
        base = re.sub(r"(?i)[-_]?(class[-_]?logo|event[-_]?logo|logo)$", "", base)
        base = base.replace("-", " ").replace("_", " ")
        base = re.sub(r"\b20\d{2}\b", "", base).strip()
        parts = []
        for w in base.split():
            wu = w.upper()
            if wu in {"WC", "SA", "SAS", "RSA", "ILCA", "RS", "DF95", "IOM"}:
                parts.append(wu)
            elif re.match(r"^[0-9]", w):
                parts.append(w)
            else:
                parts.append(w[:1].upper() + w[1:].lower())
        return " ".join(parts) or "Event"


    items_by_src = {}

    # 1) Header icons for hosted regatta_ids (most accurate — same logo as live /regatta page)
    for r in rows:
        rid = (r.get("regatta_id") or "").strip()
        if not rid:
            continue
        entry = header_map.get(rid)
        if not isinstance(entry, dict):
            continue
        src = (entry.get("left") or "").strip()
        if not src or "/artwork/" not in src:
            continue
        if not src.startswith("/"):
            src = "/" + src.lstrip("/")
        # Prefer Event Logo; allow Class Logo when used as event branding (e.g. 29er nationals)
        if "/Event Logo/" not in src and "/Class Logo/" not in src:
            continue
        if not _disk_ok(src):
            continue
        ename = (r.get("event_name") or "").strip()
        label = _pretty_hosted_label(ename, src)
        # Normalize known WC dinghy artwork label
        if "western-cape-dinghy" in src.lower() or "wc-dinghy-champs" in src.lower():
            label = "WC Dinghy Champs"
        elif "sa-nationals" in src.lower():
            label = "Nationals"
        elif "29er" in src.lower() and "nationals" in ename.lower():
            label = "29er Nationals"
        href = _event_logo_catalogue_href(src, rid)
        prev = items_by_src.get(src)
        if prev is None or (href and not prev.get("href")):
            items_by_src[src] = {
                "label": label,
                "src": src,
                "kind": "event",
                "href": href,
                "title": f"{label} — all years using this event logo",
            }

    # 2) Name→logo rules for hosted names (covers calendar-only + missing header entries)
    seen_src = set(items_by_src.keys())
    for needle, src, label in _CLUB_EVENT_LOGO_RULES:
        if src in seen_src:
            continue
        match_row = None
        for r in rows:
            name = (r.get("event_name") or "").lower()
            rid = (r.get("regatta_id") or "").lower()
            hay = f"{name} {rid}"
            if needle in hay:
                match_row = r
                break
        if not match_row:
            continue
        if not _disk_ok(src):
            continue
        seen_src.add(src)
        href = _event_logo_catalogue_href(src, (match_row.get("regatta_id") or "").strip())
        items_by_src[src] = {
            "label": label,
            "src": src,
            "kind": "event",
            "href": href,
            "title": f"{label} — all years using this event logo",
        }

    
    def _logo_stem(src: str) -> str:
        base = Path((src or "").split("?")[0]).name.lower()
        base = re.sub(r"\.(png|jpe?g|webp|gif|svg)$", "", base)
        base = re.sub(r"[-_]?(class[-_]?logo|event[-_]?logo|logo)$", "", base)
        return re.sub(r"[^a-z0-9]+", "", base)

    def _clean_label(label: str) -> str:
        s = (label or "").strip()
        s = re.sub(r"(?i)\s+(class\s+)?logo$", "", s).strip()
        s = re.sub(r"\s+", " ", s)
        return s

    def _specificity(label: str) -> tuple:
        lab = (label or "").lower()
        score = 0
        if "national" in lab:
            score += 40
        if "championship" in lab or "champs" in lab:
            score += 25
        if "series" in lab or "classic" in lab:
            score += 15
        if "youth" in lab or "region" in lab or "provincial" in lab:
            score += 10
        score += min(len(lab), 40)
        return (score, len(lab))

    raw_items = list(items_by_src.values())
    # Same artwork stem → keep the more specific title
    # e.g. "29er Nationals" trumps bare "29er".
    best_by_stem: dict = {}
    for it0 in raw_items:
        it = dict(it0)
        it["label"] = _clean_label(it.get("label") or "")
        stem = _logo_stem(it.get("src") or "") or re.sub(
            r"[^a-z0-9]+", "", (it["label"] or "").lower()
        )
        prev = best_by_stem.get(stem)
        if prev is None or _specificity(it["label"]) > _specificity(prev.get("label") or ""):
            if prev and prev.get("href") and not it.get("href"):
                it["href"] = prev["href"]
            it["title"] = f"{it['label']} — hosted at this club"
            best_by_stem[stem] = it

    kept = list(best_by_stem.values())
    labels_l = [(it, (it.get("label") or "").strip().lower()) for it in kept]
    drop = set()
    for i, (it_a, la) in enumerate(labels_l):
        if not la:
            drop.add(i)
            continue
        for j, (it_b, lb) in enumerate(labels_l):
            if i == j or not lb:
                continue
            if lb.startswith(la + " ") or lb.startswith(la + "-"):
                drop.add(i)
                break
            ta = la.split()[0]
            tb = lb.split()[0]
            if (
                ta == tb
                and la != lb
                and len(lb) > len(la)
                and any(k in lb for k in ("national", "champs", "championship", "series"))
                and not any(k in la for k in ("national", "champs", "championship", "series"))
            ):
                drop.add(i)
                break

    items = [it for i, it in enumerate(kept) if i not in drop]
    items = sorted(items, key=lambda x: (x.get("label") or "").lower())
    out = []
    seen_lab = set()
    for it in items:
        lab = (it.get("label") or "").strip().lower()
        if not lab or lab in seen_lab:
            continue
        seen_lab.add(lab)
        out.append(it)
        if len(out) >= int(limit):
            break
    return out



def _club_page_logo_chips_html(
    items: list,
    section_label: str,
    table_id: str = "",
    *,
    popover_html: str = "",
    host_class: str = "",
) -> str:
    """Logo chip grid inside an outer panel — no table, no search (header strips only).

    Optional popover_html is shown on hover/focus of the panel (e.g. recurring events).
    """
    if not items and not popover_html:
        return ""
    chips = []
    for it in items:
        src = (it.get("src") or "").strip()
        raw_label = (it.get("label") or "").strip()
        label = html_module.escape(raw_label)
        href = (it.get("href") or "").strip()
        tip = html_module.escape((it.get("title") or raw_label).strip())
        inner_img = ""
        if src:
            inner_img = (
                f'<img src="{html_module.escape(src)}" alt="" '
                f'loading="lazy" decoding="async" />'
            )
        inner = f'{inner_img}<span class="club-story-chip-label">{label}</span>'
        if href:
            chips.append(
                f'<a class="club-story-chip" href="{html_module.escape(href)}" title="{tip}">{inner}</a>'
            )
        elif src:
            chips.append(f'<span class="club-story-chip" title="{tip}">{inner}</span>')
        else:
            chips.append(f'<span class="club-story-chip club-story-chip-text">{label}</span>')
    extra = (" " + host_class.strip()) if host_class else ""
    if popover_html and "club-story-events-host" not in extra:
        extra += " club-story-events-host"
    pop = ""
    if popover_html:
        pop = (
            f'<div class="club-story-events-popover" role="tooltip">'
            f"{popover_html}</div>"
        )
    chips_html = (
        f'<div class="club-story-logo-chips">{"".join(chips)}</div>' if chips else ""
    )
    return (
        f'<div class="club-story-panel club-story-logo-row{extra}" tabindex="0">'
        f'<div class="club-story-logo-row-label">{html_module.escape(section_label)}</div>'
        f"{chips_html}{pop}</div>"
    )



