def _club_page_map_embed_html(p: dict) -> str:
    """Centered clickable Google Maps embed from gps_coordinates / address / location_url."""
    gps = (p.get("gps_coordinates") or "").strip()
    address = (p.get("address") or "").strip()
    name = (p.get("club_fullname") or p.get("club_abbrev") or "Yacht Club").strip()
    location_url = (p.get("location_url") or "").strip()
    q = ""
    if gps and re.match(r"^-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?$", gps):
        q = re.sub(r"\s+", "", gps)
    elif address:
        q = f"{name}, {address}"
    elif name:
        q = f"{name}, South Africa"
    else:
        return ""
    from urllib.parse import quote as _urlquote
    embed_src = "https://maps.google.com/maps?q=" + _urlquote(q) + "&z=14&output=embed"
    open_href = html_module.escape(location_url or ("https://www.google.com/maps?q=" + _urlquote(q)))
    # No iframe src on initial HTML — Maps is heavy; mount only on first hover.
    return (
        '<div class="club-story-map-wrap" '
        f'data-map-src="{html_module.escape(embed_src)}" data-map-href="{open_href}">'
        '<a class="club-story-map-frame-link" href="' + open_href + '" target="_blank" rel="noopener noreferrer" '
        'aria-label="Open club location in Google Maps">'
        '<div class="club-story-map-placeholder">Map loads on hover…</div>'
        '<span class="club-story-map-open">Open in Maps / Directions</span>'
        "</a>"
        "</div>"
    )


def _club_page_story_header_html(
    club_id: int,
    club_heading_html: str,
    club_logo_html: str,
    ca: str,
) -> str:
    """Rich bio/header: facts only — hosted events vs sailor classes kept separate."""
    p = {
        "province": "", "country": "", "address": "", "phone": "", "fax": "",
        "phone_mobile": "", "email": "", "contact_name": "", "office_hours": "",
        "location_url": "", "website_url": "", "facebook_url": "", "instagram_url": "",
        "gps_coordinates": "", "about_text": "", "year_established": None, "annual_events_note": "",
        "club_fullname": "", "club_abbrev": "",
    }
    class_items = []
    event_items = []
    recurring = []
    conn = None
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            p = _club_page_profile_dict(int(club_id), cur=cur)
            class_items = _club_page_top_class_logos(int(club_id), limit=40, cur=cur)
            event_items = _club_page_hosted_event_logos(int(club_id), limit=40, cur=cur)
            recurring = _club_page_recurring_event_insights(int(club_id), cur=cur, limit=5)
        finally:
            cur.close()
    except Exception as e:
        print(f"[club page] story fetch: {e}")
    finally:
        if conn is not None:
            return_db_connection(conn)

    abbrev = (p.get("club_abbrev") or ca or "").strip() or "this club"

    age_bits = []
    ye = p.get("year_established")
    if ye:
        try:
            from datetime import date as _date
            years = max(0, _date.today().year - int(ye))
            age_bits.append(f"Founded {int(ye)}")
            if years:
                age_bits.append(f"{years} years old")
        except Exception:
            age_bits.append(f"Founded {ye}")
    if p.get("province"):
        age_bits.append(p["province"])
    meta_line = " · ".join(age_bits)

    socials = "".join(
        [
            _club_page_social_icon_link(p.get("website_url") or "", "website"),
            _club_page_social_icon_link(p.get("facebook_url") or "", "facebook"),
            _club_page_social_icon_link(p.get("instagram_url") or "", "instagram"),
            _club_page_social_icon_link(p.get("location_url") or "", "maps"),
        ]
    )

    # Data-driven hosted recurrence only — do NOT fall back to free-text notes that may overclaim
    sig_items = sorted(recurring, key=lambda x: (x.get('title') or x.get('label') or '').lower())

    contact_bits = []
    if p.get("contact_name"):
        contact_bits.append(f'<span><strong>Manager:</strong> {html_module.escape(p["contact_name"])}</span>')
    if p.get("phone"):
        contact_bits.append(
            f'<span><strong>Phone:</strong> <a href="tel:{html_module.escape(p["phone"].replace(" ", ""))}">{html_module.escape(p["phone"])}</a></span>'
        )
    if p.get("phone_mobile"):
        contact_bits.append(
            f'<span><strong>Mobile:</strong> <a href="tel:{html_module.escape(p["phone_mobile"].replace(" ", ""))}">{html_module.escape(p["phone_mobile"])}</a></span>'
        )
    if p.get("email"):
        contact_bits.append(
            f'<span><strong>Email:</strong> <a href="mailto:{html_module.escape(p["email"])}">{html_module.escape(p["email"])}</a></span>'
        )
    if p.get("fax"):
        contact_bits.append(f'<span><strong>Fax:</strong> {html_module.escape(p["fax"])}</span>')

    loc_line = ""
    if p.get("address"):
        addr = html_module.escape(p["address"])
        if p.get("location_url"):
            loc_line = (
                f'<a class="club-story-map-link" href="{html_module.escape(p["location_url"])}" '
                f'target="_blank" rel="noopener noreferrer">{addr}</a>'
            )
        else:
            loc_line = addr

    map_html = _club_page_map_embed_html(p)

    # Club logo clickable → website if known
    logo_block = club_logo_html
    if club_logo_html and (p.get("website_url") or "").strip():
        logo_block = (
            f'<a class="club-page-logo-link" href="{html_module.escape(p["website_url"].strip())}" '
            f'target="_blank" rel="noopener noreferrer" title="Club website">{club_logo_html}</a>'
        )

    blocks = [
        f'<div class="header club-page-header club-story-header">'
        f'<div class="club-story-inner">'
        f'<div class="club-story-panel club-story-identity">'
        f'<div class="club-story-title-row">'
        f"<h1>{club_heading_html}</h1>"
        f"{logo_block}"
        f"</div>"
    ]
    if meta_line:
        blocks.append(f'<p class="club-story-meta">{html_module.escape(meta_line)}</p>')
    blocks.append("</div>")
    if p.get("about_text"):
        blocks.append(
            '<div class="club-story-panel club-story-block"><div class="club-story-block-label">About</div>'
            f'<div class="club-story-block-body club-story-about">{html_module.escape(p["about_text"])}</div></div>'
        )
    if contact_bits or p.get("office_hours"):
        contact_body = ""
        if contact_bits:
            contact_body += (
                f'<div class="club-story-block-body club-story-contact">{" ".join(contact_bits)}</div>'
            )
        if p.get("office_hours"):
            contact_body += (
                '<div class="club-story-office-hours">'
                '<div class="club-story-office-hours-label">Office hours</div>'
                f'<div class="club-story-block-body">{html_module.escape(p["office_hours"])}</div>'
                "</div>"
            )
        blocks.append(
            '<div class="club-story-panel club-story-block"><div class="club-story-block-label">Contact</div>'
            f"{contact_body}"
            "</div>"
        )
    if socials:
        blocks.append(
            f'<div class="club-story-panel club-story-socials-wrap">'
            f'<div class="club-story-block-label">Links</div>'
            f'<div class="club-story-socials">{socials}</div></div>'
        )
    if loc_line or map_html:
        map_block = (
            f'<div class="club-story-location-map">{map_html}</div>' if map_html else ""
        )
        body = loc_line or ""
        blocks.append(
            '<div class="club-story-panel club-story-block club-story-location">'
            '<div class="club-story-block-label">Location</div>'
            f'<div class="club-story-block-body">{body}</div>'
            f"{map_block}"
            "</div>"
        )
    recurring_popover = ""
    if sig_items:
        lis = []
        for it in sig_items:
            txt = html_module.escape(it["text"])
            href = (it.get("href") or "").strip()
            if href:
                lis.append(
                    f'<li><a href="{html_module.escape(href)}">{txt}</a></li>'
                )
            else:
                lis.append(f"<li>{txt}</li>")
        recurring_popover = (
            '<div class="club-story-block-label">'
            f"Recurring events hosted at {html_module.escape(abbrev)}"
            "</div>"
            f'<ul class="club-story-when">{"".join(lis)}</ul>'
        )
    blocks.append(
        _club_page_logo_chips_html(
            event_items,
            f"Events hosted at {abbrev}",
            "club-events-logos-table",
            popover_html=recurring_popover,
            host_class="club-story-events-host",
        )
    )
    blocks.append(
        _club_page_logo_chips_html(
            class_items,
            f"Classes sailed by {abbrev} sailors (any venue)",
            "club-classes-logos-table",
        )
    )
    blocks.append("</div></div>")
    blocks.append("""<script>
(function(){
  function mountClubMap(loc){
    if (!loc || loc.getAttribute("data-map-mounted") === "1") return;
    var wrap = loc.querySelector(".club-story-map-wrap[data-map-src]");
    if (!wrap) return;
    var src = wrap.getAttribute("data-map-src") || "";
    var href = wrap.getAttribute("data-map-href") || "#";
    if (!src) return;
    var link = wrap.querySelector(".club-story-map-frame-link");
    if (!link) return;
    var ph = wrap.querySelector(".club-story-map-placeholder");
    if (ph) ph.remove();
    if (!link.querySelector("iframe.club-story-map-iframe")) {
      var ifr = document.createElement("iframe");
      ifr.className = "club-story-map-iframe";
      ifr.src = src;
      ifr.title = "Club location map";
      ifr.setAttribute("loading", "lazy");
      ifr.setAttribute("referrerpolicy", "no-referrer-when-downgrade");
      var open = link.querySelector(".club-story-map-open");
      if (open) link.insertBefore(ifr, open);
      else link.appendChild(ifr);
    }
    link.setAttribute("href", href);
    loc.setAttribute("data-map-mounted", "1");
  }
  function wireClubMapHover(){
    var pin = document.querySelector(".club-story-maps-trigger");
    var loc = document.querySelector(".club-story-location");
    if (!loc) return;
    var hideTimer = null;
    function show(){
      clearTimeout(hideTimer);
      mountClubMap(loc);
      loc.classList.add("is-map-show");
    }
    function scheduleHide(){
      clearTimeout(hideTimer);
      hideTimer = setTimeout(function(){ loc.classList.remove("is-map-show"); }, 180);
    }
    if (pin) {
      pin.addEventListener("mouseenter", show);
      pin.addEventListener("mouseleave", scheduleHide);
      pin.addEventListener("focus", show);
      pin.addEventListener("blur", scheduleHide);
    }
    loc.addEventListener("mouseenter", show);
    loc.addEventListener("mouseleave", scheduleHide);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", wireClubMapHover);
  else wireClubMapHover();
})();
</script>""")
    return "".join(blocks)


def _serve_club_page_impl(slug: str, club: tuple):
    club_id, club_name, club_abbrev = club
    base_url = _canonical_base_url()
    club_code = _club_slug_from_name(club_abbrev) if (club_abbrev and str(club_abbrev).strip()) else _club_slug_from_name(club_name or "")
    slug_is_name = bool(club_code and slug.strip().lower() != club_code)
    if slug_is_name:
        return RedirectResponse(url=f"{base_url}/club/{club_code}", status_code=301)
    canonical_url = f"{base_url}/club/{slug}"
    ca = (club_abbrev or "").strip()
    cn = (club_name or "").strip()
    if ca and cn and ca.lower() != cn.lower():
        club_heading_html = f"{html_module.escape(ca)} - {html_module.escape(cn)}"
    elif cn:
        club_heading_html = html_module.escape(cn)
    elif ca:
        club_heading_html = html_module.escape(ca)
    else:
        club_heading_html = "Club"

    sailors = []
    regattas_hosted = []
    regatta_ids_with_results: Set[str] = set()
    unassigned_id = _get_unassigned_club_id()
    is_unassigned = unassigned_id is not None and int(club_id) == int(unassigned_id)
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT DISTINCT s.sa_sailing_id::text AS sas_id,
                       COALESCE(TRIM(s.full_name), TRIM(s.first_name || ' ' || COALESCE(s.last_name, ''))) AS full_name,
                       COALESCE(TRIM(s.first_name), '') AS first_name,
                       COALESCE(TRIM(s.last_name), '') AS last_name,
                       COALESCE(s.last_name, '') AS ord_ln,
                       COALESCE(s.first_name, '') AS ord_fn
                FROM sas_id_personal s
                JOIN results r ON (
                    r.helm_sa_sailing_id::text = s.sa_sailing_id::text
                    OR r.crew_sa_sailing_id::text = s.sa_sailing_id::text
                )
                WHERE r.club_id = %s
                  AND (s.full_name IS NOT NULL OR s.first_name IS NOT NULL OR s.last_name IS NOT NULL)
                ORDER BY ord_fn ASC, ord_ln ASC
            """, (club_id,))
            rows = cur.fetchall() or []
            by_name = {}
            for r in rows:
                full = (r.get("full_name") or "").strip()
                if not full:
                    continue
                ln = (r.get("last_name") or "").strip()
                fn = (r.get("first_name") or "").strip()
                # Display: given name, surname (e.g. "Ross, Walton")
                parts = [x for x in (fn, ln) if x]
                display = ", ".join(parts) if parts else full
                sid = str(r.get("sas_id") or "")
                if full not in by_name:
                    by_name[full] = {"display": display, "sids": [], "fn": fn, "ln": ln}
                by_name[full]["sids"].append(sid)
            def _given_then_surname_key(item):
                full, data = item[0], item[1]
                fn = (data.get("fn") or "").strip()
                ln = (data.get("ln") or "").strip()
                if not fn and not ln:
                    d = (data.get("display") or "").strip()
                    if "," in d:
                        fn = (d.split(",", 1)[0] or "").strip()
                        ln = (d.split(",", 1)[1] or "").strip()
                return (fn.upper(), ln.upper(), full.upper())

            for full, data in sorted(by_name.items(), key=_given_then_surname_key):
                sids = data["sids"]
                display = data["display"]
                has_dup = len(sids) > 1
                s = _sailor_canonical_slug(full, sids[0], has_dup)
                sailors.append((display, s))

            cur.execute(
                """
                SELECT DISTINCT reg.regatta_id, reg.event_name,
                       COALESCE(
                         reg.start_date,
                         reg.end_date,
                         CASE
                           WHEN reg.regatta_id ~ '^[0-9]+-[0-9]{4}-' THEN
                             make_date((substring(reg.regatta_id from '^[0-9]+-([0-9]{4})-'))::int, 1, 15)
                           ELSE NULL
                         END
                       ) AS start_date,
                       COALESCE(reg.end_date, reg.start_date) AS end_date
                FROM regattas reg
                WHERE reg.host_club_id = %s
                ORDER BY COALESCE(
                  reg.start_date,
                  reg.end_date,
                  CASE
                    WHEN reg.regatta_id ~ '^[0-9]+-[0-9]{4}-' THEN
                      make_date((substring(reg.regatta_id from '^[0-9]+-([0-9]{4})-'))::int, 1, 15)
                    ELSE NULL
                  END
                ) DESC NULLS LAST
                """,
                (club_id,),
            )
            regattas_hosted = _regatta_sql_rows_to_match_tuples(cur.fetchall() or [])
            rids = [str(t[1]).strip() for t in regattas_hosted if len(t) > 1 and t[1]]
            if rids:
                cur.execute(
                    "SELECT DISTINCT regatta_id::text AS regatta_id FROM results WHERE regatta_id = ANY(%s)",
                    (rids,),
                )
                regatta_ids_with_results = {str(r.get("regatta_id") or "").strip() for r in (cur.fetchall() or [])}
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[club page] fetch data: {e}")

    json_ld = {
        "@context": "https://schema.org",
        "@type": "SportsOrganization",
        "name": (f"{ca} - {cn}" if (ca and cn) else (cn or ca or "Club")),
        "sport": "Sailing",
    }

    # Three lists: Upcoming | Past Events / Regattas Hosted (results) | Other (no results).
    regattas_with_results = _club_parent_only_regatta_rows(
        [
            row for row in (regattas_hosted or [])
            if len(row) > 1 and str(row[1] or "").strip() in (regatta_ids_with_results or set())
        ]
    )
    regattas_without_results = _club_parent_only_regatta_rows(
        [
            row for row in (regattas_hosted or [])
            if len(row) > 1 and str(row[1] or "").strip()
            and str(row[1] or "").strip() not in (regatta_ids_with_results or set())
        ]
    )
    sailors_section_html = _club_sailors_table_section_html(sailors, ca)
    regattas_section_html = ""  # listed under Past Events / Regattas Hosted

    sas_calendar_html = ""
    other_events_html = ""
    unmatched_past_html = ""
    if table_exists("events"):
        try:
            if is_unassigned:
                evd = _events_cards_unassigned_only()
            else:
                evd = _get_upcoming_events(host_club_id=int(club_id))
            up = evd.get("upcoming") or []
            lv = evd.get("live") or []
            pa = evd.get("past") or []
            _club_page_match_past_calendar_to_hosted(
                regattas_hosted, evd, is_unassigned, regatta_ids_with_results
            )

            past_regattas = []
            other_events = []
            seen_past = set()
            seen_other = set()

            def _card_key(card: dict) -> str:
                rid = str(card.get("regatta_id") or "").strip().lower()
                if rid:
                    return "rid:" + rid
                rurl = str(card.get("result_url") or "").strip().lower()
                if rurl.startswith("/regatta/"):
                    return "rid:" + rurl.split("/regatta/", 1)[-1].strip("/")
                nm = str(card.get("display_title") or card.get("event_name") or "").strip().lower()
                dt = _club_card_date_cell(card.get("start_date_iso") or card.get("date_display") or "")
                return "nm:" + nm + "|" + dt

            # Remap fleet-child /regatta/ URLs → parent master for club list.
            _past_rids = [
                str(r[1]).strip()
                for r in (regattas_with_results or [])
                if len(r) > 1 and r[1]
            ] + [
                str(c.get("regatta_id") or "").strip()
                for c in (pa or [])
                if str(c.get("regatta_id") or "").strip()
            ]
            _child_to_parent = _club_fleet_child_parent_map(_past_rids)

            def _add_past(card: dict) -> None:
                c = dict(card)
                rid = str(c.get("regatta_id") or "").strip()
                rurl = str(c.get("result_url") or "").strip()
                if not rid and rurl.startswith("/regatta/"):
                    rid = rurl.split("/regatta/", 1)[-1].strip("/")
                if rid and rid in _child_to_parent:
                    # Fleet child — do not list separately on club page
                    return
                k = _card_key(c)
                if k in seen_past:
                    return
                seen_past.add(k)
                past_regattas.append(c)

            def _resolve_list_rid(rid: str) -> str:
                """Follow 301 / standalone redirects so live-* shells map to canonical."""
                r = str(rid or "").strip()
                if not r:
                    return ""
                tgt = _regatta_slug_redirect_target(r)
                if not tgt:
                    return r
                s = str(tgt).strip()
                if "/regatta/" in s:
                    s = s.split("/regatta/", 1)[-1]
                return s.strip("/").split("?")[0].strip() or r

            def _add_other(card: dict) -> None:
                c = dict(card)
                rid = str(c.get("regatta_id") or "").strip()
                rurl = str(c.get("result_url") or "").strip()
                if not rid and rurl.startswith("/regatta/"):
                    rid = rurl.split("/regatta/", 1)[-1].strip("/")
                resolved = _resolve_list_rid(rid)
                if resolved and resolved != rid:
                    c["regatta_id"] = resolved
                    rid = resolved
                # Dead shell / calendar twin of a Past results row → drop
                if rid and ("rid:" + rid.lower()) in seen_past:
                    return
                if rid and rid in (regatta_ids_with_results or set()):
                    return
                for past in past_regattas:
                    try:
                        if _club_cards_same_event(past, c):
                            return
                    except Exception:
                        pass
                k = _card_key(c)
                if k in seen_past or k in seen_other:
                    return
                # Also suppress when only the name/date key collides with a past results row
                for past in past_regattas:
                    pk = _card_key(past)
                    if pk.startswith("nm:") and k.startswith("nm:") and pk == k:
                        return
                seen_other.add(k)
                other_events.append(c)

            # Past Events / Regattas Hosted = one row per hosted regatta with results
            for row in regattas_with_results:
                _add_past(_club_hosted_tuple_to_event_card(row, with_results=True))

            # Calendar past: only if rid has rows in results → Past; else Other.
            # Never promote empty /regatta/ shells (live-*) into Past.
            # Resolve redirects first (live-* → canonical date slug).
            results_set = regatta_ids_with_results or set()
            for card in pa or []:
                c = dict(card)
                rid = str(c.get("regatta_id") or "").strip()
                rurl = str(c.get("result_url") or "").strip()
                if not rid and rurl.startswith("/regatta/"):
                    rid = rurl.split("/regatta/", 1)[-1].strip("/")
                    c["regatta_id"] = rid
                if not rid and str(c.get("details_url") or "").startswith("/regatta/"):
                    rid = str(c.get("details_url") or "").split("/regatta/", 1)[-1].strip("/")
                    c["regatta_id"] = rid
                resolved = _resolve_list_rid(rid)
                if resolved and resolved != rid:
                    rid = resolved
                    c["regatta_id"] = rid
                in_results = bool(rid) and rid in results_set
                if in_results:
                    c["result_url"] = ("/regatta/" + rid) if rid else rurl
                    c["result_yes"] = True
                    if str(c.get("details_url") or "").startswith("/regatta/"):
                        c["details_url"] = ""
                    _add_past(c)
                else:
                    c["result_url"] = ""
                    c["result_yes"] = False
                    if str(c.get("details_url") or "").startswith("/regatta/"):
                        c["details_url"] = ""
                    _add_other(c)

            # Hosted shells without results → Other (unless redirect target already in Past)
            for row in regattas_without_results:
                card = _club_hosted_tuple_to_event_card(row, with_results=False)
                rid = str(card.get("regatta_id") or "").strip()
                resolved = _resolve_list_rid(rid)
                if resolved and resolved in results_set:
                    continue  # superseded empty shell
                if resolved and resolved != rid:
                    card["regatta_id"] = resolved
                _add_other(card)

            past_regattas = _club_collapse_same_event_cards(past_regattas)
            other_events = _club_collapse_same_event_cards(other_events)
            past_regattas.sort(
                key=lambda c: _club_card_date_cell(c.get("start_date_iso") or c.get("date_display") or ""),
                reverse=True,
            )
            other_events.sort(
                key=lambda c: _club_card_date_cell(c.get("start_date_iso") or c.get("date_display") or ""),
                reverse=True,
            )
            if other_events:
                other_events_html = _club_other_events_table_html(other_events, ca)
            if up or lv or past_regattas:
                sas_calendar_html = _club_events_tables_html(up, lv, past_regattas, ca)
        except Exception as ex:
            print(f"[club page] events dashboard: {ex}")

    club_logo_html = _club_page_header_logo_html(ca, slug)
    club_story_html = _club_page_story_header_html(int(club_id), club_heading_html, club_logo_html, ca)
    body = (
        '<a href="/" class="back-to-home">← Back to Search</a>'
        f"{club_story_html}"
        f"{sas_calendar_html}"
        '<div class="club-content" style="margin:1.5rem 0;">'
        f"{sailors_section_html}"
        f"{other_events_html}"
        f"{regattas_section_html}"
        "</div>"
    )
    doc = (
        "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>"
        f"{club_heading_html} | SailingSA</title>"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        f"<meta name=\"description\" content=\"Sailing club: {html_module.escape(cn or ca or 'Club')}. Sailors and regattas.\">"
        f"<link rel=\"canonical\" href=\"{html_module.escape(canonical_url)}\">"
        "<link rel=\"icon\" href=\"/favicon.ico\" sizes=\"any\"><link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"48x48\" href=\"/favicon-48.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/favicon-192.png\"><link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">"
        "<link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/favicon-192.png\">"
        f"<script type=\"application/ld+json\">{json.dumps(json_ld)}</script>"
        "<link rel=\"stylesheet\" href=\"/css/main.css?v=13\">\n"
        f"<style>body{{font-family:-apple-system,'system-ui','Segoe UI',Roboto,Oxygen,Ubuntu,Cantarell,sans-serif;margin:2rem;color:#1a2750;}}a{{color:#1a2750;}}{_CLUB_PAGE_CSS}{_CLUB_TABLES_CSS}</style></head><body>"
        f"<div class=\"club-page\">{body}</div>{_seo_discovery_block_html()}<script>{_CLUB_TABLES_SORT_JS}</script></body></html>"
    )
    return HTMLResponse(doc)


def _format_regatta_host_display(abbrev: str, fullname: str, legacy_coalesce: str) -> str:
    """Standalone regatta header: Host: CODE - Full club name when both exist; else abbrev, full name, or legacy COALESCE."""
    a = (abbrev or "").strip()
    f = (fullname or "").strip()
    leg = (legacy_coalesce or "").strip()
    if a and f:
        if a.lower() == f.lower():
            return f or a
        return f"{a} - {f}"
    if a:
        return a
    if f:
        return f
    return leg




def _resolve_regatta_status_as_at_time(
    regatta_id,
    end_date,
    start_date,
    as_at_time,
    cur=None,
    _db_q=None,
):
    """Snapshot time ladder: keep recorded as_at; else matched calendar event last day @ 17:45; else regatta end/start."""
    if as_at_time:
        return as_at_time
    from datetime import datetime as _dt

    day = None
    if regatta_id:
        try:
            if cur is not None and table_exists("events"):
                cur.execute(
                    """
                    SELECT COALESCE(e.end_date, e.start_date) AS d
                    FROM event_regatta_links l
                    JOIN events e ON e.event_id = l.event_id
                    WHERE l.regatta_id = %s
                      AND COALESCE(e.end_date, e.start_date) IS NOT NULL
                    ORDER BY l.match_score DESC NULLS LAST, e.event_id
                    LIMIT 1
                    """,
                    (regatta_id,),
                )
                er = cur.fetchone()
                if er and er.get("d") is not None:
                    day = er.get("d")
                if day is None:
                    cur.execute(
                        """
                        SELECT COALESCE(e.end_date, e.start_date) AS d
                        FROM events e
                        WHERE e.regatta_id = %s
                        ORDER BY e.event_id
                        LIMIT 1
                        """,
                        (regatta_id,),
                    )
                    er = cur.fetchone()
                    if er and er.get("d") is not None:
                        day = er.get("d")
            elif _db_q is not None and table_exists("events"):
                rows = _db_q(
                    """
                    SELECT COALESCE(end_date, start_date) AS d
                    FROM events
                    WHERE regatta_id::text = %s
                    ORDER BY event_id
                    LIMIT 1
                    """,
                    (regatta_id,),
                )
                if rows and rows[0].get("d") is not None:
                    day = rows[0]["d"]
        except Exception:
            pass
    if day is None:
        day = end_date or start_date
    if day is None:
        return None
    try:
        if hasattr(day, "year"):
            d = day
        else:
            d = _dt.strptime(str(day)[:10], "%Y-%m-%d").date()
        return _dt(d.year, d.month, d.day, 17, 45)
    except Exception:
        return None

def _wc_regatta_source_banner_html(regatta_id: str, *, position: str | None = None) -> str:
    """Linked stamp/banner when banner_image is set in wc_regatta_header_icons.json.

    Looks up slug, then parent master (strip -gold-fleet / -silver-fleet / … tails).
    position: "top" or "bottom" filters JSON banner_position (default top).
    """
    try:
        icons = _read_wc_regatta_header_icons()
        rid = str(regatta_id).strip()
        raw = icons.get(rid) or {}
        if not (raw.get("banner_image") or raw.get("source_banner_image")):
            for tail in (
                "-gold-fleet", "-silver-fleet", "-bronze-fleet",
                "-overall", "-df95", "-hobie-16",
            ):
                if rid.endswith(tail):
                    raw = icons.get(rid[: -len(tail)]) or {}
                    break
        img = (raw.get("banner_image") or raw.get("source_banner_image") or "").strip()
        if not img:
            return ""
        want = (raw.get("banner_position") or "top").strip().lower()
        if want not in ("top", "bottom"):
            want = "top"
        if position is not None and want != position:
            return ""
        href = (raw.get("banner_href") or raw.get("source_banner_href") or "").strip()
        img_esc = html_module.escape(img, quote=True)
        alt = html_module.escape(
            (raw.get("banner_alt") or "Original result document — partially illegible").strip(),
            quote=True,
        )
        img_tag = (
            f'<img class="regatta-source-banner-img" src="{img_esc}" '
            f'alt="{alt}" loading="lazy">'
        )
        if href:
            href_esc = html_module.escape(href, quote=True)
            inner = (
                f'<a class="regatta-source-banner-link" href="{href_esc}" '
                f'target="_blank" rel="noopener noreferrer">{img_tag}</a>'
            )
        else:
            inner = img_tag
        return f'<div class="regatta-source-banner regatta-source-banner--{want}">{inner}</div>'
    except Exception:
        return ""


def _regatta_pdf_status_line_override(regatta_id: str):
    """Return status_line from wc_regatta_header_icons.json when set."""
    try:
        raw = _read_wc_regatta_header_icons().get(str(regatta_id).strip()) or {}
        sl = raw.get("status_line") or raw.get("status_line_text")
        if sl and str(sl).strip():
            return str(sl).strip()
    except Exception:
        pass
    return None

def _format_regatta_status_line(status_word: str, as_at_time) -> str:
    """Format status line per RESULTS_HTML_STATUS_LINE_RULE. as_at_time from API (results table then regattas). No datetime.now/start_date.
    If as_at_time exists and is formattable: 'Results are <Status> as at DD Month YYYY at HH:MM'.
    If as_at_time is NULL or invalid: 'Results are <Status> (snapshot time not recorded)'.
    Upstream: _resolve_regatta_status_as_at_time uses matched event end_date @ 17:45 when no snapshot."""
    word = (status_word or "Final").strip() or "Final"
    escaped_word = html_module.escape(word)
    if not as_at_time:
        return f"Results are {escaped_word} (snapshot time not recorded)"
    if hasattr(as_at_time, "strftime"):
        status_date = as_at_time.strftime("%d %B %Y at %H:%M")
        return f"Results are {escaped_word} as at {html_module.escape(status_date)}"
    if isinstance(as_at_time, str) and as_at_time.strip():
        try:
            from datetime import datetime as _dt
            s = as_at_time.strip()
            s2 = s[:19].replace("Z", "").replace("+00:00", "").strip()
            if "T" in s2:
                t = _dt.strptime(s2, "%Y-%m-%dT%H:%M:%S")
            elif len(s2) >= 16 and (" " in s2 or "-" in s2):
                t = _dt.strptime(s2[:16], "%Y-%m-%d %H:%M")
            else:
                t = _dt.strptime(s[:10], "%Y-%m-%d")
            status_date = t.strftime("%d %B %Y at %H:%M")
            return f"Results are {escaped_word} as at {html_module.escape(status_date)}"
        except Exception:
            pass
    return f"Results are {escaped_word} (snapshot time not recorded)"


def _resolve_class_slug_to_class_id(class_slug: str):
    """Resolve URL class_slug to (class_id, class_name). Handles name-only (420, ilca-6) and id-slug (7-420). Returns (None, None) if invalid."""
    if not class_slug or not isinstance(class_slug, str):
        return (None, None)
    s = class_slug.strip()
    if re.match(r"^\d+-", s):
        try:
            cid = int(s.split("-")[0])
            name = _get_class_name_by_id(cid)
            return (cid, name) if name else (None, None)
        except (ValueError, TypeError):
            return (None, None)
    class_id, class_name = _get_class_by_name_slug(s)
    return (class_id, class_name)


@app.get("/api/class/resolve-slug/{slug}")
def api_class_resolve_slug(slug: str):
    """Resolve name-only slug (e.g. dabchick) or id-slug segment to canonical path for SPA when nginx serves static index."""
    if not slug or not str(slug).strip():
        raise HTTPException(status_code=404, detail="Class not found")
    class_id, class_name = _resolve_class_slug_to_class_id(slug.strip())
    if not class_id:
        raise HTTPException(status_code=404, detail="Class not found")
    canon = _class_canonical_slug(class_name or "")
    canonical_path = f"/class/{class_id}-{canon}" if canon else f"/class/{class_id}"
    return {"class_id": int(class_id), "canonical_path": canonical_path}


def _get_regatta_class_page_data(regatta_id: str, class_id: int):
    """Return (event_name, host_club_name, start_date, end_date, [one_fleet], result_status, as_at_time, host_club_province, host_club_abbrev, host_club_fullname) for single-class regatta page, or None."""
    if not regatta_id or class_id is None or not table_exists("regattas") or not table_exists("regatta_blocks") or not table_exists("results"):
        return None
    raw = []
    crew_by_result = {}
    try:
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT r.event_name, r.start_date, r.end_date,
                       COALESCE(c.club_abbrev, c.club_fullname, '') AS host_club_name,
                       TRIM(COALESCE(c.club_abbrev, '')) AS host_club_abbrev,
                       TRIM(COALESCE(c.club_fullname, '')) AS host_club_fullname,
                       c.province AS host_club_province,
                       r.result_status, r.as_at_time
                FROM regattas r
                LEFT JOIN clubs c ON c.club_id = r.host_club_id
                WHERE r.regatta_id = %s
            """, (regatta_id,))
            row = cur.fetchone()
            if not row:
                return None
            event_name = (row.get("event_name") or "").strip()
            host_club_name = (row.get("host_club_name") or "").strip()
            host_club_abbrev = (row.get("host_club_abbrev") or "").strip()
            host_club_fullname = (row.get("host_club_fullname") or "").strip()
            host_club_province = (row.get("host_club_province") or "").strip() or None
            start_date = row.get("start_date")
            end_date = row.get("end_date")
            result_status = (row.get("result_status") or "").strip() or "Final"
            as_at_time = row.get("as_at_time")
            cur.execute("""
                SELECT as_at_time FROM results
                WHERE regatta_id = %s AND as_at_time IS NOT NULL
                ORDER BY result_id LIMIT 1
            """, (regatta_id,))
            res_row = cur.fetchone()
            if res_row and res_row.get("as_at_time"):
                as_at_time = res_row["as_at_time"]
            as_at_time = _resolve_regatta_status_as_at_time(
                regatta_id, end_date, start_date, as_at_time, cur=cur
            )
            cur.execute("""
                SELECT rb.block_id,
                       COALESCE(TRIM(rb.fleet_label), TRIM(rb.class_canonical), TRIM(rb.class_original), 'Fleet') AS fleet_name,
                       rb.fleet_label, rb.class_canonical,
                       rb.races_sailed, rb.discard_count, rb.to_count, rb.scoring_system, rb.rating_system,
                       rb.race_column_labels,
                       res.result_id,
                       res.rank, res.sail_number, res.helm_name, res.crew_name,
                       res.boat_name, res.jib_no, res.bow_no, res.hull_no,
                res.hull_colour,
                       COALESCE(TRIM(c.club_abbrev), TRIM(res.club_raw), '') AS club,
                       res.club_id, COALESCE(c.club_abbrev, c.club_fullname) AS club_fullname,
                       res.helm_sa_sailing_id, res.crew_sa_sailing_id,
                       res.total_points_raw, res.nett_points_raw, res.race_scores, res.raced,
                       res.start_time, res.finish_time, res.duration_time, res.corrected_time, res.delta_time,
                       res.handicap, res.aph, res.race_distance_nm, res.course_data,
                       COALESCE(TRIM(c_res.class_name), TRIM(res.class_original), '') AS class_name,
                       COALESCE(res.class_id, rb.class_id) AS result_class_id
                FROM regatta_blocks rb
                JOIN results res ON res.block_id = rb.block_id AND res.regatta_id = rb.regatta_id
                LEFT JOIN clubs c ON c.club_id = res.club_id
                LEFT JOIN classes c_res ON c_res.class_id = COALESCE(res.class_id, rb.class_id)
                WHERE rb.regatta_id = %s AND (COALESCE(res.class_id, rb.class_id) = %s)
                ORDER BY rb.block_id, COALESCE(res.rank, 99999), res.result_id
            """, (regatta_id, class_id))
            raw = cur.fetchall() or []
            if not raw:
                return None
            dup_names = set()
            cur.execute("""
                SELECT LOWER(TRIM(COALESCE(full_name, first_name || ' ' || COALESCE(last_name, '')))) AS n
                FROM sas_id_personal WHERE full_name IS NOT NULL OR first_name IS NOT NULL
                GROUP BY LOWER(TRIM(COALESCE(full_name, first_name || ' ' || COALESCE(last_name, ''))))
                HAVING COUNT(*) > 1
            """)
            for r in cur.fetchall() or []:
                if r.get("n"):
                    dup_names.add(r["n"])
            sas_ids = set()
            for r in raw:
                h, c = r.get("helm_sa_sailing_id"), r.get("crew_sa_sailing_id")
                if h is not None and str(h).strip().isdigit():
                    sas_ids.add(str(h).strip())
                if c is not None and str(c).strip().isdigit():
                    sas_ids.add(str(c).strip())
            name_map = {}
            slug_map = {}
            if sas_ids:
                cur.execute("""
                    SELECT sa_sailing_id::text AS sas_id,
                           COALESCE(TRIM(full_name), TRIM(first_name || ' ' || COALESCE(last_name, ''))) AS full_name
                    FROM sas_id_personal
                    WHERE sa_sailing_id::text = ANY(%s)
                """, (list(sas_ids),))
                for r in cur.fetchall() or []:
                    sid = str(r.get("sas_id") or "")
                    name_map[sid] = (r.get("full_name") or "").strip()
                for sid, nm in name_map.items():
                    has_dup = (nm.lower() in dup_names) if nm else False
                    slug_map[sid] = _sailor_canonical_slug(nm, sid, has_dup) if nm else None
            result_ids = [x.get("result_id") for x in raw if x.get("result_id") is not None]
            crew_by_result = _get_crew_for_results(conn, result_ids) if (result_ids and table_exists("result_crew")) else {}
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[regatta class] _get_regatta_class_page_data: {e}")
        return None
    by_block = {}
    for r in raw:
        bid = r.get("block_id")
        rs = r.get("race_scores")
        if isinstance(rs, str) and rs:
            try:
                rs = json.loads(rs)
            except Exception:
                rs = {}
        if not isinstance(rs, dict):
            rs = {}
        if bid not in by_block:
            class_name_for_slug = (r.get("class_name") or "").strip()
            if _regatta_slug_is_sa_pilot_standalone(str(regatta_id).strip()):
                class_name_for_slug = _wc_dinghy_table_label_open_a_to_open(class_name_for_slug)
            class_slug_one = _class_canonical_slug(class_name_for_slug) if class_name_for_slug else ""
            _fleet_nm_one = (r.get("fleet_name") or "Fleet").strip()
            _fl_combine_one = (r.get("fleet_label") or r.get("class_canonical") or "").strip()
            _fleet_lb_one = _fl_combine_one
            if _regatta_slug_is_sa_pilot_standalone(str(regatta_id).strip()):
                _fleet_nm_one = _wc_dinghy_fleet_title_display(_fleet_nm_one)
                _fleet_lb_one = _wc_dinghy_fleet_title_display(_fleet_lb_one)
                _fleet_lb_cell_one = _wc_dinghy_fleet_column_cell_display(
                    _wc_dinghy_fleet_title_display(_fl_combine_one)
                )
            else:
                _fleet_lb_cell_one = _fleet_lb_one
            by_block[bid] = {
                "block_id": bid,
                "name": _fleet_nm_one,
                "fleet_label": _fleet_lb_one,
                "fleet_label_cell": _fleet_lb_cell_one,
                "races_sailed": r.get("races_sailed"),
                "discard_count": r.get("discard_count"),
                "to_count": r.get("to_count"),
                "scoring_system": r.get("scoring_system") or "Appendix A",
                "rating_system": r.get("rating_system"),
                "race_column_labels": r.get("race_column_labels"),
                "rows": [],
                "regatta_id": regatta_id,
                "class_slug": class_slug_one,
            }
        club_fn = (r.get("club_abbrev") or r.get("club_fullname") or "").strip()
        club_slug = _club_slug_from_name(club_fn or r.get("club") or "") if (r.get("club_id") and (club_fn or r.get("club"))) else None
        helm_name = r.get("helm_name")
        helm_sas_id = str(r.get("helm_sa_sailing_id") or "") if r.get("helm_sa_sailing_id") is not None else ""
        helm_slug = slug_map.get(helm_sas_id) if (helm_sas_id and helm_sas_id.isdigit()) else None
        crew_name = r.get("crew_name")
        crew_sas_id = str(r.get("crew_sa_sailing_id") or "") if r.get("crew_sa_sailing_id") is not None else ""
        crew_slug = slug_map.get(crew_sas_id) if (crew_sas_id and crew_sas_id.isdigit()) else None
        if not helm_slug and _result_row_identity_pending_helm(r):
            helm_slug = _identity_pending_name_slug(helm_name)
        if not crew_slug and _result_row_identity_pending_crew(r):
            crew_slug = _identity_pending_name_slug(crew_name)
        by_block[bid]["rows"].append({
            "result_id": r.get("result_id"),
            "rank": r.get("rank"),
            "sail_number": r.get("sail_number"),
            "helm_name": helm_name,
            "helm_slug": helm_slug,
            "helm_sa_sailing_id": r.get("helm_sa_sailing_id"),
            "helm_profile_from_name_only": bool(helm_slug and r.get("helm_sa_sailing_id") is None),
            "crew_name": crew_name,
            "crew_slug": crew_slug,
            "crew_sa_sailing_id": r.get("crew_sa_sailing_id"),
            "crew_profile_from_name_only": bool(crew_slug and r.get("crew_sa_sailing_id") is None),
            "crew_list": crew_by_result.get(r.get("result_id"), []),
            "boat_name": r.get("boat_name"),
            "jib_no": r.get("jib_no"),
            "bow_no": r.get("bow_no"),
            "hull_no": r.get("hull_no"),
            "hull_colour": r.get("hull_colour"),
            "club": r.get("club") or r.get("club_abbrev") or r.get("club_raw"),
            "club_id": r.get("club_id"),
            "club_slug": club_slug,
            "total": r.get("total_points_raw"),
            "nett": r.get("nett_points_raw"),
            "race_scores": rs,
            "raced": r.get("raced"),
            "class_name": (
                "ILCA 4"
                if (
                    str(regatta_id).strip() == "2026-02-16-hyc-cape-classic"
                    and (r.get("fleet_label") or "").strip() == "ILCA 4"
                    and (r.get("class_name") or "").strip().casefold() in {"ilca 4.7", "ilca 4"}
                )
                else _wc_dinghy_table_label_open_a_to_open((r.get("class_name") or "").strip())
                if _regatta_slug_is_sa_pilot_standalone(str(regatta_id).strip())
                else (r.get("class_name") or "").strip()
            ),
            "start_time": r.get("start_time"),
            "finish_time": r.get("finish_time"),
            "duration_time": r.get("duration_time"),
            "corrected_time": r.get("corrected_time"),
            "delta_time": r.get("delta_time"),
            "handicap": r.get("handicap"),
            "aph": r.get("aph"),
            "race_distance_nm": r.get("race_distance_nm"),
            "course_data": r.get("course_data"),
            "result_class_id": r.get("result_class_id"),
            "match_status_class": r.get("match_status_class"),
            "class_catalogue_matched": r.get("result_class_id") is not None,
        })
    fleets = []
    for bid in sorted(by_block.keys(), key=lambda b: _regatta_fleets_sort_key(by_block, b)):
        bl = by_block[bid]
        bl["entries"] = len(bl["rows"])
        fleets.append(bl)
    return (
        event_name,
        host_club_name,
        start_date,
        end_date,
        fleets,
        result_status,
        as_at_time,
        host_club_province,
        host_club_abbrev,
        host_club_fullname,
    )


def serve_regatta_class_standalone(slug: str, class_slug: str, request: Request):
    """Serve class-filtered ladder at /regatta/{slug}/class-{class_slug}.

    Multi-fleet umbrellas (Fast+Slow, etc.): sub-URLs are **fleet_shell** `…-{fleet_tail}`, not class — see PROCESS /
    redirect to fleet_shell when the slice is one fleet block."""
    reg = _get_regatta_by_slug(slug)
    if not reg:
        return RedirectResponse(url="/events", status_code=301)
    regatta_id = reg[0]
    if _regatta_block_count(str(regatta_id).strip()) <= 1 and _single_fleet_is_mixed_or_overall(str(regatta_id).strip()):
        rid_m = quote(str(regatta_id).strip(), safe="")
        return RedirectResponse(url=f"/regatta/{rid_m}", status_code=301)
    cid, class_name = _resolve_class_slug_to_class_id(class_slug.strip())
    if not cid or not class_name:
        return RedirectResponse(url="/events", status_code=301)
    canonical_class_slug = _class_canonical_slug(class_name)
    if str(slug).strip() != str(regatta_id):
        tail = canonical_class_slug if canonical_class_slug else class_slug.strip()
        return RedirectResponse(url=f"/regatta/{regatta_id}/class-{tail}", status_code=301)
    if canonical_class_slug and class_slug.strip().lower() != canonical_class_slug.lower():
        return RedirectResponse(url=f"/regatta/{regatta_id}/class-{canonical_class_slug}", status_code=301)
    data = _get_regatta_class_page_data(regatta_id, cid)
    if not data:
        return RedirectResponse(url="/events", status_code=301)
    if len(data) >= 10:
        ev_name, host_club_name, start_d, end_d, fleets, result_status, as_at_time, host_club_province, host_club_abbrev, host_club_fullname = data[:10]
    else:
        ev_name, host_club_name, start_d, end_d, fleets, result_status, as_at_time, host_club_province = data[:8]
        host_club_abbrev, host_club_fullname = "", ""
    if len(fleets) != 1:
        return RedirectResponse(url="/events", status_code=301)
    # Multi-fleet championship: a /class-* slice that falls entirely in one block must use fleet_shell (PDF fleet ladder).
    _solo_bid = str((fleets[0] or {}).get("block_id") or "")
    if ":" in _solo_bid and _regatta_has_sibling_block(regatta_id, _solo_bid):
        _tail = _solo_bid.split(":", 1)[1]
        _dest = f"/regatta/{quote(str(regatta_id).strip(), safe='')}-{quote(_tail, safe='')}"
        return RedirectResponse(url=_dest, status_code=301)
    try:
        event_name = ev_name or reg[1]
        base_url = _canonical_base_url()
        canonical_url = f"{base_url}/regatta/{regatta_id}/class-{_class_canonical_slug(class_name)}"
        escaped_title = html_module.escape(event_name or "")
        status_word = (result_status or "Final").strip() or "Final"
        status_line_text = _format_regatta_status_line(status_word, as_at_time)
        host_club_id = reg[5] if len(reg) > 5 else None
        host_club_slug = _get_club_slug_by_id(host_club_id) if host_club_id else None
        host_club_text = _format_regatta_host_display(host_club_abbrev, host_club_fullname, host_club_name or "")
        host_club_html = f'<a href="/club/{html_module.escape(host_club_slug)}">{html_module.escape(host_club_text)}</a>' if host_club_slug and host_club_text else html_module.escape(host_club_text)
        use_wc_cols = _regatta_slug_is_sa_pilot_standalone(str(regatta_id))
        is_sa = _session_role_is_super_admin(request)
        hub_badge = _effective_regatta_hub_toolbar_badge_label(str(regatta_id)) if is_sa else None
        back_link = f'<a href="/regatta/{html_module.escape(regatta_id)}" class="back-to-home">← Back to full regatta</a>'
        if is_sa:
            back_block = (
                '<div class="regatta-back-row">'
                + back_link
                + _wc_super_admin_regatta_toolbar_html(str(regatta_id), hub_badge)
                + "</div>"
            )
        else:
            back_block = back_link
        _lu, _ru = _wc_regatta_header_icon_urls(str(regatta_id), event_name)
        _left_logo_col = _regatta_standalone_left_logo_column_html(_lu)
        _host_code_logo = _regatta_host_club_code_resolved(
            host_club_abbrev, (host_club_name or ""), str(regatta_id)
        )
        if not _ru and _host_code_logo:
            _ensure_club_logo_cached(_host_code_logo, host_club_slug)
        _right_logo_col = _regatta_standalone_right_logo_column_html(
            _host_code_logo or host_club_abbrev, host_club_slug, _ru
        )
        header_html = (
            '<div class="regatta-header-wrap">'
            + back_block
            + '<div class="header">'
            + _left_logo_col
            + '<div class="regatta-header-main-col">'
            f'<div class="regatta-name">{escaped_title}</div>'
            f'<div class="host-club">Host: {host_club_html}</div>'
            f'<div class="status-line">{status_line_text}</div>'
            + "</div>"
            + _right_logo_col
            + "</div></div>"
        )

        def _iso_date(d):
            if d is None:
                return None
            if hasattr(d, "strftime"):
                return d.strftime("%Y-%m-%d")
            return str(d)[:10] if str(d) else None

        start_iso = _iso_date(start_d)
        json_ld = {
            "@context": "https://schema.org",
            "@type": "SportsEvent",
            "name": event_name or "",
            "sport": "Sailing",
            "eventStatus": "https://schema.org/EventScheduled",
            "eventAttendanceMode": "https://schema.org/OfflineEventAttendanceMode",
        }
        if start_iso:
            json_ld["startDate"] = start_iso
        end_iso = _iso_date(end_d)
        if end_iso:
            json_ld["endDate"] = end_iso
        if event_name:
            json_ld["description"] = event_name
        if host_club_text:
            json_ld["organizer"] = {"@type": "Organization", "name": host_club_text}
        wc_prefs = _merge_wc_column_prefs_for_regatta(str(regatta_id)) if use_wc_cols else None
        _show_fleet_hdr_logos = _wc_regatta_show_fleet_header_logos(str(regatta_id)) if use_wc_cols else True
        sa_columns_frag = ""
        if use_wc_cols and is_sa:
            sa_columns_frag = _wc_regatta_sa_columns_panel_html(str(regatta_id), wc_prefs)
        first_wc_bid = str((fleets[0] if fleets else {}).get("block_id") or "")
        late_ext_html = ""
        fleet_section_parts: List[str] = []
        for f in fleets:
            sec, lx = _render_result_sheet_fleet(
                f,
                standalone_class_page=True,
                column_prefs=wc_prefs if use_wc_cols else None,
                wc_sa_fleet_edit=bool(use_wc_cols and is_sa),
                show_fleet_header_logos=_show_fleet_hdr_logos,
                wc_show_late_entry_strip=(
                    bool(use_wc_cols and is_sa)
                    and str((f or {}).get("block_id") or "") == first_wc_bid
                ),
                wc_late_strip_external=(
                    bool(use_wc_cols and is_sa)
                    and str((f or {}).get("block_id") or "") == first_wc_bid
                ),
            )
            fleet_section_parts.append(sec)
            if lx:
                late_ext_html = lx
        fleet_picker_frag = ""
        if use_wc_cols and is_sa:
            fleet_picker_frag = _wc_regatta_fleet_picker_fragment(str(regatta_id))
        print_btn = '<div class="action-buttons"><button class="action-button" onclick="window.print()">Print</button></div>'
        if use_wc_cols and is_sa:
            fleet_wrapped = (
                f'<div class="wc-dinghy-champs-results-root" id="wcDinghyChampsResultsRoot">'
                f"{late_ext_html}\n"
                + "\n".join(fleet_section_parts)
                + "</div>"
            )
        else:
            fleet_wrapped = "\n".join(fleet_section_parts)
        banner_top = _wc_regatta_source_banner_html(str(regatta_id), position="top")
        banner_bottom = _wc_regatta_source_banner_html(str(regatta_id), position="bottom")
        body_html = header_html + banner_top + sa_columns_frag + fleet_picker_frag + fleet_wrapped + "\n" + banner_bottom + print_btn
        seo_sailors = ""
        seo_disc = _seo_discovery_block_html()
        wc_club_edit_script_c = (
            (_wc_standalone_fleet_edit_script_html() + _wc_standalone_fleet_autocomplete_script_html())
            if _regatta_slug_is_sa_pilot_standalone(str(regatta_id)) and is_sa
            else ""
        )
        sa_toolbar_script_c = (
            '<script src="/js/regatta-sa-toolbar.js?v=20260723sa0" defer></script><script src="/js/regatta-fleet-ops.js?v=20260723f2" defer></script>' if is_sa else ""
        )
        doc = (
            "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>"
            f"{html_module.escape(class_name)} – {escaped_title} | SailingSA</title>"
            f"<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
            f"<link rel=\"canonical\" href=\"{html_module.escape(canonical_url)}\">"
            "<link rel=\"icon\" href=\"/favicon.ico\" sizes=\"any\"><link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"48x48\" href=\"/favicon-48.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/favicon-192.png\"><link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">"
            "<link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/favicon-192.png\">"
            f"<script type=\"application/ld+json\">{json.dumps(json_ld)}</script>"
            f"<style>{_RESULT_SHEET_CSS}</style></head><body>"
            f"<div class=\"regatta-page\">{body_html}</div>{seo_sailors}{seo_disc}{sa_toolbar_script_c}{wc_club_edit_script_c}"
            '<footer class="site-footer-about" style="text-align:center;padding:2rem 1rem;font-size:0.9rem;color:#666;border-top:1px solid #e0e0e0;margin-top:2rem;">SailingSA – South African Sailing Results Database © <span id="year-sa-footer-class"></span></footer>'
            "<script>document.getElementById('year-sa-footer-class').textContent=new Date().getFullYear();</script>"
            "</body></html>"
        )
        return HTMLResponse(doc)
    except Exception as e:
        print(f"[serve_regatta_class_standalone] {e}", flush=True)
        return HTMLResponse(content=_HTML_SOFT_FAIL_200, status_code=200, media_type="text/html")




def _merge_gimco_2026_hub_fleets(regatta_id: str, data):
    """2026-02-01-rcyc-gimco: keep master A/B/C fleets; append Inter Academy + Cape 31 child shells.

    Child regatta rows hold fleet blocks merged onto the master URL (single combined results page).
    Do not pull legacy 385/384 shells or duplicate 405-409 auto-stubs here.
    """
    if str(regatta_id).strip() != "2026-02-01-rcyc-gimco" or not data:
        return data
    base_fleets = list(data[4] or [])
    child_regatta_ids = (
        "2026-02-01-rcyc-gimco-inter-academy",
        "382-2026-rcyc-gimco-cape-31",
    )
    merged_fleets = list(base_fleets)
    statuses = [(data[5] or "").strip() if len(data) > 5 else ""]
    as_at_vals = []
    if len(data) > 6 and data[6] is not None:
        as_at_vals.append(data[6])
    for child_id in child_regatta_ids:
        child = _get_regatta_full_page_data(child_id)
        if child and len(child) >= 7 and (child[4] or []):
            merged_fleets.extend(child[4] or [])
            statuses.append((child[5] or "").strip())
            if len(child) > 6 and child[6] is not None:
                as_at_vals.append(child[6])
    if len(merged_fleets) == len(base_fleets):
        return data
    merged_status = (data[5] or "").strip() if len(data) > 5 else ""
    if any("provisional" in (s or "").lower() for s in statuses if s):
        merged_status = "Provisional"
    elif not merged_status and statuses:
        merged_status = (statuses[0] or "Final").strip() or "Final"
    merged_as_at = data[6] if len(data) > 6 else None
    if as_at_vals:
        try:
            merged_as_at = max(as_at_vals)
        except Exception:
            merged_as_at = as_at_vals[-1]
    lst = list(data)
    lst[4] = merged_fleets
    if len(lst) > 5:
        lst[5] = merged_status or "Final"
    if len(lst) > 6:
        lst[6] = merged_as_at
    return tuple(lst)




PORT_OWEN_DINGHY_SHELL = "2026-01-01-port-owen-river-race-dinghy-fleet"
PORT_OWEN_MIRROR_BLOCK = "2026-01-01-port-owen-river-race:mirror-fleet"


def _merge_port_owen_dinghy_shell_fleets(
    requested_slug: str,
    regatta_id: str,
    only_block_id: Optional[str],
    data,
):
    """dinghy-fleet public slug: append Mirror block after Dinghy (original PDF layout)."""
    if (
        str(requested_slug or "").strip() != PORT_OWEN_DINGHY_SHELL
        or str(regatta_id or "").strip() != "2026-01-01-port-owen-river-race"
        or not data
        or not only_block_id
    ):
        return data
    base_fleets = list(data[4] or [])
    full = _get_regatta_full_page_data(regatta_id)
    if not full or len(full) < 7:
        return data
    mirror_fleets = [
        f for f in (full[4] or [])
        if str((f or {}).get("block_id") or "").strip() == PORT_OWEN_MIRROR_BLOCK
    ]
    if not mirror_fleets:
        return data
    if any(
        str((f or {}).get("block_id") or "").strip() == PORT_OWEN_MIRROR_BLOCK
        for f in base_fleets
    ):
        return data
    lst = list(data)
    lst[4] = base_fleets + mirror_fleets
    return tuple(lst)





def _merge_hyc_cape_classic_2025_hub_fleets(regatta_id: str, data):
    """2025-02-16-hyc-cape-classic: append fleet-child blocks onto empty parent hub URL."""
    rid = str(regatta_id).strip()
    if rid != "2025-02-16-hyc-cape-classic":
        return data
    children = ('2025-02-16-hyc-cape-classic-sonnet', '2025-02-16-hyc-cape-classic-optimist', '2025-02-16-hyc-cape-classic-optimist-b', '2025-02-16-hyc-cape-classic-mirror', '2025-02-16-hyc-cape-classic-ilca-7', '2025-02-16-hyc-cape-classic-ilca-6', '2025-02-16-hyc-cape-classic-ilca-4-16', '2025-02-16-hyc-cape-classic-dabchick', '2025-02-16-hyc-cape-classic-hobie-16')
    if not data:
        for child_id in children:
            child = _get_regatta_full_page_data(child_id)
            if child and len(child) >= 7:
                lst = list(child)
                lst[0] = "2025 HYC Cape Classic"
                data = tuple(lst)
                break
        if not data:
            return data
    base_fleets = list(data[4] or [])
    merged_fleets = list(base_fleets)
    statuses = [(data[5] or "").strip() if len(data) > 5 else ""]
    as_at_vals = []
    if len(data) > 6 and data[6] is not None:
        as_at_vals.append(data[6])
    seen_labels = {
        str((b or {}).get("block_label_raw") or (b or {}).get("fleet_label") or "").strip().lower()
        for b in merged_fleets
    }
    for child_id in children:
        child = _get_regatta_full_page_data(child_id)
        if child and len(child) >= 7 and (child[4] or []):
            for band in (child[4] or []):
                blk = dict(band)
                lab = str(blk.get("block_label_raw") or blk.get("fleet_label") or "").strip().lower()
                if lab and lab in seen_labels:
                    continue
                if lab:
                    seen_labels.add(lab)
                blk["fleet_shell_href"] = f"/regatta/{child_id}"
                merged_fleets.append(blk)
            statuses.append((child[5] or "").strip())
            if len(child) > 6 and child[6] is not None:
                as_at_vals.append(child[6])
    if len(merged_fleets) == len(base_fleets) and base_fleets:
        return data
    if not merged_fleets:
        return data
    merged_status = (data[5] or "").strip() if len(data) > 5 else ""
    if any("provisional" in (s or "").lower() for s in statuses if s):
        merged_status = "Provisional"
    elif not merged_status and statuses:
        merged_status = (statuses[0] or "Final").strip() or "Final"
    merged_as_at = data[6] if len(data) > 6 else None
    if as_at_vals:
        try:
            merged_as_at = max(as_at_vals)
        except Exception:
            merged_as_at = as_at_vals[-1]
    lst = list(data)
    lst[0] = "2025 HYC Cape Classic"
    lst[4] = merged_fleets
    if len(lst) > 5:
        lst[5] = merged_status or "Final"
    if len(lst) > 6:
        lst[6] = merged_as_at
    return tuple(lst)


