def _regatta_not_found_response(slug: str = "") -> HTMLResponse:
    """Unknown/broken regatta slug — 404, never cache a redirect to /events."""
    hint = f" ({html_module.escape(str(slug).strip())})" if str(slug).strip() else ""
    body = (
        "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>Regatta not found | SailingSA</title>"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        "<meta name=\"robots\" content=\"noindex\">"
        "<style>body{font-family:-apple-system,'system-ui','Segoe UI',Roboto,Oxygen,Ubuntu,Cantarell,sans-serif;padding:2rem;max-width:560px;margin:0 auto;color:#1a2750;background:#fff}"
        "a{color:#0b2c4d;font-weight:600}</style></head><body>"
        "<h1>Regatta not found</h1>"
        "<p>No public results page exists for this URL" + hint + ".</p>"
        "<p><a href=\"/regattas\">Browse regattas</a> · <a href=\"/\">Home</a></p>"
        "</body></html>"
    )
    return HTMLResponse(
        content=body,
        status_code=404,
        headers={"Cache-Control": "no-store, no-cache, must-revalidate, max-age=0"},
    )


