def _age_category_podium_sort_key(row: dict):
    """Within category: best fleet rank first, then nett, then sail."""
    try:
        rk = int(row.get("rank") or 10**9)
    except (TypeError, ValueError):
        rk = 10**9
    try:
        nett = float(row.get("nett") if row.get("nett") is not None else 10**9)
    except (TypeError, ValueError):
        nett = 10**9
    return (rk, nett, str(row.get("sail_number") or ""), str(row.get("helm_name") or ""))


def _render_age_category_podium_sections_html(
    regatta_id: str,
    fleets: list,
    *,
    event_name: Optional[str] = None,
) -> str:
    """Parent-only: one podium table per age_category (top 3), below last fleet.

    Header e.g. "U16 Ilca Fleet" / "U17 420 Fleet" — class stem from overall fleet,
    generic main-header-left logo L+R. Columns: Rank · Class · Sail · Club · Helm · Nett
    (no Category, no Fleet — header already names the category).

    Skip age-band subfleet blocks (Under 17 / u17-results etc.) so youth nationals that
    already publish separate U17/U19 ladders still derive podium from the overall ladder only.
    """
    rid = str(regatta_id or "").strip()
    if not rid or not fleets:
        return ""

    def _is_age_band_subfleet(fl: dict) -> bool:
        bid = str(fl.get("block_id") or "").strip().lower()
        tail = bid.split(":", 1)[-1] if ":" in bid else bid
        if tail in (
            "u16-results", "u17-results", "u18-results", "u19-results", "u21-results",
            "youth-results",
        ):
            return True
        for key in ("fleet_label", "block_label_raw", "name"):
            s = str(fl.get(key) or "").lower()
            if "under " in s or "under1" in s.replace(" ", ""):
                return True
            if re.search(r"\bu1[6-9]\b|\bu21\b", s):
                # e.g. "420 Fleet Under 17" already caught; bare U17 fleet shell
                if "under" in s or "u17-results" in bid or "u19-results" in bid:
                    return True
        return False

    def _class_stem_from_fleets(fls: list) -> str:
        """Prefer catalogue class on overall rows; else strip 'Fleet' from overall label."""
        counts: dict[str, int] = {}
        for fl in fls:
            for r in fl.get("rows") or []:
                if not isinstance(r, dict):
                    continue
                cn = str(r.get("class_name") or "").strip()
                if cn:
                    counts[cn] = counts.get(cn, 0) + 1
        if counts:
            return max(counts.items(), key=lambda kv: kv[1])[0]
        for fl in fls:
            lab = str(fl.get("fleet_label") or fl.get("name") or "").strip()
            if not lab:
                continue
            stem = re.sub(r"\s+Fleet\b.*$", "", lab, flags=re.I).strip()
            stem = re.sub(r"\s+Overall.*$", "", stem, flags=re.I).strip()
            if stem:
                return stem
        return "Ilca"

    # If PDF already publishes U17/U19 (etc.) as separate fleet blocks, do NOT also
    # render age_category podium strips — that duplicates the youth ladders (420 lesson).
    if any(_is_age_band_subfleet(fl) for fl in fleets):
        return ""

    main_fleets = [fl for fl in fleets if not _is_age_band_subfleet(fl)]
    if not main_fleets:
        main_fleets = list(fleets)

    by_cat: dict[str, list] = {}
    for fl in main_fleets:
        fleet_label = (fl.get("fleet_label") or fl.get("name") or "").strip()
        for r in fl.get("rows") or []:
            if not isinstance(r, dict):
                continue
            cat = str(r.get("age_category") or "").strip()
            if not cat:
                continue
            row = dict(r)
            row["_fleet_label"] = fleet_label
            by_cat.setdefault(cat, []).append(row)
    if not by_cat:
        return ""

    class_stem = _class_stem_from_fleets(main_fleets)

    left_url = None
    try:
        lu, _ru = _wc_regatta_header_icon_urls(rid, event_name)
        left_url = (lu or "").strip() or None
    except Exception:
        left_url = None
    if not left_url:
        # Class artwork fallback from stem
        try:
            left_url = _catalogue_logo_path_for_class_name(class_stem)
        except Exception:
            left_url = None
    if not left_url:
        left_url = "/artwork/Class Logo/ILCA-Class-Logo.png"

    img = (
        f'<img src="{html_module.escape(left_url)}" alt="" class="class-header-logo-img" '
        f'loading="lazy" decoding="async" />'
    )
    left_col = f'<div class="class-header-logo-col">{img}</div>'
    right_col = f'<div class="class-header-club-logo-col">{img}</div>'

    ordered = [c for c in _AGE_CATEGORY_PODIUM_ORDER if c in by_cat]
    for c in sorted(by_cat.keys()):
        if c not in ordered:
            ordered.append(c)

    parts: list[str] = []
    for cat in ordered:
        rows = sorted(by_cat[cat], key=_age_category_podium_sort_key)[:3]
        if not rows:
            continue
        title = f"{cat} {class_stem} Fleet"
        thead = (
            '<th class="rank-col">Rank</th>'
            '<th class="class-col">Class</th>'
            '<th class="sail-col">Sail No</th>'
            '<th class="club-col">Club</th>'
            '<th class="helm-col">Helm</th>'
            '<th class="nett-col">Nett</th>'
        )
        trs = []
        for i, r in enumerate(rows, start=1):
            medal = ""
            if i == 1:
                medal = "medal-gold"
            elif i == 2:
                medal = "medal-silver"
            elif i == 3:
                medal = "medal-bronze"
            rank_str = _format_rank(i)
            cn = (r.get("class_name") or r.get("_fleet_label") or "").strip()
            class_html = html_module.escape(cn)
            _rcid = r.get("result_class_id")
            if _rcid is None:
                _rcid = r.get("class_id")
            if _rcid is not None and cn:
                try:
                    _canon = _class_canonical_slug(cn)
                    _href = f"{int(_rcid)}-{_canon}" if _canon else str(int(_rcid))
                    class_html = (
                        f'<a href="/class/{html_module.escape(_href)}">'
                        f"{html_module.escape(cn)}</a>"
                    )
                except Exception:
                    class_html = html_module.escape(cn)
            sail = html_module.escape(str(r.get("sail_number") or "").strip())
            club_raw, club_slug = _regatta_public_club_display_and_slug(r)
            if club_slug and club_raw:
                club_html = (
                    f'<a href="/club/{html_module.escape(str(club_slug))}">'
                    f"{html_module.escape(club_raw)}</a>"
                )
            else:
                club_html = html_module.escape(club_raw)
            helm_html = _tsc_9hr_helm_html(r)
            try:
                nett_plain = _format_total_nett_display(r.get("nett"), True)
            except Exception:
                nett_plain = str(r.get("nett") or "")
            nett_html = html_module.escape(nett_plain)
            trs.append(
                f'<tr class="{medal}">'
                f'<td class="rank-col">{html_module.escape(rank_str)}</td>'
                f'<td class="class-col">{class_html}</td>'
                f'<td class="sail-col">{sail}</td>'
                f'<td class="club-col">{club_html}</td>'
                f'<td class="helm-col">{helm_html}</td>'
                f'<td class="nett-col">{nett_html}</td>'
                f"</tr>"
            )
        table = (
            f'<table class="fleet-results-table age-cat-podium-table">'
            f"<thead><tr>{thead}</tr></thead>"
            f"<tbody>{''.join(trs)}</tbody></table>"
        )
        center = (
            f'<div class="fleet-title-row">{html_module.escape(title)}</div>'
            f'<div class="sailed-line">Category podium — top {len(rows)}</div>'
        )
        parts.append(
            f'<div class="fleet-section age-cat-podium" data-age-category="{html_module.escape(cat, quote=True)}">'
            f'<div class="class-header class-header--with-logos">'
            f"{left_col}"
            f'<div class="class-header-main-col">{center}</div>'
            f"{right_col}"
            f"</div>"
            f'<div class="table-wrapper">{table}</div></div>'
        )
    if not parts:
        return ""
    return (
        '<div class="age-cat-podium-wrap" id="ageCategoryPodiums">'
        + "\n".join(parts)
        + "</div>"
    )



def serve_regatta_standalone(slug: str, request: Request):
    """Serve one full standalone HTML result sheet for /regatta/{slug}. Unknown/missing → 404 (never /events)."""
    start_time = time.time()
    requested_slug = str(slug).strip()
    _slug_redir = _regatta_slug_redirect_target(requested_slug)
    if _slug_redir:
        return RedirectResponse(url=_slug_redir, status_code=301)
    hub_alias_canonical = _REGATTA_HUB_SLUG_ALIASES.get(requested_slug)
    only_block_id: Optional[str] = None
    reg = None
    shell = _resolve_fleet_shell_public_slug(requested_slug)
    if shell:
        rid_shell, bid_shell = shell
        reg = _get_regatta_by_regatta_id(rid_shell)
        if reg:
            only_block_id = bid_shell
    if not reg and hub_alias_canonical:
        reg = _get_regatta_by_regatta_id(hub_alias_canonical)
    if not reg:
        reg = _get_regatta_by_slug(slug)
    if not reg:
        _fleet_parent_redir = _redirect_missing_fleet_shell_to_parent(requested_slug)
        if _fleet_parent_redir is not None:
            return _fleet_parent_redir
        return _regatta_not_found_response(slug)
    regatta_id, event_name, start_date, end_date, host_club_name, host_club_id = reg
    if hub_alias_canonical:
        regatta_id = hub_alias_canonical
    elif str(slug).strip() != str(regatta_id) and only_block_id is None:
        return RedirectResponse(url=f"/regatta/{regatta_id}", status_code=301)
    print("REGATTA: before DB query")
    t0 = time.time()
    data = _get_regatta_full_page_data(regatta_id, only_block_id=only_block_id)
    data = _merge_gimco_2026_hub_fleets(regatta_id, data)
    data = _merge_youth_nationals_2024_hub_fleets(regatta_id, data)
    data = _merge_port_owen_dinghy_shell_fleets(requested_slug, regatta_id, only_block_id, data)
    data = _merge_hyc_cape_classic_2025_hub_fleets(regatta_id, data)
    data = _merge_kzn_2025_regionals_hub_fleets(regatta_id, data)
    data = _merge_mpumalanga_2025_regionals_hub_fleets(regatta_id, data)
    print("LIVE REGATTA DB TIME:", time.time() - t0, flush=True)
    if not data:
        _fleet_parent_redir = _redirect_missing_fleet_shell_to_parent(requested_slug)
        if _fleet_parent_redir is not None:
            return _fleet_parent_redir
        return _regatta_not_found_response(slug)
    try:
        if len(data) >= 10:
            ev_name, host_club_legacy, start_d, end_d, fleets, result_status, as_at_time, host_club_province, host_club_abbrev, host_club_fullname = data[:10]
        else:
            ev_name, host_club_legacy, start_d, end_d, fleets, result_status, as_at_time = data[:7]
            host_club_province = data[7] if len(data) > 7 else None
            host_club_abbrev, host_club_fullname = "", ""
        base_url = _canonical_base_url()
        canonical_slug = requested_slug if only_block_id else str(regatta_id)
        canonical_url = f"{base_url}/regatta/{canonical_slug}"
        display_name = (ev_name or event_name or "").strip()
        escaped_title = html_module.escape(display_name)
        status_word = (result_status or "Final").strip() or "Final"
        status_line_text = _format_regatta_status_line(status_word, as_at_time)
        _pdf_sl = _regatta_pdf_status_line_override(str(regatta_id))
        if _pdf_sl:
            status_line_text = html_module.escape(_pdf_sl)
        host_club_slug = _get_club_slug_by_id(host_club_id) if host_club_id else None
        host_club_text = _format_regatta_host_display(
            host_club_abbrev, host_club_fullname, (host_club_legacy or host_club_name or "")
        )
        esc_host = html_module.escape(host_club_text)
        host_club_html = (
            f'<a href="/club/{html_module.escape(host_club_slug)}">{esc_host}</a>'
            if host_club_slug and host_club_text
            else esc_host
        )
        back_link = '<a href="/" class="back-to-home">← Back to Search</a>'
        is_sa = _session_role_is_super_admin(request)
        hub_badge = _effective_regatta_hub_toolbar_badge_label(str(regatta_id)) if is_sa else None
        if is_sa:
            back_block = (
                '<div class="regatta-back-row">'
                + back_link
                + _wc_super_admin_regatta_toolbar_html(str(regatta_id), hub_badge)
                + "</div>"
            )
        else:
            back_block = back_link
        if _regatta_slug_is_sa_pilot_standalone(str(regatta_id)) and is_sa:
            name_html = _wc_regatta_name_editor_fragment(display_name, str(regatta_id))
            # Public / SA-off-edit: real <a> navigates. SA edit mode: button only (no navigation) — wire to host picker when present.
            if host_club_slug and host_club_text:
                href = f"/club/{html_module.escape(host_club_slug)}"
                host_row = (
                    f'<div class="host-club host-club-wrap">Host: '
                    f'<span class="host-club-public-nav"><a href="{href}">{esc_host}</a></span>'
                    f'<button type="button" class="host-club-sa-edit-hit" id="regattaHostEditBtn" '
                    f'aria-label="Change host club">{esc_host}</button></div>'
                )
            else:
                host_row = (
                    f'<div class="host-club host-club-wrap">Host: '
                    f'<span class="host-club-public-nav">{esc_host}</span>'
                    f'<button type="button" class="host-club-sa-edit-hit" id="regattaHostEditBtn" '
                    f'aria-label="Change host club">{esc_host}</button></div>'
                )
            host_row += _wc_regatta_host_picker_fragment(str(regatta_id))
            host_row += _wc_regatta_fleet_picker_fragment(str(regatta_id))
        else:
            name_html = f'<div class="regatta-name">{escaped_title}</div>'
            host_row = f'<div class="host-club">Host: {host_club_html}</div>'
        lu, ru = _wc_regatta_header_icon_urls(str(regatta_id), ev_name or event_name)
        _host_code_logo = _regatta_host_club_code_resolved(
            host_club_abbrev, (host_club_legacy or host_club_name or ""), str(regatta_id)
        )
        if not ru and _host_code_logo:
            _ensure_club_logo_cached(_host_code_logo, host_club_slug)
        left_logo_col = _regatta_standalone_left_logo_column_html(lu)
        right_logo_col = _regatta_standalone_right_logo_column_html(
            _host_code_logo or host_club_abbrev, host_club_slug, ru
        )
        wc_icons_frag = ""
        if _regatta_slug_is_sa_pilot_standalone(str(regatta_id)) and _session_role_is_super_admin(request):
            _host_preview = (
                _regatta_host_club_logo_src_for_code(_host_code_logo)
                if _host_code_logo and _club_logo_file_exists_on_disk(_host_code_logo)
                else None
            )
            wc_icons_frag = _wc_regatta_header_icon_editor_fragment(
                str(regatta_id),
                lu,
                ru,
                host_club_logo_url=_host_preview,
                show_fleet_header_logos=_wc_regatta_show_fleet_header_logos(str(regatta_id)),
            )
        header_html = (
            '<div class="regatta-header-wrap">'
            + back_block
            + '<div class="header">'
            + left_logo_col
            + '<div class="regatta-header-main-col">'
            f"{name_html}"
            f"{host_row}"
            f'<div class="status-line">{status_line_text}</div>'
            + "</div>"
            + right_logo_col
            + "</div>"
            + wc_icons_frag
            + "</div>"
        )

        def _iso_date(d):
            if d is None:
                return None
            if hasattr(d, "strftime"):
                return d.strftime("%Y-%m-%d")
            return str(d)[:10] if str(d) else None

        # SportsEvent JSON-LD: startDate required (ISO 8601 YYYY-MM-DD); rest for rich result eligibility
        start_iso = _iso_date(start_d)
        json_ld = {
            "@context": "https://schema.org",
            "@type": "SportsEvent",
            "name": ev_name or event_name,
            "sport": "Sailing",
            "eventStatus": "https://schema.org/EventScheduled",
            "eventAttendanceMode": "https://schema.org/OfflineEventAttendanceMode",
        }
        if start_iso:
            json_ld["startDate"] = start_iso
        end_iso = _iso_date(end_d)
        if end_iso:
            json_ld["endDate"] = end_iso
        description = ev_name or event_name or ""
        if description:
            json_ld["description"] = description
        organizer_name = host_club_text or "SailingSA"
        json_ld["organizer"] = {"@type": "Organization", "name": organizer_name}
        if host_club_text:
            address = {"@type": "PostalAddress", "addressCountry": "ZA"}
            if host_club_province:
                address["addressLocality"] = host_club_province
            json_ld["location"] = {
                "@type": "Place",
                "name": host_club_text,
                "address": address,
            }
        use_wc_cols = _regatta_slug_is_sa_pilot_standalone(str(regatta_id))
        is_sa = _session_role_is_super_admin(request)
        wc_prefs = _merge_wc_column_prefs_for_regatta(str(regatta_id)) if use_wc_cols else None
        _show_fleet_hdr_logos = _wc_regatta_show_fleet_header_logos(str(regatta_id)) if use_wc_cols else True
        sa_columns_frag = ""
        if use_wc_cols and is_sa:
            sa_columns_frag = _wc_regatta_sa_columns_panel_html(str(regatta_id), wc_prefs)
        first_wc_bid = str((fleets[0] if fleets else {}).get("block_id") or "")
        late_ext_html = ""
        fleet_section_parts: List[str] = []
        for f in fleets:
            sec, lx = _render_result_sheet_fleet(
                f,
                column_prefs=wc_prefs if use_wc_cols else None,
                wc_sa_fleet_edit=bool(use_wc_cols and is_sa),
                show_fleet_header_logos=_show_fleet_hdr_logos,
                wc_show_late_entry_strip=(
                    bool(use_wc_cols and is_sa)
                    and str((f or {}).get("block_id") or "") == first_wc_bid
                ),
                wc_late_strip_external=(
                    bool(use_wc_cols and is_sa)
                    and str((f or {}).get("block_id") or "") == first_wc_bid
                ),
            )
            fleet_section_parts.append(sec)
            if lx:
                late_ext_html = lx
        fleets_inner = "\n".join(fleet_section_parts)
        fleet_joined = fleets_inner
        if _regatta_slug_is_sa_pilot_standalone(str(regatta_id)) and is_sa:
            wc_slug_js = json.dumps(str(regatta_id))
            fleet_joined = (
                '<div class="wc-dinghy-champs-results-root" id="wcDinghyChampsResultsRoot">'
                + late_ext_html
                + ("\n" if late_ext_html else "")
                + fleets_inner
                + "</div>"
                "<script>(function(){"
                'var root=document.getElementById("wcDinghyChampsResultsRoot");'
                'var page=document.querySelector(".regatta-page");'
                "var slug=" + wc_slug_js + ";"
                "if(!root||!page)return;"
                "function onCap(e){"
                "try{"
                'if((location.pathname||"").indexOf(slug)===-1)return;'
                'if(!page.classList.contains("regatta-page--super-admin-edit"))return;'
                "var t=e.target;if(t&&t.nodeType===3)t=t.parentElement;"
                "if(!t||!t.closest)return;"
                "if(!root.contains(t))return;"
                "var a=t.closest('a[href]');if(!a||!root.contains(a))return;"
                "e.preventDefault();e.stopImmediatePropagation();"
                "}catch(x){}"
                "}"
                'root.addEventListener("click",onCap,true);'
                "})();</script>"
            )
        print_btn = '<div class="action-buttons"><button class="action-button" onclick="window.print()">Print</button></div>'
        banner_top = _wc_regatta_source_banner_html(str(regatta_id), position="top")
        banner_bottom = _wc_regatta_source_banner_html(str(regatta_id), position="bottom")
        event_info_frag = _render_event_info_strip_html(str(regatta_id), is_super_admin=bool(is_sa))
        # REGATTA_ENTRY_FLOW_2026_07_23
        _eis_cfg = _wc_regatta_event_info_strip_cfg(str(regatta_id))
        entry_script = (
            '<link rel="stylesheet" href="/js/regatta-entry.css?v=20260723e8">'
            '<script src="/js/regatta-entry.js?v=20260723e8" defer></script>'
            if (_eis_cfg.get("enter") or {}).get("url") or (_eis_cfg.get("enter") or {}).get("label")
            else ""
        )
        body_html = (
            header_html + banner_top + event_info_frag + sa_columns_frag + "\n"
            + fleet_joined + "\n" + banner_bottom + print_btn
        )
        seo_sailors = ""
        seo_disc = _seo_discovery_block_html()
        wc_club_edit_script = (
            (_wc_standalone_fleet_edit_script_html() + _wc_standalone_fleet_autocomplete_script_html())
            if _regatta_slug_is_sa_pilot_standalone(str(regatta_id)) and is_sa
            else ""
        )
        sa_toolbar_script = (
            '<script src="/js/regatta-sa-toolbar.js?v=20260723sa0" defer></script><script src="/js/regatta-fleet-ops.js?v=20260723f2" defer></script>' if is_sa else ""
        )
        doc = (
            "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>"
            f"{escaped_title} | SailingSA</title>"
            f"<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
            f"<link rel=\"canonical\" href=\"{html_module.escape(canonical_url)}\">"
            "<link rel=\"icon\" href=\"/favicon.ico\" sizes=\"any\"><link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"48x48\" href=\"/favicon-48.png\"><link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/favicon-192.png\"><link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">"
            "<link rel=\"icon\" type=\"image/png\" sizes=\"192x192\" href=\"/favicon-192.png\">"
            f"<script type=\"application/ld+json\">{json.dumps(json_ld)}</script>"
            f"<style>{_RESULT_SHEET_CSS}</style></head><body>"
            f"<div class=\"regatta-page\">{body_html}</div>{seo_sailors}{seo_disc}{sa_toolbar_script}{wc_club_edit_script}{entry_script}"
            '<footer class="site-footer-about" style="text-align:center;padding:2rem 1rem;font-size:0.9rem;color:#666;border-top:1px solid #e0e0e0;margin-top:2rem;">SailingSA – South African Sailing Results Database © <span id="year-sa-footer"></span></footer>'
            "<script>document.getElementById('year-sa-footer').textContent=new Date().getFullYear();</script>"
            "</body></html>"
        )
        print("REGATTA: total route time", round(time.time() - start_time, 3))
        return HTMLResponse(doc)
    except Exception as e:
        print(f"[serve_regatta_standalone] {e}", flush=True)
        return HTMLResponse(content=_HTML_SOFT_FAIL_200, status_code=200, media_type="text/html")


def _sitemap_sailor_slugs():
    """Return list of canonical sailor slugs for sitemap. Only sailors in sas_id_personal with at least one result (helm or crew). No broken URLs for crawlers."""
    out = []
    try:
        if not table_exists("results") or not table_exists("sas_id_personal"):
            return out
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            # Helm and crew: every sailor we might link to from regatta results must be in sitemap (avoid crawl 404s)
            cur.execute("""
                SELECT DISTINCT r.helm_sa_sailing_id::text AS sas_id,
                    COALESCE(TRIM(s.full_name), TRIM(s.first_name || ' ' || COALESCE(s.last_name, ''))) AS full_name
                FROM results r
                JOIN public.sas_id_personal s ON s.sa_sailing_id::text = r.helm_sa_sailing_id::text
                WHERE r.helm_sa_sailing_id IS NOT NULL
                  AND (s.full_name IS NOT NULL AND TRIM(s.full_name) != ''
                       OR s.first_name IS NOT NULL OR s.last_name IS NOT NULL)
                UNION
                SELECT DISTINCT r.crew_sa_sailing_id::text AS sas_id,
                    COALESCE(TRIM(s.full_name), TRIM(s.first_name || ' ' || COALESCE(s.last_name, ''))) AS full_name
                FROM results r
                JOIN public.sas_id_personal s ON s.sa_sailing_id::text = r.crew_sa_sailing_id::text
                WHERE r.crew_sa_sailing_id IS NOT NULL
                  AND (s.full_name IS NOT NULL AND TRIM(s.full_name) != ''
                       OR s.first_name IS NOT NULL OR s.last_name IS NOT NULL)
                ORDER BY full_name, sas_id
            """)
            rows = cur.fetchall()
            by_sid = {}  # sas_id -> full_name (dedupe so helm+crew same sailor once)
            for r in rows:
                sid = str(r.get("sas_id") or "")
                if not sid or sid in by_sid:
                    continue
                name = (r.get("full_name") or "").strip()
                if not name:
                    continue
                by_sid[sid] = name
            by_name = defaultdict(list)
            for sid, name in by_sid.items():
                by_name[name].append(sid)
            for name, sids in by_name.items():
                has_dup = len(sids) > 1
                for sid in sids:
                    slug = _sailor_canonical_slug(name, sid, has_dup)
                    out.append(slug)
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[sitemap] sailor slugs: {e}")
    return out


def _sitemap_club_slugs():
    """Return list of (slug, lastmod_iso) for clubs that have results or host regattas. Slug = canonical club_code (from club_abbrev)."""
    out = []
    try:
        if not table_exists("clubs"):
            return out
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT DISTINCT c.club_id, c.club_abbrev, c.club_fullname, c.club_name
                FROM clubs c
                WHERE (EXISTS (SELECT 1 FROM results r WHERE r.club_id = c.club_id)
                       OR EXISTS (SELECT 1 FROM regattas r WHERE r.host_club_id = c.club_id))
                  AND (c.club_fullname IS NOT NULL AND TRIM(c.club_fullname) != ''
                       OR c.club_name IS NOT NULL AND TRIM(c.club_name) != ''
                       OR c.club_abbrev IS NOT NULL AND TRIM(c.club_abbrev) != '')
            """)
            today = datetime.utcnow().strftime("%Y-%m-%d")
            for r in cur.fetchall() or []:
                abbrev = (r.get("club_abbrev") or "").strip()
                fullname = (r.get("club_fullname") or "").strip()
                name = (r.get("club_name") or "").strip()
                slug = _club_slug_from_name(abbrev) if abbrev else (_club_slug_from_name(fullname) if fullname else _club_slug_from_name(name))
                if slug:
                    out.append((slug, today))
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[sitemap] club slugs: {e}")
    return out


def _sitemap_class_ids():
    """Return list of class_id (int) for sitemap. Only classes with _sailors_in_class > 0."""
    return [cid for cid, _ in _sitemap_class_entries()]


def _sitemap_class_entries():
    """Return list of (class_id, class_name) for sitemap. From classes table; fallback to results if empty."""
    out = []
    try:
        if table_exists("classes"):
            conn = get_db_connection()
            cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
            try:
                cur.execute("""
                    SELECT class_id, class_name FROM classes
                    WHERE class_id IS NOT NULL
                    ORDER BY class_id
                """)
                for r in cur.fetchall() or []:
                    cid = r.get("class_id")
                    name = (r.get("class_name") or "").strip()
                    if cid is not None:
                        out.append((int(cid), name))
            finally:
                cur.close()
                return_db_connection(conn)
        # Fallback 1: distinct class_id from results
        if len(out) == 0 and table_exists("results"):
            conn = get_db_connection()
            cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
            try:
                cur.execute("SELECT DISTINCT class_id FROM results WHERE class_id IS NOT NULL ORDER BY class_id")
                ids_from_results = [int(r["class_id"]) for r in (cur.fetchall() or []) if r.get("class_id") is not None]
                if ids_from_results and table_exists("classes"):
                    placeholders = ",".join(["%s"] * len(ids_from_results))
                    cur.execute(
                        f"SELECT class_id, class_name FROM classes WHERE class_id IN ({placeholders}) ORDER BY class_id",
                        ids_from_results,
                    )
                    name_by_id = {r["class_id"]: (r.get("class_name") or "").strip() for r in (cur.fetchall() or [])}
                    out = [(cid, name_by_id.get(cid, "")) for cid in ids_from_results]
                else:
                    out = [(cid, "") for cid in ids_from_results]
            finally:
                cur.close()
                return_db_connection(conn)
        # Fallback 2: distinct class_id from regatta_blocks (block-level class data)
        if len(out) == 0 and table_exists("regatta_blocks"):
            conn = get_db_connection()
            cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
            try:
                cur.execute("SELECT DISTINCT class_id FROM regatta_blocks WHERE class_id IS NOT NULL ORDER BY class_id")
                ids = [int(r["class_id"]) for r in (cur.fetchall() or []) if r.get("class_id") is not None]
                if ids and table_exists("classes"):
                    placeholders = ",".join(["%s"] * len(ids))
                    cur.execute(
                        f"SELECT class_id, class_name FROM classes WHERE class_id IN ({placeholders}) ORDER BY class_id",
                        ids,
                    )
                    name_by_id = {r["class_id"]: (r.get("class_name") or "").strip() for r in (cur.fetchall() or [])}
                    out = [(cid, name_by_id.get(cid, "")) for cid in ids]
                else:
                    out = [(cid, "") for cid in ids]
            finally:
                cur.close()
                return_db_connection(conn)
    except Exception as e:
        print(f"[sitemap] class entries: {e}")
    print(f"[sitemap] classes: {len(out)}")
    return out


def _sitemap_regatta_slugs():
    """Return list of (slug, lastmod_iso) for sitemap. lastmod from end_date or start_date."""
    out = []
    try:
        if not table_exists("regattas"):
            return out
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT event_name, regatta_id, end_date, start_date FROM regattas
                WHERE event_name IS NOT NULL AND TRIM(event_name) != ''
                ORDER BY regatta_id
            """)
            for r in cur.fetchall() or []:
                name = (r.get("event_name") or "").strip()
                if not name:
                    continue
                slug = re.sub(r"[^\w\s\-]", "", name).strip().lower()
                slug = re.sub(r"\s+", "-", slug).strip("-")
                if not slug:
                    continue
                end_date = r.get("end_date")
                start_date = r.get("start_date")
                d = end_date or start_date
                if d and hasattr(d, "strftime"):
                    lastmod = d.strftime("%Y-%m-%d")
                else:
                    lastmod = datetime.utcnow().strftime("%Y-%m-%d")
                out.append((slug, lastmod))
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[sitemap] regatta slugs: {e}")
    return out


def _sitemap_regatta_class_entries():
    """Return list of (regatta_slug, class_slug) for /regatta/{slug}/class-{class_slug}. Only regattas/classes with results."""
    out = []
    try:
        if not table_exists("regattas") or not table_exists("results"):
            return out
        conn = get_db_connection()
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            cur.execute("""
                SELECT DISTINCT r.regatta_id, r.event_name, c.class_id, c.class_name
                FROM regattas r
                JOIN results res ON res.regatta_id = r.regatta_id
                JOIN regatta_blocks rb ON rb.block_id = res.block_id AND rb.regatta_id = res.regatta_id
                JOIN classes c ON c.class_id = COALESCE(res.class_id, rb.class_id)
                WHERE r.event_name IS NOT NULL AND TRIM(r.event_name) != ''
                  AND c.class_name IS NOT NULL AND TRIM(c.class_name) != ''
                ORDER BY r.regatta_id, c.class_name
            """)
            seen = set()
            for r in cur.fetchall() or []:
                name = (r.get("event_name") or "").strip()
                if not name:
                    continue
                regatta_slug = re.sub(r"[^\w\s\-]", "", name).strip().lower()
                regatta_slug = re.sub(r"\s+", "-", regatta_slug).strip("-")
                if not regatta_slug:
                    continue
                class_name = (r.get("class_name") or "").strip()
                class_slug = _class_canonical_slug(class_name) if class_name else ""
                if not class_slug:
                    continue
                key = (regatta_slug, class_slug)
                if key not in seen:
                    seen.add(key)
                    out.append(key)
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as e:
        print(f"[sitemap] regatta-class entries: {e}")
    return out


def _sitemap_escape_loc(url: str) -> str:
    """Escape loc for sitemap XML: & -> &amp;, < -> &lt;, > -> &gt;, ' -> &apos;, \" -> &quot;."""
    if not url:
        return ""
    return (
        url.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&apos;")
    )


# In-memory sitemap cache: global var + timestamp, 10–30 min TTL (avoids DB load on every request).
_SITEMAP_CACHE_TTL_SEC = 1200  # 20 min
_sitemap_cache = {"body": None, "expires_at": 0.0}


def _build_sitemap_xml() -> str:
    """Sitemap index (sitemaps.org): points to child urlset files on the site. Called on cache miss."""
    base = _canonical_base_url().rstrip("/")
    today = datetime.utcnow().strftime("%Y-%m-%d")
    child_names = (
        "sitemap-classes.xml",
        "sitemap-clubs.xml",
        "sitemap-core.xml",
        "sitemap-regattas.xml",
        "sitemap-sailors.xml",
    )
    lines = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    ]
    for name in child_names:
        full_url = f"{base}/{name}"
        esc_loc = _sitemap_escape_loc(full_url)
        lines.append("  <sitemap>")
        lines.append(f"    <loc>{esc_loc}</loc>")
        lines.append(f"    <lastmod>{today}</lastmod>")
        lines.append("  </sitemap>")
    lines.append("</sitemapindex>")
    print(f"[sitemap] index: {len(child_names)} child sitemaps, lastmod={today}")
    return "\n".join(lines)


_SITEMAP_HEADERS = {"Cache-Control": "public, max-age=600"}


@app.api_route("/sitemap.xml", methods=["GET", "HEAD"])
def serve_sitemap_xml():
    """Dynamic sitemap: valid sitemaps.org schema. If cache valid → return cached XML; else regenerate and store."""
    now = time.time()
    if _sitemap_cache["body"] is not None and now < _sitemap_cache["expires_at"]:
        print("[sitemap] cache HIT")
        return Response(content=_sitemap_cache["body"], media_type="application/xml", headers=_SITEMAP_HEADERS)
    print("[sitemap] cache MISS")
    body = _build_sitemap_xml()
    _sitemap_cache["body"] = body
    _sitemap_cache["expires_at"] = now + _SITEMAP_CACHE_TTL_SEC
    return Response(content=body, media_type="application/xml", headers=_SITEMAP_HEADERS)


@app.get("/robots.txt")
def serve_robots_txt():
    """Serve robots.txt: Allow all, point to sitemap. Content-Type: text/plain. Trailing newline for crawl spec."""
    base = _canonical_base_url()
    body = f"User-agent: *\nAllow: /\nSitemap: {base}/sitemap.xml\n"
    return Response(content=body, media_type="text/plain", headers={"Cache-Control": "public, max-age=3600"})

