_CLUB_TABLES_SORT_JS = """
(function(){
  function sortTable(table, colIndex){
    if(!table||!table.tBodies||!table.tBodies[0])return;
    var tbody=table.tBodies[0];
    var rows=Array.prototype.slice.call(tbody.querySelectorAll('tr'));
    if(rows.length===0)return;
    var cur=parseInt(table.dataset.sortCol,10);
    var dir=(cur===colIndex&&(table.dataset.sortDir||'asc')==='asc')?'desc':'asc';
    table.dataset.sortCol=colIndex;table.dataset.sortDir=dir;
    var isoRe=/^\\d{4}-\\d{2}-\\d{2}/;
    rows.sort(function(a,b){
      var ac=a.cells[colIndex],bc=b.cells[colIndex];
      if(!ac||!bc)return 0;
      var at=(ac.textContent||'').trim(),bt=(bc.textContent||'').trim();
      if(isoRe.test(at)&&isoRe.test(bt)){var dc=at<bt?-1:(at>bt?1:0);return dir==='asc'?dc:-dc;}
      var am=at.match(/-?\\d+(?:\\.\\d+)?/),bm=bt.match(/-?\\d+(?:\\.\\d+)?/);
      var an=am?parseFloat(am[0]):NaN,bn=bm?parseFloat(bm[0]):NaN;
      if(!isNaN(an)&&!isNaN(bn)&&/\\d/.test(at.charAt(0))&&/\\d/.test(bt.charAt(0)))return dir==='asc'?an-bn:bn-an;
      var c=at.localeCompare(bt,undefined,{numeric:true});
      return dir==='asc'?c:-c;
    });
    rows.forEach(function(r){tbody.appendChild(r);});
    var ch=dir==='asc'?'\\u25B2':'\\u25BC';
    Array.prototype.forEach.call(table.querySelectorAll('thead th'),function(th,i){
      var sp=th.querySelector('.sort-indicator');
      if(sp)sp.textContent=i===colIndex?' '+ch:' \\u21C5';
    });
  }
  Array.prototype.forEach.call(document.querySelectorAll('.club-page table.table thead th'),function(th){
    th.style.cursor='pointer';th.title='Sort';
    th.addEventListener('click',function(){sortTable(th.closest('table'),th.cellIndex);});
  });
  Array.prototype.forEach.call(document.querySelectorAll('.club-table-filter'),function(inp){
    var tgt=document.getElementById(inp.getAttribute('data-table')||'');
    if(!tgt)return;
    inp.addEventListener('input',function(){
      var q=(inp.value||'').trim().toLowerCase();
      Array.prototype.forEach.call(tgt.tBodies[0].rows,function(tr){
        var hay=tr.getAttribute('data-search')||tr.textContent.toLowerCase();
        tr.style.display=(!q||hay.indexOf(q)!==-1)?'':'none';
      });
    });
  });
})();
"""


def _club_sort_th(label, extra_cls=""):
    cls = ' class="%s"' % extra_cls if extra_cls else ""
    return '<th%s>%s<span class="sort-indicator" aria-hidden="true"> \u21C5</span></th>' % (cls, html_module.escape(label))


def _club_sailors_table_section_html(sailors: list, club_abbrev: str = "") -> str:
    n = len(sailors or [])
    head = "<thead><tr>" + _club_sort_th("#") + _club_sort_th("Sailor") + "</tr></thead>"
    ab = (club_abbrev or "").strip().upper()
    logo_html = (
        '<img src="/api/club-logo/%s" alt="" class="row-logo" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' % html_module.escape(ab)
    ) if ab else ""
    trs = []
    for i, (name, sslug) in enumerate(sailors or [], 1):
        dn = html_module.escape(name)
        ds = html_module.escape(name.lower(), quote=True)
        trs.append(
            '<tr data-search="%s"><td>%d</td><td class="cell-left">%s'
            '<a href="/sailor/%s">%s</a></td></tr>' % (ds, i, logo_html, html_module.escape(sslug), dn)
        )
    body_rows = "".join(trs) or '<tr><td colspan="2">No sailors found.</td></tr>'
    return (
        '<div class="card stats-section club-sailors-section">'
        '<h2 class="section-title">Sailors (%d)</h2>'
        '<input type="search" class="club-table-filter" data-table="club-sailors-table" placeholder="Search sailors name…" autocomplete="off">'
        '<div class="table-container club-table-scroll"><table class="table" id="club-sailors-table">%s<tbody>%s</tbody></table></div>'
        "</div>" % (n, head, body_rows)
    )


def _club_regatta_row_logo_url(regatta_id: str, event_name: str, club_abbrev: str = "") -> str:
    """Same left artwork as the open /regatta/{id} main header — used in every list.

    Truth = wc_regatta_header_icons.json `left` (Event Logo or Class Logo).
    Never use club/host logos here (those are header-right only).
    """
    rid = str(regatta_id or "").strip()
    ename = (event_name or "").strip()

    def _norm(path: str) -> str:
        p = (path or "").strip()
        if not p:
            return ""
        return p if p.startswith("/") else "/" + p.lstrip("/")

    def _is_club_logo(path: str) -> bool:
        p = (path or "").lower()
        return "/club logo/" in p or "/api/club-logo/" in p or p.startswith("/api/club-logo/")

    # 1) Exact header left for this regatta (what you see when you open the result)
    try:
        left, _r = _wc_regatta_header_icon_urls(rid, ename)
        left = _norm(left or "")
        if left and not _is_club_logo(left):
            return left
    except Exception:
        pass

    # 2) Name → Event Logo rules (calendar cards / no slug yet)
    hay = f"{ename.lower()} {rid.lower()}"
    best_src = ""
    best_len = -1
    try:
        for needle, src, _label in _CLUB_EVENT_LOGO_RULES:
            if needle and needle in hay and len(needle) > best_len:
                best_src = _norm(src)
                best_len = len(needle)
    except Exception:
        best_src = ""
    if best_src and not _is_club_logo(best_src):
        return best_src

    return ""


def _club_regattas_table_section_html(regattas: list, club_abbrev: str) -> str:
    n = len(regattas or [])
    head = "<thead><tr>" + _club_sort_th("#") + _club_sort_th("Event") + _club_sort_th("Date") + "</tr></thead>"
    trs = []
    for i, row in enumerate(regattas or [], 1):
        name, regatta_id = row[0], row[1]
        date = row[2] if len(row) > 2 else ""
        dn = html_module.escape(str(name or ""))
        rid = html_module.escape(str(regatta_id or ""))
        dd = html_module.escape(str(date or ""))
        ds = html_module.escape(("%s %s" % (name, date or "")).strip().lower(), quote=True)
        logo = _club_regatta_row_logo_url(regatta_id, name, club_abbrev)
        logo_html = (
            '<img src="%s" alt="" class="row-logo" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' % html_module.escape(logo)
        ) if logo else ""
        trs.append(
            '<tr data-search="%s"><td>%d</td><td class="cell-left">%s<a href="/regatta/%s">%s</a></td>'
            '<td>%s</td></tr>' % (ds, i, logo_html, rid, dn, dd)
        )
    body_rows = "".join(trs) or '<tr><td colspan="3">No regattas found.</td></tr>'
    return (
        '<div class="card stats-section club-regattas-section">'
        '<h2 class="section-title">Regattas hosted (%d)</h2>'
        '<input type="search" class="club-table-filter" data-table="club-regattas-table" placeholder="Search regattas…" autocomplete="off">'
        '<div class="table-container club-table-scroll"><table class="table" id="club-regattas-table">%s<tbody>%s</tbody></table></div>'
        "</div>" % (n, head, body_rows)
    )


def _club_card_date_cell(val) -> str:
    """Normalize a card date for club tables — ISO preferred; never truncate display dates."""
    s = str(val or "").strip()
    if not s:
        return ""
    # ISO YYYY-MM-DD (optionally with time)
    if len(s) >= 10 and s[4:5] == "-" and s[7:8] == "-":
        return s[:10]
    return s  # e.g. "28 Mar 2026" — keep full string


def _club_same_start_date_keys(cards: list) -> set:
    """Start dates that appear on more than one card — red-flag for club lists."""
    from collections import Counter

    keys = []
    for c in cards or []:
        d = _club_card_date_cell(c.get("start_date_iso") or c.get("date_display") or "")
        if d and d != "—":
            keys.append(d)
    return {k for k, n in Counter(keys).items() if n > 1}


def _club_event_table_rows(
    cards: list,
    include_result: bool,
    club_abbrev: str = "",
    *,
    allow_regatta_links: bool = True,
) -> str:
    clash_dates = _club_same_start_date_keys(cards)
    trs = []
    for i, c in enumerate(cards or [], 1):
        name = str(c.get("display_title") or c.get("event_name") or "").strip() or "—"
        dn = html_module.escape(name)
        logo = _club_regatta_row_logo_url(str(c.get("regatta_id") or ""), name, club_abbrev)
        logo_html = (
            '<img src="%s" alt="" class="row-logo" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">' % html_module.escape(logo)
        ) if logo else ""
        sd_raw = _club_card_date_cell(c.get("start_date_iso") or c.get("date_display") or "")
        ed_raw = _club_card_date_cell(c.get("end_date_iso") or "")
        sd = html_module.escape(sd_raw)
        ed = html_module.escape(ed_raw)
        details = str(c.get("details_url") or "").strip()
        rurl = str(c.get("result_url") or "").strip()
        if not allow_regatta_links:
            # Upcoming: never deep-link into /regatta/.
            if rurl.startswith("/regatta/"):
                rurl = ""
            if details.startswith("/regatta/"):
                details = ""
        else:
            # Past Events / Regattas Hosted: /regatta/ only when results exist (result_url).
            # details_url=/regatta/... without results → treat as no result page link.
            if not rurl and details.startswith("/regatta/"):
                details = ""
        if rurl:
            name_html = '<a href="%s">%s</a>' % (html_module.escape(rurl), dn)
        elif details:
            ext = details.startswith("http")
            if ext:
                name_html = '<a href="%s" target="_blank" rel="noopener">%s</a>' % (html_module.escape(details), dn)
            else:
                name_html = '<a href="%s">%s</a>' % (html_module.escape(details), dn)
        else:
            name_html = dn
        date_clash = bool(sd_raw and sd_raw in clash_dates)
        if date_clash:
            flag = (
                '<span class="club-date-clash-flag" title="Red flag: another hosted event shares this start date '
                '(unusual unless clearly different events)">⚠ same date</span> '
            )
            name_html = flag + name_html
            tr_attr = ' class="club-date-clash" data-date-clash="1"'
        else:
            tr_attr = ""
        ds = html_module.escape((name + " " + (sd_raw or "")).lower(), quote=True)
        res_td = ""
        if include_result:
            res_td = "<td>%s</td>" % ('<a href="%s">Results</a>' % html_module.escape(rurl) if rurl else "—")
        trs.append(
            '<tr%s data-search="%s"><td>%d</td><td class="cell-left">%s%s</td><td>%s</td>'
            '<td class="hide-mobile">%s</td>%s</tr>'
            % (tr_attr, ds, i, logo_html, name_html, sd or "—", ed or "—", res_td)
        )
    return "".join(trs)




def _club_norm_event_core(name: str) -> str:
    """Normalize event title for same-event duplicate detection on club lists."""
    s = str(name or "").lower()
    s = re.sub(r"\d{4}-\d{2}-\d{2}", " ", s)
    s = re.sub(r"\b20\d{2}\b", " ", s)
    s = re.sub(
        r"\b(results?|class fleets?|fleets?|final|provisional|as at|overall)\b",
        " ",
        s,
    )
    s = re.sub(r"[^a-z0-9]+", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def _club_cards_same_event(a: dict, b: dict) -> bool:
    """True when two club cards are the same hosted event (dup / parent+fleet sibling)."""
    da = _club_card_date_cell(a.get("start_date_iso") or a.get("date_display") or "")
    db = _club_card_date_cell(b.get("start_date_iso") or b.get("date_display") or "")
    if not da or da != db:
        return False
    na = _club_norm_event_core(a.get("display_title") or a.get("event_name") or "")
    nb = _club_norm_event_core(b.get("display_title") or b.get("event_name") or "")
    if not na or not nb:
        return False
    if na == nb:
        return True
    if na in nb or nb in na:
        return True
    ta, tb = set(na.split()), set(nb.split())
    inter = ta & tb
    if len(inter) >= 3 and (len(inter) / max(len(ta | tb), 1)) >= 0.55:
        return True
    return False


def _club_prefer_event_card(a: dict, b: dict) -> dict:
    """Prefer master/parent-looking card over Class Fleets / longer org-prefix twin."""
    def score(c: dict) -> tuple:
        name = str(c.get("display_title") or c.get("event_name") or "")
        rid = str(c.get("regatta_id") or "")
        core = _club_norm_event_core(name)
        has_results = 1 if (c.get("result_yes") or str(c.get("result_url") or "").startswith("/regatta/")) else 0
        class_fleets_penalty = 1 if re.search(r"class\s*fleets?", name, re.I) else 0
        # Prefer shorter core (drop org prefixes / fleet suffixes)
        return (
            has_results,
            -class_fleets_penalty,
            -len(core),
            -len(rid),  # shorter slug often master (king-of-vaal vs long provincial dump)
            name.lower(),
        )
    return a if score(a) >= score(b) else b


def _club_collapse_same_event_cards(cards: list) -> list:
    """Collapse calendar/regatta twins that are clearly the same event (same date + name core)."""
    out: list = []
    for card in cards or []:
        c = dict(card)
        merged = False
        for i, keep in enumerate(out):
            if _club_cards_same_event(keep, c):
                out[i] = _club_prefer_event_card(keep, c)
                merged = True
                break
        if not merged:
            out.append(c)
    return out


def _club_fleet_child_parent_map(regatta_ids: list) -> dict:
    """Map fleet-child slug → parent/master slug when parent exists in regattas.

    Club lists show one row per hosted event/regatta — never each fleet child URL.
    Child pattern: `{parent}-{fleet-tail}` where `parent` is also a regatta_id.
    """
    ids = [str(r or "").strip() for r in (regatta_ids or []) if str(r or "").strip()]
    if not ids:
        return {}
    candidates = set()
    for rid in ids:
        parts = rid.split("-")
        for i in range(1, len(parts)):
            cand = "-".join(parts[:i])
            if cand and cand != rid:
                candidates.add(cand)
    if not candidates:
        return {}
    existing = set()
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        try:
            cur.execute(
                "SELECT regatta_id::text AS rid FROM regattas WHERE regatta_id = ANY(%s)",
                (list(candidates),),
            )
            for row in cur.fetchall() or []:
                rid = row[0] if not isinstance(row, dict) else row.get("rid")
                if rid:
                    existing.add(str(rid).strip())
        finally:
            cur.close()
            return_db_connection(conn)
    except Exception as ex:
        print(f"[club page] parent map: {ex}")
        # Fallback: only parents that appear in the same id list
        existing = set(ids)
    out = {}
    for rid in ids:
        # Longest matching parent prefix wins
        best = ""
        for p in existing:
            if rid.startswith(p + "-") and len(p) > len(best):
                best = p
        if best:
            out[rid] = best
    return out


def _club_parent_only_regatta_rows(rows: list) -> list:
    """Keep single-fleet events and multi-fleet parents; drop fleet-child rows."""
    ids = [str(r[1]).strip() for r in (rows or []) if len(r) > 1 and r[1]]
    pmap = _club_fleet_child_parent_map(ids)
    out = []
    seen_parents = set()
    for row in rows or []:
        if len(row) < 2 or not row[1]:
            continue
        rid = str(row[1]).strip()
        parent = pmap.get(rid, rid)
        if rid != parent:
            # Fleet child URL — skip (parent listed separately when hosted here)
            continue
        if parent in seen_parents:
            continue
        seen_parents.add(parent)
        out.append(row)
    return out


def _club_hosted_tuple_to_event_card(t, *, with_results: bool = False) -> dict:
    """Synthetic event card from a hosted regatta match-tuple.

    Tuple: (event_name, regatta_id, date_str, start_key, end_key).
    Always use ISO start_key/end_key — never truncate display date_str.
    """
    name = str(t[0] if t else "") or "—"
    rid = str(t[1]).strip() if t and len(t) > 1 else ""
    start_iso = str(t[3]).strip()[:10] if t and len(t) > 3 and t[3] else ""
    end_iso = str(t[4]).strip()[:10] if t and len(t) > 4 and t[4] else start_iso
    if not start_iso and t and len(t) > 2 and t[2]:
        # fallback only if value already looks like ISO
        raw = str(t[2]).strip()
        if len(raw) >= 10 and raw[4:5] == "-" and raw[7:8] == "-":
            start_iso = raw[:10]
    return {
        "display_title": name,
        "event_name": name,
        "regatta_id": rid,
        "start_date_iso": start_iso,
        "end_date_iso": end_iso or start_iso,
        "details_url": "",
        "result_url": (("/regatta/" + rid) if (with_results and rid) else ""),
        "result_yes": bool(with_results and rid),
    }


def _club_other_events_table_html(other_events: list, club_abbrev: str = "") -> str:
    """Other events (no results) — rendered below Sailors on the club page."""
    head = (
        "<thead><tr>"
        + _club_sort_th("#")
        + _club_sort_th("Event")
        + _club_sort_th("Start")
        + _club_sort_th("End", "hide-mobile")
        + "</tr></thead>"
    )
    rows_ot = _club_event_table_rows(
        other_events or [],
        include_result=False,
        club_abbrev=club_abbrev,
        allow_regatta_links=False,
    ) or '<tr><td colspan="4">No other hosted events.</td></tr>'
    return (
        '<div class="card stats-section club-other-events-section">'
        '<h2 class="section-title">Other events (%d)</h2>'
        '<p class="club-events-intro" style="margin:0 0 0.65rem 0;font-size:0.9rem;color:#475569;">'
        "Hosted events that are not a regatta, or do not have results yet — no result-page link."
        "</p>"
        '<input type="search" class="club-table-filter" data-table="club-other-events-table" placeholder="Search other events…" autocomplete="off">'
        '<div class="table-container club-table-scroll"><table class="table" id="club-other-events-table">%s<tbody>%s</tbody></table></div>'
        "</div>" % (len(other_events or []), head, rows_ot)
    )


def _club_events_tables_html(
    up: list,
    lv: list,
    past_regattas: list,
    club_abbrev: str = "",
) -> str:
    """Upcoming → Past Events / Regattas Hosted. Other events render below Sailors."""
    upcoming = list(lv or []) + list(up or [])
    out = []
    head = (
        "<thead><tr>"
        + _club_sort_th("#")
        + _club_sort_th("Event")
        + _club_sort_th("Start")
        + _club_sort_th("End", "hide-mobile")
        + "</tr></thead>"
    )
    rows_up = _club_event_table_rows(upcoming, include_result=False, club_abbrev=club_abbrev, allow_regatta_links=False) or '<tr><td colspan="4">No upcoming events.</td></tr>'
    out.append(
        '<div class="card stats-section club-upcoming-events-section">'
        '<h2 class="section-title">Upcoming events (%d)</h2>'
        '<input type="search" class="club-table-filter" data-table="club-upcoming-table" placeholder="Search upcoming events…" autocomplete="off">'
        '<div class="table-container club-table-scroll"><table class="table" id="club-upcoming-table">%s<tbody>%s</tbody></table></div>'
        "</div>" % (len(upcoming), head, rows_up)
    )
    rows_ph = _club_event_table_rows(
        past_regattas or [],
        include_result=False,
        club_abbrev=club_abbrev,
        allow_regatta_links=True,
    ) or '<tr><td colspan="4">No past events / regattas hosted.</td></tr>'
    out.append(
        '<div class="card stats-section club-past-regattas-hosted-section">'
        '<h2 class="section-title">Past Events / Regattas Hosted (%d)</h2>'
        '<p class="club-events-intro" style="margin:0 0 0.65rem 0;font-size:0.9rem;color:#475569;">'
        "Hosted regattas with results — one row per event (fleets live on the result page). "
        "Red flag = two or more events sharing the same start date (unusual for one club)."
        "</p>"
        '<input type="search" class="club-table-filter" data-table="club-past-regattas-hosted-table" placeholder="Search past events / regattas…" autocomplete="off">'
        '<div class="table-container club-table-scroll"><table class="table" id="club-past-regattas-hosted-table">%s<tbody>%s</tbody></table></div>'
        "</div>" % (len(past_regattas or []), head, rows_ph)
    )
    return "".join(out)


@app.get("/api/optimist-family")
def api_optimist_family():
    """Master list of all Optimist boats - resolves generic Optimist to valid fleet"""
    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    
    cur.execute("""
        WITH normalized_sails AS (
            SELECT 
                UPPER(TRIM(REGEXP_REPLACE(r.sail_number, '^RSA\\s*', '', 'i'))) as sail_norm,
                r.helm_name,
                c.class_name,
                reg.start_date,
                reg.event_name,
                reg.regatta_id
            FROM results r
            JOIN classes c ON r.class_id = c.class_id
            JOIN regattas reg ON r.regatta_id = reg.regatta_id
            WHERE c.class_name IN ('Optimist', 'Optimist A', 'Optimist B', 'Optimist C')
              AND r.sail_number IS NOT NULL AND r.sail_number != ''
              AND r.sail_number ~ '[0-9]'
              AND r.sail_number !~ '[/,]'
              AND LENGTH(REGEXP_REPLACE(r.sail_number, '[^0-9]', '', 'g')) BETWEEN 1 AND 4
        ),
        last_race AS (
            SELECT DISTINCT ON (sail_norm)
                sail_norm, helm_name, class_name,
                start_date as last_race_date, event_name as last_event, regatta_id
            FROM normalized_sails
            ORDER BY sail_norm, start_date DESC
        ),
        helm_valid_fleet AS (
            SELECT DISTINCT ON (helm_name)
                helm_name, class_name as valid_fleet
            FROM normalized_sails
            WHERE class_name IN ('Optimist A', 'Optimist B', 'Optimist C')
            ORDER BY helm_name, start_date DESC
        ),
        race_counts AS (
            SELECT sail_norm, COUNT(*) as total_results
            FROM normalized_sails GROUP BY sail_norm
        )
        SELECT 
            lr.sail_norm as sail_number,
            lr.helm_name,
            CASE WHEN lr.class_name = 'Optimist' 
                 THEN COALESCE(hvf.valid_fleet, 'Optimist C')
                 ELSE lr.class_name END as current_fleet,
            lr.last_race_date::text,
            lr.last_event,
            lr.regatta_id,
            rc.total_results
        FROM last_race lr
        LEFT JOIN helm_valid_fleet hvf ON lr.helm_name = hvf.helm_name
        JOIN race_counts rc ON lr.sail_norm = rc.sail_norm
        ORDER BY CASE WHEN lr.sail_norm ~ '^[0-9]+$' 
                      THEN LPAD(lr.sail_norm, 10, '0') ELSE lr.sail_norm END
    """)
    
    boats = cur.fetchall()
    fleet_counts = {'Optimist A': 0, 'Optimist B': 0, 'Optimist C': 0}
    for b in boats:
        fleet = b['current_fleet']
        if fleet in fleet_counts:
            fleet_counts[fleet] += 1
    
    cur.close()
    conn.close()
    return {"total": len(boats), "fleet_counts": fleet_counts, "boats": [dict(b) for b in boats]}


