@app.get("/api/ilca-family")
def api_ilca_family():
    """Master list of all ILCA boats with last race info"""
    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    
    cur.execute("""
        WITH normalized_sails AS (
            SELECT 
                UPPER(TRIM(REGEXP_REPLACE(r.sail_number, '^RSA\\s*', '', 'i'))) as sail_norm,
                r.helm_name,
                c.class_name,
                reg.start_date,
                reg.event_name,
                reg.regatta_id
            FROM results r
            JOIN classes c ON r.class_id = c.class_id
            JOIN regattas reg ON r.regatta_id = reg.regatta_id
            WHERE c.class_name IN ('Ilca 4.7', 'Ilca 6', 'Ilca 7')
              AND r.sail_number IS NOT NULL AND r.sail_number != ''
              AND r.sail_number ~ '[0-9]'
              AND r.sail_number !~ '[/,]'
              AND LENGTH(REGEXP_REPLACE(r.sail_number, '[^0-9]', '', 'g')) BETWEEN 1 AND 6
        ),
        last_race AS (
            SELECT DISTINCT ON (sail_norm)
                sail_norm, helm_name, class_name,
                start_date as last_race_date, event_name as last_event, regatta_id
            FROM normalized_sails
            ORDER BY sail_norm, start_date DESC
        ),
        race_counts AS (
            SELECT sail_norm, COUNT(*) as total_results
            FROM normalized_sails GROUP BY sail_norm
        )
        SELECT 
            lr.sail_norm as sail_number,
            lr.helm_name,
            lr.class_name as current_class,
            lr.last_race_date::text,
            lr.last_event,
            lr.regatta_id,
            rc.total_results
        FROM last_race lr
        JOIN race_counts rc ON lr.sail_norm = rc.sail_norm
        ORDER BY CASE WHEN lr.sail_norm ~ '^[0-9]+$' 
                      THEN LPAD(lr.sail_norm, 10, '0') ELSE lr.sail_norm END
    """)
    
    boats = cur.fetchall()
    class_counts = {'Ilca 4.7': 0, 'Ilca 6': 0, 'Ilca 7': 0}
    for b in boats:
        cls = b['current_class']
        if cls in class_counts:
            class_counts[cls] += 1
    
    cur.close()
    conn.close()
    return {"total": len(boats), "class_counts": class_counts, "boats": [dict(b) for b in boats]}


